{"command":"cat > src/lua_values.py <<'PY'
import math
import re

INT_MIN = -(1 << 63)
INT_MAX = (1 << 63) - 1
MASK64 = (1 << 64) - 1

_addr_counter = [0x550000000000]

def next_addr():
    _addr_counter[0] += 0x2b0
    return _addr_counter[0]

def wrap_int(x):
    x &= MASK64
    if x >= (1 << 63):
        x -= (1 << 64)
    return x

def is_int(v):
    return type(v) is int

def is_float(v):
    return type(v) is float

def is_number(v):
    return type(v) is int or type(v) is float

def lua_type(v):
    if v is None:
        return "nil"
    t = type(v)
    if t is bool:
        return "boolean"
    if t is int or t is float:
        return "number"
    if t is bytes:
        return "string"
    if isinstance(v, LuaTable):
        return "table"
    if isinstance(v, (LuaClosure, BuiltinFunction)):
        return "function"
    if isinstance(v, UserData):
        return "userdata"
    if isinstance(v, LuaThreadObj):
        return "thread"
    return "userdata"

class LuaError(Exception):
    def __init__(self, value, located=False):
        super().__init__(repr(value))
        self.value = value
        self.located = located
        self.snapshot = None  # list of frame-info dicts, innermost first

class Cell:
    __slots__ = ("value",)
    def __init__(self, value=None):
        self.value = value

class Var:
    _next = [0]
    __slots__ = ("name", "id", "const", "close", "kind", "line")
    def __init__(self, name, const=False, close=False, kind="local", line=0):
        Var._next[0] += 1
        self.id = Var._next[0]
        self.name = name  # bytes
        self.const = const or close
        self.close = close
        self.kind = kind
        self.line = line
    def __repr__(self):
        return "<Var %r#%d>" % (self.name, self.id)

class Proto:
    __slots__ = ("params", "is_vararg", "body", "upvalues", "source",
                 "linedefined", "lastlinedefined", "locals_info", "name_hint")
    def __init__(self):
        self.params = []          # list[Var]
        self.is_vararg = False
        self.body = None          # block stmt node
        self.upvalues = []        # list[Var] from enclosing functions
        self.source = b""         # chunkname as given (source id)
        self.linedefined = 0
        self.lastlinedefined = 0
        self.locals_info = []     # list of Var declared (for debug), in decl order
        self.name_hint = None

class LuaClosure:
    __slots__ = ("proto", "upvalue_cells", "addr", "_metatable")
    def __init__(self, proto, upvalue_cells):
        self.proto = proto
        self.upvalue_cells = upvalue_cells  # dict varid->Cell, ordered like proto.upvalues
        self.addr = next_addr()
        self._metatable = None
    def env_cell(self):
        # first upvalue if it is _ENV; used by load/xpcall semantics minimally
        if self.proto.upvalues and self.proto.upvalues[0].name == b"_ENV":
            return self.upvalue_cells.get(self.proto.upvalues[0].id)
        return None

class BuiltinFunction:
    __slots__ = ("name", "func", "addr", "yieldable")
    def __init__(self, name, func, yieldable=True):
        self.name = name  # bytes qualified name e.g. b"string.format" or b"print"
        self.func = func  # callable(interp, args) -> list
        self.addr = next_addr()
        self.yieldable = yieldable

class UserData:
    __slots__ = ("metatable", "addr", "uservalue", "data")
    def __init__(self):
        self.metatable = None
        self.addr = next_addr()
        self.uservalue = None
        self.data = None

class FileUserData(UserData):
    __slots__ = ("file", "closed", "is_popen", "mode", "name")
    def __init__(self, fileobj, name=b"", is_popen=False, mode=b"r"):
        super().__init__()
        self.file = fileobj
        self.closed = False
        self.is_popen = is_popen
        self.mode = mode
        self.name = name
        # FILE* addresses look like libc heap pointers in original output
        self.addr = 0x7f0000000000 + (next_addr() & 0xffffff)

class LuaThreadObj:
    __slots__ = ("addr", "status", "func", "pythread", "cond", "resume_args",
                 "yield_values", "return_values", "error_value", "started",
                 "close_requested", "frames", "is_main", "waiting", "resumer_waiting",
                 "close_result", "hook", "hook_mask", "hook_count")
    def __init__(self, func=None, is_main=False):
        import threading
        self.addr = next_addr()
        self.status = "suspended" if not is_main else "running"
        self.func = func
        self.pythread = None
        self.cond = threading.Condition()
        self.resume_args = None
        self.yield_values = None
        self.return_values = None
        self.error_value = None
        self.started = False
        self.close_requested = False
        self.frames = []
        self.is_main = is_main
        self.waiting = False
        self.resumer_waiting = False
        self.close_result = None
        self.hook = None
        self.hook_mask = 0
        self.hook_count = 0

def normalize_key(key):
    """Return hashable normalized key, or raise ValueError(msg)."""
    if key is None:
        raise ValueError("table index is nil")
    t = type(key)
    if t is bool:
        return (0, key)
    if t is int:
        return (1, key)
    if t is float:
        if math.isnan(key):
            raise ValueError("table index is NaN")
        if key == math.floor(key) and INT_MIN <= key <= INT_MAX:
            return (1, int(key))
        return (2, key)
    if t is bytes:
        return (3, key)
    # objects by identity
    return (4, id(key))

def storage_key(key):
    """Key as it should be reported by pairs etc."""
    if type(key) is float:
        if key == math.floor(key) and INT_MIN <= key <= INT_MAX:
            return int(key)
    return key

class LuaTable:
    __slots__ = ("map", "order", "metatable", "addr")
    def __init__(self):
        self.map = {}      # nk -> [orig_key, value]
        self.order = []    # nks in insertion order (kept after deletion)
        self.metatable = None
        self.addr = next_addr()

    def rawget(self, key):
        if key is None:
            return None
        try:
            nk = normalize_key(key)
        except ValueError:
            return None
        e = self.map.get(nk)
        return e[1] if e is not None else None

    def rawset(self, key, value):
        nk = normalize_key(key)  # raises ValueError
        if value is None:
            if nk in self.map:
                del self.map[nk]
            return
        e = self.map.get(nk)
        if e is None:
            self.map[nk] = [storage_key(key), value]
            if nk not in self._orderset():
                self.order.append(nk)
        else:
            e[1] = value

    def _orderset(self):
        # small optimization not worth maintaining a set slot; order len usually ok
        return set(self.order)

    def get_int(self, i):
        e = self.map.get((1, i))
        return e[1] if e is not None else None

    def border(self):
        # contiguous prefix (a valid border)
        n = 0
        m = self.map
        while (1, n + 1) in m:
            n += 1
        return n

    def ordered_entries(self):
        """Entries in pairs order: positive ints ascending first, then others
        in insertion order."""
        ints = []
        others = []
        for nk, e in self.map.items():
            if nk[0] == 1 and nk[1] >= 1:
                ints.append((nk[1], e))
        ints.sort(key=lambda x: x[0])
        seen = set()
        result = []
        for _, e in ints:
            result.append(e)
        pos_int_nks = set((1, i) for i, _ in ints)
        for nk in self.order:
            if nk in pos_int_nks or nk in seen:
                continue
            seen.add(nk)
            e = self.map.get(nk)
            if e is not None:
                result.append(e)
        # any keys not in order list (shouldn't happen)
        for nk, e in self.map.items():
            if nk not in pos_int_nks and nk not in seen:
                result.append(e)
        return result

    def lua_next(self, key):
        """Return (k, v) after key, or None at end. Raise ValueError for bad key."""
        if key is None:
            entries = self.ordered_entries()
            if not entries:
                return None
            return (entries[0][0], entries[0][1])
        nk = normalize_key(key)
        entries = self.ordered_entries()
        # Try to find key in current entries
        for i, e in enumerate(entries):
            try:
                enk = normalize_key(e[0])
            except ValueError:
                continue
            if enk == nk:
                if i + 1 < len(entries):
                    ne = entries[i + 1]
                    return (ne[0], ne[1])
                return None
        # Key not currently present: if positive int, find next present int > it,
        # else first non-int; if in insertion order history, scan after it.
        if nk[0] == 1 and nk[1] >= 1 and nk in set(self.order):
            best = None
            for e in entries:
                ek = e[0]
                if type(ek) is int and ek > nk[1]:
                    if best is None or ek < best[0]:
                        best = e
            if best is not None:
                return (best[0], best[1])
            for e in entries:
                if not (type(e[0]) is int and e[0] >= 1):
                    return (e[0], e[1])
            return None
        if nk in set(self.order):
            idx = self.order.index(nk)
            for onk in self.order[idx + 1:]:
                if onk[0] == 1 and onk[1] >= 1:
                    continue
                e = self.map.get(onk)
                if e is not None:
                    return (e[0], e[1])
            return None
        raise ValueError("invalid key to 'next'")

# ---------------- numbers ----------------

def float_to_bytes(x):
    if math.isnan(x):
        return b"-nan" if math.copysign(1.0, x) < 0 else b"nan"
    if math.isinf(x):
        return b"-inf" if x < 0 else b"inf"
    s = format(x, ".14g")
    try:
        back = float(s)
    except ValueError:
        back = None
    if back != x or (x == 0.0 and math.copysign(1.0, back) != math.copysign(1.0, x)):
        s = format(x, ".17g")
    # %g in Python may produce e.g. '1e-05' (ok) or 'e+15'; ensure exponent form
    # matches C: exponent at least two digits (Python already does two).
    if not any(c in s for c in ".eEnN"):  # looks like integer
        s += ".0"
    return s.encode("ascii")

def int_to_bytes(x):
    return str(x).encode("ascii")

def number_to_bytes(x):
    if type(x) is int:
        return int_to_bytes(x)
    return float_to_bytes(x)

_HEX_DIGITS = set(b"0123456789abcdefABCDEF")

def parse_number_string(s):
    """Parse a bytes string as a Lua number (str2number). Return int/float or None."""
    if type(s) is not bytes:
        return None
    t = s.strip(b" \t\n\v\f\r")
    if not t:
        return None
