    except ValueError:
        return None

def to_integer_value(v):
    """Convert like lua_tointegerx with string coercion disabled for pure numbers;
    Return int or None. Numbers only (int/float with integral value)."""
    if type(v) is int:
        return v
    if type(v) is float:
        if math.isnan(v) or math.isinf(v):
            return None
        if v == math.floor(v) and INT_MIN <= v <= 9223372036854775807.0:
            # float(INT_MAX) rounds to 2^63; handled by range below
            if v < 9223372036854775808.0:
                return int(v)
        return None
    return None

def number_to_float(v):
    if type(v) is int:
        return float(v)
    return v

def truthy(v):
    return v is not None and v is not False

def short_source(source):
    """Compute short_src like Lua: source is bytes chunkname as given to load."""
    if not source:
        return b"?"
    if source[:1] == b"@":
        s = source[1:]
        if len(s) > 60:
            s = b"..." + s[-57:]
        return s
    if source[:1] == b"=":
        return source[1:]
    # string source: first line
    line = source.split(b"\n", 1)[0]
    if source[:1] == b"\x1b":
        return b"binary string"
    if len(line) > 45:
        line = line[:45]
        return b'[string "' + line + b'..."]'
    return b'[string "' + line + b'"]'

def source_display_for_error(source):
    return short_source(source)
