def encode_utf8(cp):
    if cp < 0x80:
        return bytes([cp])
    elif cp < 0x800:
        return bytes([0xC0 | (cp >> 6), 0x80 | (cp & 0x3F)])
    elif cp < 0x10000:
        return bytes([0xE0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)])
    elif cp < 0x200000:
        return bytes([0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3F),
                      0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)])
    elif cp < 0x4000000:
        return bytes([0xF8 | (cp >> 24), 0x80 | ((cp >> 18) & 0x3F),
                      0x80 | ((cp >> 12) & 0x3F), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)])
    else:
        return bytes([0xFC | (cp >> 30), 0x80 | ((cp >> 24) & 0x3F), 0x80 | ((cp >> 18) & 0x3F),
                      0x80 | ((cp >> 12) & 0x3F), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)])

def token_raw(tok):
    return _raw_by_id.get(id(tok))
