from lua_lexer import Lexer, LexError, token_raw
from lua_values import Var, Proto

class ParseError(Exception):
    def __init__(self, msg, line):
        if isinstance(msg, str):
            msg = msg.encode("latin1")
        super().__init__(msg)
        self.msg = msg
        self.line = line

class GlobalBinding:
    __slots__ = ("name", "const")
    def __init__(self, name, const=False):
        self.name = name
        self.const = const

class BlockScope:
    __slots__ = ("func", "bindings", "labels", "gotos", "is_loop",
                 "has_global", "global_all", "local_decls", "stmt_index")
    def __init__(self, func, is_loop=False):
        self.func = func
        self.bindings = {}   # name -> Var or GlobalBinding
        self.labels = {}     # name -> (label_id, index, line)
        self.gotos = []      # dicts
        self.is_loop = is_loop
        self.has_global = False
        self.global_all = None   # None=no wildcard; True=const wildcard; False=plain
        self.local_decls = []    # (name, stmt_index, var) vars declared in this block
        self.stmt_index = 0

class FuncCtx:
    __slots__ = ("proto", "parent")
    def __init__(self, proto, parent):
        self.proto = proto
        self.parent = parent

BLOCK_FOLLOW = set([b"else", b"elseif", b"end", b"until", "eof"])

class Parser:
    def __init__(self, data, source):
        self.lexer = Lexer(data, source)
        self.source = source
        self.tok = self.lexer.next()
        self.scopes = []
        self.funcs = []
        self._label_counter = 0
        self.main_proto = None
        self.env_var = None

    # ---------- token helpers ----------
    def advance(self):
        t = self.tok
        self.tok = self.lexer.next()
        return t

    def check(self, typ):
        return self.tok.type == typ

    def accept(self, typ):
        if self.tok.type == typ:
            self.advance()
            return True
        return False

    def tok_display(self, tok=None):
        tok = tok or self.tok
        if tok.type == "eof":
            return "<eof>"
        if tok.type == "name":
            return "'" + tok.value.decode("latin1") + "'"
        if tok.type == "string":
            s = tok.value.decode("latin1")
            return "'\"" + s + "\"'"
        if tok.type == "number":
            raw = token_raw(tok)
            if raw is None:
                raw = str(tok.value).encode()
            return "'" + raw.decode("latin1") + "'"
        if isinstance(tok.type, bytes):
            return "'" + tok.type.decode("latin1") + "'"
        return "'" + str(tok.type) + "'"

    def error(self, msg, line=None, near_tok=True):
        if line is None:
            line = self.tok.line
        if near_tok:
            msg = msg + " near " + self.tok_display()
        raise ParseError(msg, line)

    def expect(self, typ, what=None):
        if self.tok.type != typ:
            if what is None:
                what = "'" + (typ.decode("latin1") if isinstance(typ, bytes) else str(typ)) + "'"
            self.error(what + " expected")
        return self.advance()

    def expect_name(self):
        if self.tok.type != "name":
            self.error("<name> expected")
        t = self.advance()
        return t.value, t.line

    # ---------- scopes ----------
    def push_scope(self, is_loop=False):
        s = BlockScope(self.funcs[-1], is_loop=is_loop)
        self.scopes.append(s)
        return s

    def pop_scope(self):
        s = self.scopes.pop()
        self._check_gotos(s)
        return s

    def _check_gotos(self, scope):
        for g in scope.gotos:
            name = g["name"]
            if name in scope.labels:
                # check jumps into scope of local
                lid, lidx, lline = scope.labels[name]
                g["label_id"] = lid
                goto_stmt_index = g["index"]
                # if label is at end of block, locals out of scope there
                is_last = g.get("block_len") is not None and lidx >= g["block_len"] - 1
                # We'll compute block_len at check time if set in scope
