                is_end_label = (scope.stmt_index and lidx == scope.stmt_index - 1 and
                                g.get("label_at_end", False))
                if not g.get("label_at_end"):
                    for (lname, didx, lvar) in scope.local_decls:
                        if goto_stmt_index < didx < lidx or (goto_stmt_index < didx and lidx > didx):
                            # if goto before declaration and label after declaration
                            if goto_stmt_index < didx <= lidx:
                                raise ParseError(
                                    ("<goto %s> at line %d jumps into the scope of '%s'" %
                                     (name.decode("latin1"), g["line"], lname.decode("latin1"))).encode("latin1"),
                                    g["line"])
                g["resolved"] = True
            else:
