                    # find parent scope still on stack (pop already removed current)
                    parent = None
                    for s in reversed(self.scopes):
                        if s.func is scope.func:
                            parent = s
                            break
                        else:
                            break
                    if parent is not None:
                        parent.gotos.append(g)
                    else:
                        raise ParseError(
                            ("no visible label '%s' for <goto> at line %d" %
                             (name.decode("latin1"), g["line"])).encode("latin1"),
