    def current_func(self):
        return self.funcs[-1]

    def add_upvalues_for(self, var, owner_func):
        # funcs list: find index of owner
        idxs = {id(f): i for i, f in enumerate(self.funcs)}
        oi = idxs.get(id(owner_func))
        if oi is None:
            return
        for j in range(oi + 1, len(self.funcs)):
            proto = self.funcs[j].proto
            if all(v.id != var.id for v in proto.upvalues):
                proto.upvalues.append(var)

    def find_binding(self, name):
        for s in reversed(self.scopes):
            if name in s.bindings:
                return s.bindings[name], s
        return None, None

    def resolve_env_var(self, access_name, line):
        """Return (Var, kind) for _ENV, or raise the _ENV-is-global error."""
        for s in reversed(self.scopes):
            if b"_ENV" in s.bindings:
                b = s.bindings[b"_ENV"]
                if isinstance(b, GlobalBinding):
                    raise ParseError(
                        ("_ENV is global when accessing variable '%s'" %
                         access_name.decode("latin1")).encode("latin1"), line)
                # Var
                if s.func is self.current_func():
                    kind = "local" if b is not self.env_var else "upvalue"
                    # _ENV var of main chunk is an upvalue; locals named _ENV are local
                    if b.kind == "env":
                        kind = "upvalue"
                    return b, kind
                else:
                    self.add_upvalues_for(b, s.func)
                    return b, "upvalue"
        # Should not happen for chunks; create reference to main env var
        return self.env_var, "upvalue"

    def resolve_name(self, name, line):
        """Return expression node for reading a name."""
        b, s = self.find_binding(name)
        if b is not None:
            if isinstance(b, GlobalBinding):
                if name == b"_ENV":
                    raise ParseError(
                        b"_ENV is global when accessing variable '_ENV'", line)
                env_var, env_kind = self.resolve_env_var(name, line)
                return ("globalvar", line, name, env_var, env_kind, b.const)
            # Var
            if s.func is self.current_func():
                if b.kind == "env":
                    return ("var", line, b, "upvalue")
                return ("var", line, b, "local")
            self.add_upvalues_for(b, s.func)
            return ("var", line, b, "upvalue")
        # not bound -> global if allowed
        if name == b"_ENV":
            # _ENV should always be bound in main chunk; fall through to env var
            return ("var", line, self.env_var, "upvalue")
        const = self._global_allowed(name, line)
        env_var, env_kind = self.resolve_env_var(name, line)
        return ("globalvar", line, name, env_var, env_kind, const)

    def _global_allowed(self, name, line):
        """Return const flag for undeclared global, or raise not declared."""
        for s in reversed(self.scopes):
            if s.global_all is not None:
                return s.global_all
        for s in self.scopes:
            if s.has_global:
                raise ParseError(
                    ("variable '%s' not declared" % name.decode("latin1")).encode("latin1"), line)
        return False

    def declare_local(self, var):
        scope = self.scopes[-1]
        scope.bindings[var.name] = var
        scope.local_decls.append((var.name, scope.stmt_index, var))
        self.current_func().proto.locals_info.append(var)

    def add_local_binding_only(self, var):
        self.scopes[-1].bindings[var.name] = var

    # ---------- top level ----------
    def parse_chunk(self):
        proto = Proto()
        proto.is_vararg = True
        proto.source = self.source
        proto.linedefined = 0
        proto.lastlinedefined = 0
        self.main_proto = proto
        ctx = FuncCtx(proto, None)
        self.funcs.append(ctx)
        # base scope with _ENV
        base = BlockScope(ctx)
        self.env_var = Var(b"_ENV", kind="env", line=0)
        base.bindings[b"_ENV"] = self.env_var
        proto.upvalues.append(self.env_var)
        self.scopes.append(base)
        body = self.parse_block(top=True)
        if self.tok.type != "eof":
            # Block follow tokens at top: error expected eof
            self.error("<eof> expected")
        proto.body = body
        # pop scopes (check gotos)
        self.pop_scope()  # body block scope already popped? parse_block manages its scope
        # At this point only base should be removed manually without checks interfering
        return proto

    # block parsing: creates and pops its own scope (except repeat special handling)
    def parse_block(self, top=False, is_loop=False, scope=None, keep_scope=False):
        owns = False
        if scope is None:
            scope = self.push_scope(is_loop=is_loop)
            owns = True
        stmts = []
        labels_snapshot = {}
        while True:
            if self.tok.type == "eof" or self.tok.type in (b"end", b"else", b"elseif", b"until"):
                break
            if self.tok.type == b"return":
                stmts.append(self.parse_return())
                # after return, only block follow allowed (optional ';' handled in parse_return)
                break
            scope.stmt_index = len(stmts)
            st = self.parse_statement()
            scope.stmt_index = len(stmts)
            if st is not None:
                stmts.append(st)
        # mark labels at end
        for name, (lid, idx, ln) in scope.labels.items():
            if idx == len(stmts) - 1:
                for g in scope.gotos:
                    if g["name"] == name:
                        g["label_at_end"] = True
        block = ("block", stmts[0][1] if stmts else self.tok.line, stmts,
                 dict(scope.labels))
        if owns and not keep_scope:
            self.pop_scope()
        return block

    def parse_return(self):
        line = self.advance().line  # return
        exps = []
        if not (self.tok.type == "eof" or self.tok.type in (b"end", b"else", b"elseif", b"until", b";")):
            exps = self.parse_explist()
        self.accept(b";")
        return ("return", line, exps)

    # ---------- statements ----------
    def parse_statement(self):
        t = self.tok.type
        line = self.tok.line
        if t == b";":
            self.advance()
            return ("empty", line)
        elif t == b"do":
            self.advance()
            blk = self.parse_block()
            self.expect(b"end")
            return ("do", line, blk)
        elif t == b"while":
            self.advance()
            cond = self.parse_exp()
            self.expect(b"do")
            blk = self.parse_block(is_loop=True)
            self.expect(b"end")
            return ("while", line, cond, blk)
        elif t == b"repeat":
            self.advance()
            scope = self.push_scope(is_loop=True)
            blk_stmts_scope = scope
            blk = self.parse_block(scope=scope, keep_scope=True)
            self.expect(b"until")
            cond = self.parse_exp()  # locals of block visible
            self.pop_scope()
            return ("repeat", line, blk, cond)
        elif t == b"if":
            return self.parse_if()
        elif t == b"for":
            return self.parse_for()
        elif t == b"function":
            return self.parse_function_stmt()
        elif t == b"local":
            return self.parse_local()
        elif t == b"global":
            return self.parse_global()
        elif t == b"break":
            self.advance()
            # validate inside loop in current function
            inloop = False
            for s in reversed(self.scopes):
                if s.func is not self.current_func():
                    break
                if s.is_loop:
                    inloop = True
                    break
            if not inloop:
                raise ParseError(b"break outside loop near 'break'", line)
            return ("break", line)
        elif t == b"goto":
            self.advance()
            name, nline = self.expect_name()
            scope = self.scopes[-1]
            g = {"name": name, "line": line, "index": scope.stmt_index,
                 "label_id": None, "resolved": False}
            # if label already defined in a visible scope (same func), record id immediately
            lid = None
            for s in reversed(self.scopes):
                if s.func is not self.current_func():
                    break
                if name in s.labels:
                    lid = s.labels[name][0]
                    break
            if lid is not None:
                g["label_id"] = lid
                g["outer_visible"] = True
                return ("goto", line, name, lid)
            scope.gotos.append(g)
            # placeholder; id filled via dict ref in g? We need mutable node:
            node = ["goto", line, name, None]
            g["node"] = node
            return node
        elif t == b"::":
            self.advance()
            name, nline = self.expect_name()
            self.expect(b"::")
            scope = self.scopes[-1]
            if name in scope.labels:
                raise ParseError(
                    ("label '%s' already defined on line %d" %
                     (name.decode("latin1"), scope.labels[name][2])).encode("latin1"), line)
            self._label_counter += 1
            lid = self._label_counter
            scope.labels[name] = (lid, scope.stmt_index, line)
            return ("label", line, name, lid)
        elif t == b"return":
            # handled in block
            return self.parse_return()
        else:
            return self.parse_expr_statement()

    def parse_if(self):
        line = self.advance().line  # if
        branches = []
        cond = self.parse_exp()
        self.expect(b"then")
        blk = self.parse_block()
        branches.append((cond, blk))
        elseblk = None
        while self.tok.type == b"elseif":
            self.advance()
            c = self.parse_exp()
            self.expect(b"then")
            b = self.parse_block()
            branches.append((c, b))
        if self.tok.type == b"else":
            self.advance()
            elseblk = self.parse_block()
        self.expect(b"end")
        return ("if", line, branches, elseblk)

    def parse_for(self):
        line = self.advance().line  # for
        name, nline = self.expect_name()
        if self.tok.type == b"=":
            self.advance()
            start = self.parse_exp()
            self.expect(b",")
            limit = self.parse_exp()
            step = None
            if self.accept(b","):
                step = self.parse_exp()
            self.expect(b"do")
            var = Var(name, const=True, kind="local", line=nline)
            scope = self.push_scope(is_loop=True)
            scope.bindings[name] = var
            scope.local_decls.append((name, 0, var))
            self.current_func().proto.locals_info.append(var)
            blk = self.parse_block(scope=scope, keep_scope=True)
            self.pop_scope()
            self.expect(b"end")
            return ("fornum", line, var, start, limit, step, blk)
        elif self.tok.type in (b",", b"in"):
            names = [(name, nline)]
            while self.accept(b","):
                n2, l2 = self.expect_name()
                names.append((n2, l2))
            self.expect(b"in")
            exps = self.parse_explist()
            self.expect(b"do")
            vars = []
            scope = self.push_scope(is_loop=True)
            for (nm, ln) in names:
                v = Var(nm, const=True, kind="local", line=ln)
                vars.append(v)
                scope.bindings[nm] = v
                scope.local_decls.append((nm, 0, v))
                self.current_func().proto.locals_info.append(v)
            blk = self.parse_block(scope=scope, keep_scope=True)
            self.pop_scope()
            self.expect(b"end")
            return ("forgen", line, vars, exps, blk)
        else:
            self.error("'=' or 'in' expected")

    def parse_attrib(self):
        # current tok is '<'
        line = self.tok.line
        self.advance()  # <
        if self.tok.type != "name":
            self.error("<name> expected")
        aname = self.advance().value
        if self.tok.type != b">":
            self.error("'>' expected")
        self.advance()  # >
        if aname not in (b"const", b"close"):
            raise ParseError(("unknown attribute '%s'" % aname.decode("latin1")).encode("latin1"), line)
        return aname

    def parse_namelist_attribs(self):
        """Parse [attrib] name [attrib] {, name [attrib]}. Return list of (name,line,attr)."""
        prefix = None
        if self.tok.type == b"<":
            prefix = self.parse_attrib()
        result = []
        while True:
            name, nline = self.expect_name()
            attr = prefix
            if self.tok.type == b"<":
                attr = self.parse_attrib()
            result.append((name, nline, attr))
            if not self.accept(b","):
                break
        return result, prefix

    def parse_local(self):
        line = self.advance().line  # local
        if self.tok.type == b"function":
            self.advance()
            name, nline = self.expect_name()
            var = Var(name, kind="local", line=nline)
            self.declare_local(var)
            proto = self.parse_function_body(line, is_method=False)
            return ("localfunc", line, var, proto)
        namelist, prefix = self.parse_namelist_attribs()
        vars = []
        closes = 0
        for (name, nline, attr) in namelist:
            is_close = attr == b"close"
            is_const = attr == b"const"
            if is_close:
                closes += 1
            vars.append(Var(name, const=is_const, close=is_close, kind="local", line=nline))
        if closes > 1:
            raise ParseError(b"multiple to-be-closed variables in local list", line)
        exps = []
        if self.accept(b"="):
            exps = self.parse_explist()
        else:
            # after namelist, if next starts expression statement? Lua errors "syntax error"
            if self.tok.type == "name" or (isinstance(self.tok.type, bytes) and self.tok.type not in (b";", b"end", b"else", b"elseif", b"until")):
                # e.g. local x y -> syntax error near <eof>? handled generically by next statement?
                pass
        for v in vars:
            self.declare_local(v)
        return ("local", line, vars, exps)

    def parse_global(self):
        line = self.advance().line  # global
        if self.tok.type == b"function":
            self.advance()
            name, nline = self.expect_name()
            scope = self.scopes[-1]
            scope.bindings[name] = GlobalBinding(name, False)
            scope.has_global = True
            env_var, env_kind = self.resolve_env_var(name, line)
            proto = self.parse_function_body(line, is_method=False)
            return ("globalfunc", line, name, proto, env_var, env_kind)
        # optional prefix attrib
        prefix = None
        prefix_line = line
        if self.tok.type == b"<":
            prefix_line = self.tok.line
            prefix = self.parse_attrib()
        if self.tok.type == b"*":
            self.advance()
            if prefix == b"close":
                raise ParseError(b"global variables cannot be to-be-closed", line)
            scope = self.scopes[-1]
            scope.global_all = (prefix == b"const")
            scope.has_global = True
            return ("empty", line)
        # namelist (prefix already consumed; parse manually)
        namelist = []
        while True:
            name, nline = self.expect_name()
            attr = prefix
            if self.tok.type == b"<":
                attr = self.parse_attrib()
            namelist.append((name, nline, attr))
            if not self.accept(b","):
                break
        for (name, nline, attr) in namelist:
            if attr == b"close":
                raise ParseError(b"global variables cannot be to-be-closed", line)
        exps = None
        if self.accept(b"="):
            exps = self.parse_explist()
        # env var resolved BEFORE adding bindings (so defining _ENV itself works);
        # but if exps exist we need runtime env. Resolve relative to first name for errors.
        env_var = env_kind = None
        if exps is not None:
            env_var, env_kind = self.resolve_env_var(namelist[0][0], line)
        scope = self.scopes[-1]
        for (name, nline, attr) in namelist:
            scope.bindings[name] = GlobalBinding(name, attr == b"const")
        scope.has_global = True
        names = [n for (n, _, _) in namelist]
        return ("global", line, names, exps, env_var, env_kind)

    def parse_function_stmt(self):
        line = self.advance().line  # function
        # funcname: Name { '.' Name } [':' Name]
        name, nline = self.expect_name()
        base_node = self.resolve_name(name, nline)
        dotted = False
        while self.tok.type == b".":
            self.advance()
            fname, fline = self.expect_name()
            base_node = ("index", fline, base_node, ("string", fline, fname), fname)
            dotted = True
        is_method = False
        if self.tok.type == b":":
            self.advance()
            fname, fline = self.expect_name()
            base_node = ("index", fline, base_node, ("string", fline, fname), fname)
            is_method = True
            dotted = True
        if not dotted:
            # assignment target: check const
            self._check_assignable(base_node, line)
        proto = self.parse_function_body(line, is_method=is_method)
        fexp = ("function", line, proto)
        return ("assign", line, [base_node], [fexp])

    def _check_assignable(self, node, line):
        if node[0] == "var":
            if node[2].const:
                raise ParseError(("attempt to assign to const variable '%s'" %
                                  node[2].name.decode("latin1")).encode("latin1"), line)
        elif node[0] == "globalvar":
            if node[5]:
                raise ParseError(("attempt to assign to const variable '%s'" %
                                  node[2].decode("latin1")).encode("latin1"), line)
        elif node[0] == "index":
            pass
        else:
            # syntax error near current token
            self.error("syntax error", line=line)

    def parse_function_body(self, line, is_method=False):
        proto = Proto()
        proto.source = self.source
        proto.linedefined = line
        parent = self.funcs[-1] if self.funcs else None
        ctx = FuncCtx(proto, parent)
        self.funcs.append(ctx)
        # function var scope for parameters
        pscope = self.push_scope()
        self.expect(b"(")
        params = []
        vararg_var = None
        if self.tok.type != b")":
            while True:
                if self.tok.type == "name":
                    nm, ln = self.expect_name()
                    v = Var(nm, kind="local", line=ln)
                    params.append(v)
                    pscope.bindings[nm] = v
                    proto.locals_info.append(v)
                elif self.tok.type == b"...":
                    vline = self.advance().line
                    proto.is_vararg = True
                    if self.tok.type == "name":
                        nm, ln = self.expect_name()
                        vararg_var = Var(nm, const=True, kind="local", line=ln)
                        pscope.bindings[nm] = vararg_var
                        proto.locals_info.append(vararg_var)
                    break
                else:
                    self.error("<name> or '...' expected")
                if not self.accept(b","):
                    break
        if is_method:
            selfv = Var(b"self", kind="local", line=line)
            params.insert(0, selfv)
            # self binding should be first param but not shadow explicit later params?
            # Bindings: explicit params parsed already; rebind order: self first, then params override if named self.
            # Rebuild: remove then set
            if b"self" not in pscope.bindings:
                pscope.bindings[b"self"] = selfv
                proto.locals_info.insert(0, selfv)
            else:
                # explicit param named self shadows implicit; but implicit occupies slot 1.
                # Keep implicit var first in locals_info ordering approximations:
                proto.locals_info = [selfv] + [v for v in proto.locals_info if v is not selfv]
        proto.params = params
        proto.vararg_var = vararg_var
        self.expect(b")")
        body = self.parse_block()
        endline = self.tok.line
        self.expect(b"end")
        proto.lastlinedefined = endline
        proto.body = body
        # pop param scope
        self.pop_scope()
        self.funcs.pop()
        return proto

    def parse_expr_statement(self):
        line = self.tok.line
        # Statements starting with expression must be call or assignment.
        # If token cannot start prefixexp, report unexpected symbol (except block follows handled)
        if not (self.tok.type == "name" or self.tok.type == b"("):
            # keywords that are block follows should be handled by caller; others unexpected
            if self.tok.type in (b"then",):
                self.error("unexpected symbol")
            self.error("unexpected symbol")
        first = self.parse_suffixed_exp()
        if self.tok.type in (b"=", b","):
            targets = [first]
            while self.accept(b","):
                targets.append(self.parse_suffixed_exp())
            for tg in targets:
                self._check_assignable(tg, tg[1])
            self.expect(b"=")
            exps = self.parse_explist()
            return ("assign", line, targets, exps)
        # must be a call
        if first[0] not in ("call", "mcall"):
            # syntax error near next token (or <eof>)
            self.error("syntax error")
        return ("callstmt", line, first)

    # ---------- expressions ----------
    def parse_explist(self):
        exps = [self.parse_exp()]
        while self.accept(b","):
            exps.append(self.parse_exp())
        return exps

    # precedence: or<and<compare<| < ~ < & << >> .. + - * / // % unary ^
    BINPRI = {
        b"or": (1, 1), b"and": (2, 2),
        b"<": (3, 3), b">": (3, 3), b"<=": (3, 3), b">=": (3, 3), b"~=": (3, 3), b"==": (3, 3),
        b"|": (4, 4), b"~": (5, 5), b"&": (6, 6), b"<<": (7, 7), b">>": (7, 7),
        b"..": (9, 8),  # right assoc: left pri 9? Standard Lua: .. pri (5,4) scaled; use ordering below +/-?
        b"+": (10, 10), b"-": (10, 10),
        b"*": (11, 11), b"/": (11, 11), b"//": (11, 11), b"%": (11, 11),
        b"^": (14, 13),
    }
    UNARY_PRI = 12

    def parse_exp(self, limit=0):
        line = self.tok.line
        t = self.tok.type
        if t in (b"not", b"#", b"-", b"~"):
            op = self.advance().type
            sub = self.parse_exp(self.UNARY_PRI)
            left = ("unop", line, op, sub)
        else:
            left = self.parse_simple_exp()
        while True:
            op = self.tok.type
            if op not in self.BINPRI:
                break
            lpri, rpri = self.BINPRI[op]
            if lpri <= limit:
                break
            oline = self.advance().line
            right = self.parse_exp(rpri)
            left = ("binop", oline, op, left, right)
        return left

    def parse_simple_exp(self):
        t = self.tok
        line = t.line
        if t.type == b"nil":
            self.advance(); return ("nil", line)
        if t.type == b"true":
            self.advance(); return ("true", line)
        if t.type == b"false":
            self.advance(); return ("false", line)
        if t.type == "number":
            self.advance(); return ("number", line, t.value)
        if t.type == "string":
            self.advance(); return ("string", line, t.value)
        if t.type == b"...":
            self.advance()
            if not self.current_func().proto.is_vararg:
                raise ParseError(b"cannot use '...' outside a vararg function near '...'", line)
            return ("vararg", line)
        if t.type == b"function":
            self.advance()
            proto = self.parse_function_body(line, is_method=False)
            return ("function", line, proto)
        if t.type == b"{":
            return self.parse_table()
        if t.type == "name" or t.type == b"(":
            return self.parse_suffixed_exp()
        self.error("unexpected symbol")

    def parse_table(self):
        line = self.advance().line  # {
        fields = []
        while self.tok.type != b"}":
            if self.tok.type == b"[":
                self.advance()
                kexp = self.parse_exp()
                self.expect(b"]")
                self.expect(b"=")
                vexp = self.parse_exp()
                fields.append(("rec", kexp, vexp))
            elif self.tok.type == "name":
                # could be  name '=' or list expr starting with name
                # Need lookahead: peek next token after name
                save_tok = self.tok
                # Use lexer peek: lexer position after self.tok is not stored separately.
                # We'll implement lookahead by advancing and checking; if '=', rec, else
                # we need to push back. Instead, parse assuming name then check current.
                nm = self.tok.value
                nline = self.tok.line
                # lookahead helper: temporarily advance
                self.advance()
                if self.tok.type == b"=":
                    self.advance()
                    vexp = self.parse_exp()
                    fields.append(("rec", ("string", nline, nm), vexp))
                else:
                    # It was start of a list expression; continue parsing suffixed exp
                    # starting from this name. We have consumed name and current is next token.
                    exp = self._continue_suffixed(self.resolve_name(nm, nline))
                    # Now parse rest of expression with binary ops:
                    exp = self._continue_binop(exp, 0)
                    fields.append(("list", None, exp))
            else:
                exp = self.parse_exp()
                fields.append(("list", None, exp))
            if self.tok.type in (b",", b";"):
                self.advance()
            elif self.tok.type != b"}":
                self.error("'}' expected")
        self.expect(b"}")
        return ("table", line, fields)

    def _continue_binop(self, left, limit):
        while True:
