            sub = self.parse_exp(self.UNARY_PRI)
            left = ("unop", line, op, sub)
        else:
            left = self.parse_simple_exp()
        while True:
            op = self.tok.type
            if op not in self.BINPRI:
                break
            lpri, rpri = self.BINPRI[op]
            if lpri <= limit:
                break
            oline = self.advance().line
            right = self.parse_exp(rpri)
            left = ("binop", oline, op, left, right)
        return left

    def parse_simple_exp(self):
        t = self.tok
        line = t.line
        if t.type == b"nil":
            self.advance(); return ("nil", line)
        if t.type == b"true":
            self.advance(); return ("true", line)
        if t.type == b"false":
            self.advance(); return ("false", line)
        if t.type == "number":
            self.advance(); return ("number", line, t.value)
        if t.type == "string":
            self.advance(); return ("string", line, t.value)
        if t.type == b"...":
            self.advance()
            if not self.current_func().proto.is_vararg:
                raise ParseError(b"cannot use '...' outside a vararg function near '...'", line)
            return ("vararg", line)
        if t.type == b"function":
            self.advance()
            proto = self.parse_function_body(line, is_method=False)
            return ("function", line, proto)
        if t.type == b"{":
            return self.parse_table()
        if t.type == "name" or t.type == b"(":
            return self.parse_suffixed_exp()
        self.error("unexpected symbol")

    def parse_table(self):
        line = self.advance().line  # {
        fields = []
        while self.tok.type != b"}":
            if self.tok.type == b"[":
                self.advance()
                kexp = self.parse_exp()
                self.expect(b"]")
                self.expect(b"=")
                vexp = self.parse_exp()
                fields.append(("rec", kexp, vexp))
            elif self.tok.type == "name":
                # could be  name '=' or list expr starting with name
                # Need lookahead: peek next token after name
                save_tok = self.tok
                # Use lexer peek: lexer position after self.tok is not stored separately.
                # We'll implement lookahead by advancing and checking; if '=', rec, else
                # we need to push back. Instead, parse assuming name then check current.
                nm = self.tok.value
                nline = self.tok.line
                # lookahead helper: temporarily advance
                self.advance()
                if self.tok.type == b"=":
                    self.advance()
                    vexp = self.parse_exp()
                    fields.append(("rec", ("string", nline, nm), vexp))
                else:
                    # It was start of a list expression; continue parsing suffixed exp
                    # starting from this name. We have consumed name and current is next token.
                    exp = self._continue_suffixed(self.resolve_name(nm, nline))
                    # Now parse rest of expression with binary ops:
                    exp = self._continue_binop(exp, 0)
                    fields.append(("list", None, exp))
            else:
                exp = self.parse_exp()
                fields.append(("list", None, exp))
            if self.tok.type in (b",", b";"):
                self.advance()
            elif self.tok.type != b"}":
                self.error("'}' expected")
        self.expect(b"}")
        return ("table", line, fields)

    def _continue_binop(self, left, limit):
        while True:
            op = self.tok.type
            if op not in self.BINPRI:
                break
            lpri, rpri = self.BINPRI[op]
            if lpri <= limit:
                break
            oline = self.advance().line
            right = self.parse_exp(rpri)
            left = ("binop", oline, op, left, right)
        return left

    def parse_primary_exp(self):
        t = self.tok
        line = t.line
        if t.type == b"(":
            self.advance()
            e = self.parse_exp()
            self.expect(b")")
            return ("paren", line, e)
        elif t.type == "name":
            self.advance()
            return self.resolve_name(t.value, line)
        else:
            self.error("unexpected symbol")

    def parse_suffixed_exp(self):
        exp = self.parse_primary_exp()
        return self._continue_suffixed(exp)

    def _continue_suffixed(self, exp):
        while True:
            t = self.tok
            line = t.line
            if t.type == b".":
                self.advance()
                fname, fline = self.expect_name()
                exp = ("index", fline, exp, ("string", fline, fname), fname)
            elif t.type == b"[":
                self.advance()
                kexp = self.parse_exp()
                self.expect(b"]")
                fieldname = None
                if kexp[0] == "string":
                    fieldname = kexp[2]
                exp = ("index", line, exp, kexp, fieldname)
            elif t.type == b":":
                self.advance()
                mname, mline = self.expect_name()
                args = self.parse_args()
                exp = ("mcall", mline, exp, mname, args)
            elif t.type == b"(" or t.type == "string" or t.type == b"{":
                args = self.parse_args()
                exp = ("call", line, exp, args)
            else:
                break
