    def parse_args(self):
        t = self.tok
        line = t.line
        if t.type == b"(":
            self.advance()
            if self.tok.type == b")":
                self.advance()
                return []
            args = self.parse_explist()
            self.expect(b")")
            return args
        elif t.type == "string":
            self.advance()
            return [("string", line, t.value)]
        elif t.type == b"{":
            return [self.parse_table()]
        else:
            self.error("unexpected symbol")

def parse_source(data, source):
    p = Parser(data, source)
    try:
        proto = p.parse_chunk()
    except LexError as e:
        raise ParseError(e.msg, e.line)
    # resolve goto nodes placeholders
    _finalize_gotos(p, proto)
    return proto

