import math
import threading
import sys

from lua_values import *

class ReturnSignal(Exception):
    def __init__(self, values):
        self.values = values

class BreakSignal(Exception):
    pass

class GotoSignal(Exception):
    def __init__(self, label_id):
        self.label_id = label_id

class TailCallSignal(Exception):
    def __init__(self, owner, func, args, desc, call_info):
        self.owner = owner
        self.func = func
        self.args = args
        self.desc = desc
        self.call_info = call_info

class CoroutineCloseSignal(Exception):
    pass

class BlockCtx:
    __slots__ = ("closers", "locals", "current_idx", "locals_start")
    def __init__(self, locals_start):
        self.closers = []   # (var, cell, decl_idx)
        self.locals = []    # (var, cell, decl_idx)
        self.current_idx = 0
        self.locals_start = locals_start

class Frame:
    __slots__ = ("closure", "proto", "cells", "varargs", "current_line",
                 "call_name", "namewhat", "istailcall", "is_c", "builtin",
                 "locals_stack", "blocks", "thread", "call_args", "what")
    def __init__(self, thread):
        self.closure = None
        self.proto = None
        self.cells = {}
        self.varargs = []
        self.current_line = -1
        self.call_name = None
        self.namewhat = ""
        self.istailcall = False
        self.is_c = False
        self.builtin = None
        self.locals_stack = []  # (Var, Cell)
        self.blocks = []
        self.thread = thread
        self.call_args = None
        self.what = "Lua"

def _float_floor_div(a, b):
    # a // b for floats
    if b == 0:
        if a == 0 or math.isnan(a) or math.isnan(b):
            return float("nan")
        return math.copysign(math.inf, a) * math.copysign(1.0, b)
    q = a / b
    if math.isnan(q):
        return float("nan")
    if math.isinf(q):
        return q
    return float(math.floor(q))

class Interpreter:
    def __init__(self):
        self.globals = LuaTable()
        self.registry = LuaTable()
        self.main_thread = LuaThreadObj(is_main=True)
        self.thread_by_py = {threading.get_ident(): self.main_thread}
        self.type_metatables = {
            "string": None, "number": None, "boolean": None, "nil": None,
            "function": None, "thread": None,
        }
        self.string_metatable = LuaTable()
        self.type_metatables["string"] = self.string_metatable
        self.warnings_on = False
        self.warn_state = False
        self.gc_running = True
        self.gc_mode = "generational"
        self.gc_params = {"pause": 250 if False else 200, "stepmul": 200, "stepsize": 9600, "minormul": 20}
        # actual defaults observed: pause 250 (generational mode?) - corrected in stdlib init if needed
        self.gc_params["pause"] = 250
        self.stdin_file = None
        self.stdout_file = None
        self.stderr_file = None
        self.file_metatable = None
        self.output_file = None
        self.input_file = None
        self._next_coroutine_id = 0
        self.traceback_override = None
        self.exit_code = None
        self.progname = b"lua"

    # ---------- threads / frames ----------
    def current_thread(self):
        t = self.thread_by_py.get(threading.get_ident())
        if t is None:
            return self.main_thread
        return t

    def current_frame(self):
        th = self.current_thread()
        return th.frames[-1] if th.frames else None

    def current_lua_frame(self):
        th = self.current_thread()
        for f in reversed(th.frames):
            if not f.is_c:
                return f
        return None

    def snapshot_frames(self, thread=None):
        th = thread or self.current_thread()
        snap = []
        for f in reversed(th.frames):
            snap.append({
                "is_c": f.is_c,
                "what": f.what,
                "source": (f.proto.source if f.proto else b"=[C]"),
                "currentline": f.current_line,
                "call_name": f.call_name,
                "namewhat": f.namewhat,
                "istailcall": f.istailcall,
                "linedefined": (f.proto.linedefined if f.proto else -1),
                "lastlinedefined": (f.proto.lastlinedefined if f.proto else -1),
                "func": (f.builtin if f.is_c else f.closure),
                "proto": f.proto,
                "frame_ref": f,
                "istailcall": f.istailcall,
            })
        return snap

    # ---------- errors ----------
    def make_error(self, value, located=False):
        e = value if isinstance(value, LuaError) else LuaError(value, located)
        if e.snapshot is None:
            try:
                e.snapshot = self.snapshot_frames()
            except Exception:
                e.snapshot = []
        return e

    def runtime_error(self, msg, line=None, frame=None):
        if isinstance(msg, str):
            msg = msg.encode("latin1")
        f = frame or self.current_lua_frame()
        if f is not None and f.proto is not None:
            ln = line if line is not None else f.current_line
            src = short_source(f.proto.source)
            full = src + b":" + str(ln).encode() + b": " + msg
            raise self.make_error(full, True)
        raise self.make_error(msg, False)

    def lib_error(self, msg):
        """Error from a library function: locate at the Lua call site if the
        immediate caller of the current C function is Lua."""
        if isinstance(msg, str):
            msg = msg.encode("latin1")
        th = self.current_thread()
        # find innermost C frame
        for i in range(len(th.frames) - 1, -1, -1):
            fr = th.frames[i]
            if fr.is_c:
                caller = th.frames[i - 1] if i > 0 else None
                if caller is not None and not caller.is_c and caller.proto is not None:
                    src = short_source(caller.proto.source)
                    full = src + b":" + str(caller.current_line).encode() + b": " + msg
                    raise self.make_error(full, True)
                break
        raise self.make_error(msg, False)

    def arg_error(self, funcname, argno, msg):
        self.lib_error(("bad argument #%d to '%s' (%s)" % (argno, funcname, msg)).encode("latin1")
                       if isinstance(funcname, str) else
                       b"bad argument #" + str(argno).encode() + b" to '" + funcname + b"' (" +
                       (msg.encode("latin1") if isinstance(msg, str) else msg) + b")")

    # ---------- metatables ----------
    def get_metatable(self, v):
        if isinstance(v, LuaTable):
            return v.metatable
        if isinstance(v, UserData):
            return v.metatable
        return self.type_metatables.get(lua_type(v))

    def get_metafield(self, v, name):
        mt = self.get_metatable(v)
        if mt is None:
            return None
        return mt.rawget(name)

    def obj_addr(self, v):
        if hasattr(v, "addr"):
            return v.addr
        return id(v)

    def default_tostring(self, v):
        t = lua_type(v)
        if t == "table" or t == "userdata":
            mt = self.get_metatable(v)
            name = None
            if mt is not None:
                nm = mt.rawget(b"__name")
                if type(nm) is bytes:
                    name = nm
            if isinstance(v, FileUserData):
                # handled by its __tostring, but fallback:
                return b"file (" + (b"closed" if v.closed else ("0x%x" % v.addr).encode()) + b")"
            label = name if name else t.encode()
            return label + b": 0x%x" % self.obj_addr(v)
        if t == "function":
            return b"function: 0x%x" % self.obj_addr(v)
        if t == "thread":
            return b"thread: 0x%x" % self.obj_addr(v)
        return None

    def lua_tostring(self, v):
        """tostring semantics; returns bytes or whatever __tostring returns."""
        t = lua_type(v)
        if t == "string":
            return v
        if t == "number":
            return number_to_bytes(v)
        if t == "boolean":
            return b"true" if v else b"false"
        if t == "nil":
            return b"nil"
        mm = self.get_metafield(v, b"__tostring")
        if mm is not None:
            res = self.call_value(mm, [v], call_info=(b"__tostring", "metamethod"))
            return res[0] if res else None
        return self.default_tostring(v)

    def tostring_coerce(self, v):
        """Convert to bytes for print/concat contexts. Numbers/strings only
        in concat, but print uses tostring."""
        r = self.lua_tostring(v)
        return r

    # ---------- value descriptions ----------
    def expr_desc(self, node):
        if node is None:
            return None
        tag = node[0]
        if tag == "var":
            kind = node[3]
            return " (%s '%s')" % (kind, node[2].name.decode("latin1"))
        if tag == "globalvar":
            return " (global '%s')" % node[2].decode("latin1")
        if tag == "index":
            fieldname = node[4]
            kexp = node[3]
            if fieldname is not None:
                return " (field '%s')" % fieldname.decode("latin1")
            if kexp[0] == "number" and type(kexp[2]) is int:
                return " (field 'integer index')"
            return " (field '?')"
        if tag == "paren":
            return self.expr_desc(node[2])
        return None

    def call_info_of(self, node):
        tag = node[0]
        if tag == "var":
            return (node[2].name, node[3])
        if tag == "globalvar":
            return (node[2], "global")
        if tag == "index":
            if node[4] is not None:
                return (node[4], "field")
            return (None, "field")
        if tag == "paren":
            return self.call_info_of(node[2])
        return (None, "")

    # ---------- calls ----------
    def call_value(self, func, args, desc=None, call_info=None):
        th = self.current_thread()
        lf = self.current_lua_frame()
        if isinstance(func, LuaClosure):
            return self.invoke_closure(func, list(args), call_info)
        if isinstance(func, BuiltinFunction):
            fr = Frame(th)
            fr.is_c = True
            fr.what = "C"
            fr.builtin = func
            fr.call_args = list(args)
            if call_info:
                fr.call_name, fr.namewhat = call_info
            fr.current_line = -1
            th.frames.append(fr)
            try:
                res = func.func(self, list(args))
            except RecursionError:
                raise self.make_error(b"stack overflow")
            finally:
                if th.frames and th.frames[-1] is fr:
                    th.frames.pop()
                elif fr in th.frames:
                    th.frames.remove(fr)
            if res is None:
                return []
            return list(res)
        mm = self.get_metafield(func, b"__call")
        if mm is not None:
            return self.call_value(mm, [func] + list(args),
                                   call_info=(b"__call", "metamethod"))
