        msg = "attempt to call a %s value" % lua_type(func)
        if desc:
            msg += desc
        self.runtime_error(msg)

    def invoke_closure(self, closure, args, call_info=None):
        th = self.current_thread()
        cur_closure = closure
        cur_args = args
        cur_info = call_info
        is_tail = False
        while True:
            proto = cur_closure.proto
            fr = Frame(th)
            fr.closure = cur_closure
            fr.proto = proto
            fr.what = "main" if proto.linedefined == 0 and proto.lastlinedefined == 0 and proto.is_vararg and False else "Lua"
            # main-chunk detection stored by loader via name_hint
            if getattr(proto, "name_hint", None) == b"main":
                fr.what = "main"
            if cur_info:
                fr.call_name, fr.namewhat = cur_info
            fr.istailcall = is_tail
            fr.cells = {}
            # upvalues
            for v in proto.upvalues:
                cell = cur_closure.upvalue_cells.get(v.id)
                if cell is None:
                    cell = Cell(None)
                    cur_closure.upvalue_cells[v.id] = cell
                fr.cells[v.id] = cell
            # params
            params = proto.params
            for i, pv in enumerate(params):
                val = cur_args[i] if i < len(cur_args) else None
                cell = Cell(val)
                fr.cells[pv.id] = cell
                fr.locals_stack.append((pv, cell))
            if proto.is_vararg:
                fr.varargs = list(cur_args[len(params):])
            else:
                fr.varargs = []
            if getattr(proto, "vararg_var", None) is not None:
                vv = proto.vararg_var
                tbl = LuaTable()
                for i, val in enumerate(fr.varargs):
                    tbl.rawset(i + 1, val)
                tbl.rawset(b"n", len(fr.varargs))
                cell = Cell(tbl)
                fr.cells[vv.id] = cell
                fr.locals_stack.append((vv, cell))
