            result = []
            tail_next = None
            try:
                self.exec_block(proto.body, fr)
                result = []
            except ReturnSignal as r:
                result = r.values
            except TailCallSignal as tc:
                if tc.owner is fr:
                    tail_next = tc
                else:
                    raise
            except RecursionError:
                raise self.make_error(b"stack overflow")
            finally:
                if th.frames and th.frames[-1] is fr:
                    th.frames.pop()
                elif fr in th.frames:
                    th.frames.remove(fr)
            if tail_next is None:
                return result
            # perform tail call
            if isinstance(tail_next.func, LuaClosure):
                cur_closure = tail_next.func
                cur_args = tail_next.args
                cur_info = tail_next.call_info
                is_tail = True
                continue
            else:
                return self.call_value(tail_next.func, tail_next.args,
                                       desc=tail_next.desc, call_info=tail_next.call_info)

    def pcall_value(self, func, args):
