            res = self.call_value(func, args)
            return True, res
        except LuaError as e:
            return False, e.value
        except RecursionError:
            return False, b"stack overflow"

    # ---------- indexing ----------
    def index_value(self, obj, key, desc=None, line=None, frame=None):
        cur = obj
        for _ in range(100):
            if isinstance(cur, LuaTable):
                v = cur.rawget(key)
                if v is not None:
                    return v
                mm = None
                if cur.metatable is not None:
                    mm = cur.metatable.rawget(b"__index")
                if mm is None:
                    return None
                if isinstance(mm, LuaTable):
                    cur = mm
                    continue
                res = self.call_value(mm, [cur, key], call_info=(b"__index", "metamethod"))
                return res[0] if res else None
            else:
                mm = self.get_metafield(cur, b"__index")
                if mm is None:
                    msg = "attempt to index a %s value" % lua_type(cur)
                    if desc:
                        msg += desc
                    self.runtime_error(msg, line=line, frame=frame)
                if isinstance(mm, LuaTable):
                    cur = mm
                    continue
                res = self.call_value(mm, [cur, key], call_info=(b"__index", "metamethod"))
                return res[0] if res else None
