    def set_index(self, obj, key, value, desc=None, line=None, frame=None):
        cur = obj
        for _ in range(100):
            if isinstance(cur, LuaTable):
                if cur.rawget(key) is not None:
                    try:
                        cur.rawset(key, value)
                    except ValueError as ve:
                        self.runtime_error(str(ve), line=line, frame=frame)
                    return
                mm = None
                if cur.metatable is not None:
                    mm = cur.metatable.rawget(b"__newindex")
                if mm is None:
                    try:
                        cur.rawset(key, value)
                    except ValueError as ve:
                        self.runtime_error(str(ve), line=line, frame=frame)
                    return
                if isinstance(mm, LuaTable):
                    cur = mm
                    continue
                self.call_value(mm, [cur, key, value], call_info=(b"__newindex", "metamethod"))
                return
            else:
                mm = self.get_metafield(cur, b"__newindex")
                if mm is None:
                    msg = "attempt to index a %s value" % lua_type(cur)
                    if desc:
                        msg += desc
                    self.runtime_error(msg, line=line, frame=frame)
                if isinstance(mm, LuaTable):
                    cur = mm
                    continue
                self.call_value(mm, [cur, key, value], call_info=(b"__newindex", "metamethod"))
                return
