        return list(frame.varargs)

    def _eval_call_parts(self, node, frame):
        if node[0] == "call":
            fnode = node[2]
            func = self.eval_exp(fnode, frame)
            args = self.eval_explist(node[3], frame) if node[3] else []
            desc = self.expr_desc(fnode)
            info = self.call_info_of(fnode)
            return func, args, desc, info
        else:  # mcall
            onode = node[2]
            obj = self.eval_exp(onode, frame)
            frame.current_line = node[1]
            func = self.index_value(obj, node[3], desc=self.expr_desc(onode),
                                    line=node[1], frame=frame)
            args = self.eval_explist(node[4], frame) if node[4] else []
            desc = " (method '%s')" % node[3].decode("latin1")
            info = (node[3], "method")
            return func, [obj] + list(args), desc, info

    def eval_exp(self, node, frame):
        tag = node[0]
        if tag == "nil":
            return None
        if tag == "true":
            return True
        if tag == "false":
            return False
        if tag == "number":
            return node[2]
        if tag == "string":
            return node[2]
        if tag == "var":
            cell = frame.cells.get(node[2].id)
            return cell.value if cell is not None else None
        if tag == "globalvar":
            frame.current_line = node[1]
            env = frame.cells[node[3].id].value
            return self.index_value(env, node[2],
                                    desc=" (upvalue '_ENV')" if node[4] == "upvalue" else " (local '_ENV')",
                                    line=node[1], frame=frame)
        if tag == "paren":
            vals = self.eval_multi_trunc(node[2], frame)
            return vals
        if tag == "vararg":
            vals = self._vararg_values(frame, node)
            return vals[0] if vals else None
        if tag == "function":
            return self.make_closure(node[2], frame)
        if tag == "table":
            return self._eval_table(node, frame)
        if tag == "index":
            obj = self.eval_exp(node[2], frame)
            key = self.eval_exp(node[3], frame)
            frame.current_line = node[1]
            return self.index_value(obj, key, desc=self.expr_desc(node[2]),
                                    line=node[1], frame=frame)
        if tag == "call" or tag == "mcall":
            vals = self.eval_multi(node, frame)
            return vals[0] if vals else None
        if tag == "unop":
            op = node[2]
            frame.current_line = node[1]
            v = self.eval_exp(node[3], frame)
            frame.current_line = node[1]
            return self.unary_op(op, v, vnode=node[3], line=node[1], frame=frame)
        if tag == "binop":
            op = node[2]
            if op == b"and":
                lv = self.eval_exp(node[3], frame)
                if not truthy(lv):
                    return lv
                return self.eval_exp(node[4], frame)
            if op == b"or":
                lv = self.eval_exp(node[3], frame)
                if truthy(lv):
                    return lv
                return self.eval_exp(node[4], frame)
            lv = self.eval_exp(node[3], frame)
            rv = self.eval_exp(node[4], frame)
            frame.current_line = node[1]
            if op == b"==":
                return self.equals(lv, rv)
            if op == b"~=":
                return not self.equals(lv, rv)
            if op in (b"<", b">", b"<=", b">="):
                return self.compare_op(op, lv, rv, line=node[1], frame=frame)
            if op == b"..":
                return self.concat_op(lv, rv, anode=node[3], bnode=node[4],
                                      line=node[1], frame=frame)
            return self.arith_op(op, lv, rv, anode=node[3], bnode=node[4],
                                 line=node[1], frame=frame)
