def _float_floor_div(a, b):
    # a // b for floats
    if b == 0:
        if a == 0 or math.isnan(a) or math.isnan(b):
            return float("nan")
        return math.copysign(math.inf, a) * math.copysign(1.0, b)
    q = a / b
    if math.isnan(q):
        return float("nan")
    if math.isinf(q):
        return q
    return float(math.floor(q))

