        self.registry = LuaTable()
        self.main_thread = LuaThreadObj(is_main=True)
        self.thread_by_py = {threading.get_ident(): self.main_thread}
        self.type_metatables = {
            "string": None, "number": None, "boolean": None, "nil": None,
            "function": None, "thread": None,
        }
        self.string_metatable = LuaTable()
        self.type_metatables["string"] = self.string_metatable
