        self.warn_state = False
        self.gc_running = True
        self.gc_mode = "generational"
        self.gc_params = {"pause": 250 if False else 200, "stepmul": 200, "stepsize": 9600, "minormul": 20}
        # actual defaults observed: pause 250 (generational mode?) - corrected in stdlib init if needed
        self.gc_params["pause"] = 250
