        self.stdout_file = None
        self.stderr_file = None
        self.file_metatable = None
        self.output_file = None
        self.input_file = None
        self._next_coroutine_id = 0
        self.traceback_override = None
        self.exit_code = None
        self.progname = b"lua"

    # ---------- threads / frames ----------
    def current_thread(self):
        t = self.thread_by_py.get(threading.get_ident())
        if t is None:
            return self.main_thread
