        th = self.current_thread()
        return th.frames[-1] if th.frames else None

    def current_lua_frame(self):
        th = self.current_thread()
        for f in reversed(th.frames):
            if not f.is_c:
                return f
        return None

    def snapshot_frames(self, thread=None):
        th = thread or self.current_thread()
        snap = []
        for f in reversed(th.frames):
            snap.append({
                "is_c": f.is_c,
                "what": f.what,
                "source": (f.proto.source if f.proto else b"=[C]"),
                "currentline": f.current_line,
                "call_name": f.call_name,
                "namewhat": f.namewhat,
                "istailcall": f.istailcall,
                "linedefined": (f.proto.linedefined if f.proto else -1),
                "lastlinedefined": (f.proto.lastlinedefined if f.proto else -1),
                "func": (f.builtin if f.is_c else f.closure),
                "proto": f.proto,
                "frame_ref": f,
                "istailcall": f.istailcall,
