        for i in range(len(th.frames) - 1, -1, -1):
            fr = th.frames[i]
            if fr.is_c:
                caller = th.frames[i - 1] if i > 0 else None
                if caller is not None and not caller.is_c and caller.proto is not None:
                    src = short_source(caller.proto.source)
                    full = src + b":" + str(caller.current_line).encode() + b": " + msg
                    raise self.make_error(full, True)
