        return None

    _ARITH_MM = {b"+": b"__add", b"-": b"__sub", b"*": b"__mul", b"/": b"__div",
                 b"//": b"__idiv", b"%": b"__mod", b"^": b"__pow",
                 b"&": b"__band", b"|": b"__bor", b"~": b"__bxor",
                 b"<<": b"__shl", b">>": b"__shr"}
    _ARITH_NAME = {b"+": "add", b"-": "sub", b"*": "mul", b"/": "div",
                   b"//": "idiv", b"%": "mod", b"^": "pow"}

    def _call_bin_mm(self, a, b, mmname):
        mm = self.get_metafield(a, mmname)
        if mm is None:
            mm = self.get_metafield(b, mmname)
        if mm is None:
            return None, False
        res = self.call_value(mm, [a, b], call_info=(mmname[2:], "metamethod"))
        return (res[0] if res else None), True

    def arith_op(self, op, a, b, anode=None, bnode=None, line=None, frame=None):
        is_bitwise = op in (b"&", b"|", b"~", b"<<", b">>")
        if not is_bitwise:
            na = self._to_number_coerce(a)
            nb = self._to_number_coerce(b)
            if na is not None and nb is not None:
                return self._numeric_arith(op, na, nb, line, frame)
