            if is_number(a) and is_number(b):
                ia = to_integer_value(a)
                ib = to_integer_value(b)
                if ia is not None and ib is not None:
                    return self._bitwise(op, ia, ib)
                # float without integer representation
                if self.get_metafield(a, self._ARITH_MM[op]) is None and \
                   self.get_metafield(b, self._ARITH_MM[op]) is None:
                    self.runtime_error("number has no integer representation", line=line, frame=frame)
            # strings that look numeric are NOT converted for bitwise, but
            # string metatable arithmetic functions exist for +,- etc only.
        # string metatable contains arithmetic metamethods for strings;
        # those simply perform numeric op if convertible (handled above) or error.
        mmres, ok = self._call_bin_mm(a, b, self._ARITH_MM[op])
        if ok:
            # For string metamethods (our builtins raise proper errors), fine.
            return mmres
        # build error
        if is_bitwise:
            # offending operand: first that is not integer-representable number
            if not (is_number(a) and to_integer_value(a) is not None):
                off, offnode = a, anode
            else:
                off, offnode = b, bnode
            desc = self._desc_for_bitwise(offnode)
            msg = "attempt to perform bitwise operation on a %s value" % lua_type(off)
            if desc:
                msg += desc
            self.runtime_error(msg, line=line, frame=frame)
        else:
            if type(a) is bytes or type(b) is bytes:
                msg = "attempt to %s a '%s' with a '%s'" % (
                    self._ARITH_NAME[op], lua_type(a), lua_type(b))
                self.runtime_error(msg, line=line, frame=frame)
            if self._to_number_coerce(a) is None:
                off, offnode = a, anode
            else:
                off, offnode = b, bnode
            desc = self.expr_desc(offnode)
            msg = "attempt to perform arithmetic on a %s value" % lua_type(off)
            if desc:
                msg += desc
            self.runtime_error(msg, line=line, frame=frame)

    def _desc_for_bitwise(self, node):
        if node is None:
            return None
        if node[0] == "string":
            return " (constant '%s')" % node[2].decode("latin1")
        return self.expr_desc(node)

    def _numeric_arith(self, op, a, b, line=None, frame=None):
        both_int = type(a) is int and type(b) is int
        if op == b"+":
            return wrap_int(a + b) if both_int else number_to_float(a) + number_to_float(b)
        if op == b"-":
            return wrap_int(a - b) if both_int else number_to_float(a) - number_to_float(b)
        if op == b"*":
            return wrap_int(a * b) if both_int else number_to_float(a) * number_to_float(b)
        if op == b"/":
            fa, fb = number_to_float(a), number_to_float(b)
            if fb == 0.0:
                if fa == 0.0 or math.isnan(fa):
                    # sign of nan: Lua/C gives -nan for 0/0
                    return -float("nan")
                return math.copysign(math.inf, fa) * math.copysign(1.0, fb)
            return fa / fb
        if op == b"//":
            if both_int:
                if b == 0:
                    self.runtime_error("attempt to divide by zero", line=line, frame=frame)
                if a == INT_MIN and b == -1:
                    return INT_MIN
                return a // b  # Python floor division matches Lua for ints
            return _float_floor_div(number_to_float(a), number_to_float(b))
        if op == b"%":
            if both_int:
                if b == 0:
                    self.runtime_error("attempt to perform 'n%0'", line=line, frame=frame)
                if b == -1:
                    return 0
                return a % b  # Python % takes sign of divisor == Lua
            fa, fb = number_to_float(a), number_to_float(b)
            if fb == 0.0 or math.isnan(fa) or math.isnan(fb) or math.isinf(fa):
                return -float("nan")
            if math.isinf(fb):
                # Lua fmod style: a - floor(a/b)*b; if a,b same sign or exact -> a else a+b
                r = fa - math.floor(fa / fb) * fb if False else math.fmod(fa, fb)
                # adjust to Lua modulo (sign of divisor)
                if r != 0 and (r < 0) != (fb < 0):
                    r += fb
                return r
            r = math.fmod(fa, fb)
            if r != 0 and (r < 0) != (fb < 0):
                r += fb
            return r
        if op == b"^":
            fa, fb = number_to_float(a), number_to_float(b)
            try:
                return math.pow(fa, fb)
            except OverflowError:
                # sign: negative base with odd integer exponent
                if fa < 0 and fb == math.floor(fb) and int(abs(fb)) % 2 == 1:
                    return -math.inf
                return math.inf
            except ValueError:
                return float("nan")
        raise AssertionError(op)

    def _bitwise(self, op, a, b):
        if op == b"&":
            return wrap_int(a & b)
        if op == b"|":
            return wrap_int(a | b)
        if op == b"~":
            return wrap_int(a ^ b)
        if op == b"<<":
            return self._shift_left(a, b)
        if op == b">>":
            return self._shift_right(a, b)
        raise AssertionError(op)

    def _shift_left(self, a, n):
        if n >= 64:
            return 0
        if n <= -64:
            return 0  # shifting right by >=64: arithmetic: sign extension
            # handled below for negative
        if n < 0:
            return self._shift_right(a, -n)
        return wrap_int(a << n)

    def _shift_right(self, a, n):
        if n < 0:
            return self._shift_left(a, -n)
        if n >= 64:
            return -1 if a < 0 else 0
        return a >> n  # Python arithmetic shift on signed

    def unary_op(self, op, v, vnode=None, line=None, frame=None):
        if op == b"not":
            return not truthy(v)
        if op == b"-":
            n = self._to_number_coerce(v)
            if n is not None:
                if type(n) is int:
                    return wrap_int(-n)
                return -n
            mm = self.get_metafield(v, b"__unm")
            if mm is not None:
                res = self.call_value(mm, [v, v], call_info=(b"unm", "metamethod"))
                return res[0] if res else None
            if type(v) is bytes:
                self.runtime_error("attempt to unm a 'string' with a 'string'", line=line, frame=frame)
            desc = self.expr_desc(vnode)
            msg = "attempt to perform arithmetic on a %s value" % lua_type(v)
            if desc:
                msg += desc
            self.runtime_error(msg, line=line, frame=frame)
        if op == b"~":
            if is_number(v):
                iv = to_integer_value(v)
                if iv is not None:
                    return wrap_int(~iv)
                self.runtime_error("number has no integer representation", line=line, frame=frame)
            mm = self.get_metafield(v, b"__bnot")
            if mm is not None:
                res = self.call_value(mm, [v, v], call_info=(b"bnot", "metamethod"))
                return res[0] if res else None
            desc = self._desc_for_bitwise(vnode)
            msg = "attempt to perform bitwise operation on a %s value" % lua_type(v)
            if desc:
                msg += desc
            self.runtime_error(msg, line=line, frame=frame)
        if op == b"#":
            if type(v) is bytes:
                return len(v)
            mm = None
            if isinstance(v, LuaTable):
                mm = self.get_metafield(v, b"__len")
                if mm is None:
                    return v.border()
            else:
                mm = self.get_metafield(v, b"__len")
            if mm is not None:
                res = self.call_value(mm, [v], call_info=(b"len", "metamethod"))
                return res[0] if res else None
            desc = self.expr_desc(vnode)
            msg = "attempt to get length of a %s value" % lua_type(v)
            if desc:
                msg += desc
            self.runtime_error(msg, line=line, frame=frame)
        raise AssertionError(op)

    def concat_op(self, a, b, anode=None, bnode=None, line=None, frame=None):
        def is_str_or_num(x):
            return type(x) is bytes or is_number(x)
        if is_str_or_num(a) and is_str_or_num(b):
            sa = a if type(a) is bytes else number_to_bytes(a)
            sb = b if type(b) is bytes else number_to_bytes(b)
            return sa + sb
        mm = self.get_metafield(a, b"__concat")
        if mm is None:
            mm = self.get_metafield(b, b"__concat")
        if mm is not None:
            res = self.call_value(mm, [a, b], call_info=(b"concat", "metamethod"))
            return res[0] if res else None
        if not is_str_or_num(a):
            off, offnode = a, anode
        else:
            off, offnode = b, bnode
        desc = self.expr_desc(offnode)
        msg = "attempt to concatenate a %s value" % lua_type(off)
        if desc:
            msg += desc
        self.runtime_error(msg, line=line, frame=frame)

    def equals(self, a, b):
        ta, tb = lua_type(a), lua_type(b)
        if ta != tb:
            if ta == "number" and tb == "number":
                pass
            else:
                return False
        if ta == "number":
            if type(a) is float and math.isnan(a):
                return False
            if type(b) is float and math.isnan(b):
                return False
            return a == b
        if isinstance(a, (LuaTable, UserData)) and isinstance(b, (LuaTable, UserData)):
            if a is b:
                return True
            if type(a) is not type(b) and not (isinstance(a, UserData) and isinstance(b, UserData)):
                # tables only compare with tables, userdata with userdata
                if isinstance(a, LuaTable) != isinstance(b, LuaTable):
                    return False
            ma = self.get_metafield(a, b"__eq")
            mb = self.get_metafield(b, b"__eq")
            if ma is not None and ma is mb:
                res = self.call_value(ma, [a, b], call_info=(b"eq", "metamethod"))
                return truthy(res[0] if res else None)
            return False
        return a is b if not isinstance(a, (bytes, bool)) and a is not None else a == b

    def compare_op(self, op, a, b, line=None, frame=None):
        # normalize: > and >= by swapping
        if op == b">":
            op = b"<"
            a, b = b, a
        elif op == b">=":
            op = b"<="
            a, b = b, a
        if is_number(a) and is_number(b):
            if (type(a) is float and math.isnan(a)) or (type(b) is float and math.isnan(b)):
                return False
            return a < b if op == b"<" else a <= b
        if type(a) is bytes and type(b) is bytes:
            return a < b if op == b"<" else a <= b
        mmname = b"__lt" if op == b"<" else b"__le"
        mm = self.get_metafield(a, mmname)
        if mm is None:
            mm = self.get_metafield(b, mmname)
        if mm is not None:
            # Lua only calls if both have the metamethod? For comparisons
            # it requires both operands to have it (selected from first in Lua 5.3+?)
            res = self.call_value(mm, [a, b], call_info=(mmname[2:], "metamethod"))
            return truthy(res[0] if res else None)
        ta, tb = lua_type(a), lua_type(b)
        if ta == tb:
            msg = "attempt to compare two %s values" % ta
        else:
            msg = "attempt to compare %s with %s" % (ta, tb)
        self.runtime_error(msg, line=line, frame=frame)

    # ---------- closers ----------
    def _check_closable(self, var, value, line, frame):
        if value is None:
            return
        mm = self.get_metafield(value, b"__close")
        if mm is None:
            self.runtime_error("variable '%s' got a non-closable value" % var.name.decode("latin1"),
                               line=line, frame=frame)

    def _close_entries(self, entries, err_value, frame):
        """entries list of (var, cell) in registration order. Calls __close in reverse.
        Returns LuaError or None from closing."""
        close_err = None
        for (var, cell) in reversed(entries):
            value = cell.value
            if value is None:
                continue
            mm = self.get_metafield(value, b"__close")
            if mm is None:
                if close_err is None:
                    try:
                        self.runtime_error(
                            "variable '%s' got a non-closable value" % var.name.decode("latin1"),
                            frame=frame)
                    except LuaError as e:
                        close_err = e
                continue
            try:
                self.call_value(mm, [value, err_value], call_info=(b"__close", "metamethod"))
            except LuaError as e:
                if close_err is None:
                    close_err = e
            except CoroutineCloseSignal as e:
                if close_err is None:
                    close_err = e
        return close_err

    # ---------- blocks / statements ----------
    def exec_block(self, node, frame, pre_locals=None, repeat_cond=None):
        # loops for repeat handled by caller calling repeatedly with a flag?
        self._exec_block_once(node, frame, pre_locals, repeat_cond)
        return None

    def _exec_block_once(self, node, frame, pre_locals=None, repeat_cond=None):
        stmts = node[2]
        labels = node[3] if len(node) > 3 else {}
        label_by_id = {}
        for lname, (lid, idx, ln) in labels.items():
            label_by_id[lid] = idx
        ctx = BlockCtx(len(frame.locals_stack))
        frame.blocks.append(ctx)
        pending = None
        cond_result = None
        try:
            if pre_locals:
                for (var, cell) in pre_locals:
                    frame.cells[var.id] = cell
                    frame.locals_stack.append((var, cell))
                    ctx.locals.append((var, cell, 0))
            i = 0
            while i < len(stmts):
                ctx.current_idx = i
                try:
                    self.exec_stmt(stmts[i], frame, ctx)
                except GotoSignal as g:
                    if g.label_id in label_by_id:
                        lidx = label_by_id[g.label_id]
                        self._goto_close(frame, ctx, stmts, lidx)
                        i = lidx
                        continue
                    raise
                i += 1
            if repeat_cond is not None:
                cv = self.eval_exp(repeat_cond, frame)
                cond_result = truthy(cv)
        except BaseException as e:
            pending = e
        # close this block
        err_value = pending.value if isinstance(pending, LuaError) else None
        close_err = self._close_entries([(v, c) for (v, c, _) in ctx.closers], err_value, frame)
        # pop locals & block ctx
        del frame.locals_stack[ctx.locals_start:]
        if frame.blocks and frame.blocks[-1] is ctx:
            frame.blocks.pop()
        elif ctx in frame.blocks:
            frame.blocks.remove(ctx)
        if close_err is not None:
            if isinstance(pending, LuaError):
                # error during closing while handling an error: Lua replaces?
                raise close_err
            if pending is None or isinstance(pending, (ReturnSignal, BreakSignal, GotoSignal, TailCallSignal, CoroutineCloseSignal)):
                raise close_err
            raise close_err
        if pending is not None:
            raise pending
        return cond_result

    def _goto_close(self, frame, ctx, stmts, lidx):
        # determine if label is at end (only labels/empty after)
        rest = stmts[lidx + 1:]
        at_end = all(st[0] in ("empty", "label") for st in rest)
        if at_end:
            to_close = list(ctx.closers)
            ctx.closers = []
            err = self._close_entries([(v, c) for (v, c, _) in to_close], None, frame)
            # remove corresponding locals from stack (all locals of this ctx)
            self._remove_ctx_locals(frame, ctx, None, remove_all=True)
            if err:
                raise err
            return
        to_close = [(v, c, d) for (v, c, d) in ctx.closers if d > lidx]
        if not to_close:
            return
        ctx.closers = [(v, c, d) for (v, c, d) in ctx.closers if d <= lidx]
        err = self._close_entries([(v, c) for (v, c, _) in to_close], None, frame)
        self._remove_ctx_locals(frame, ctx, lidx)
        if err:
            raise err

    def _remove_ctx_locals(self, frame, ctx, lidx, remove_all=False):
        if remove_all:
            remove_cells = set(id(c) for (_, c, _) in ctx.locals)
            ctx.locals = []
        else:
            remove_cells = set(id(c) for (_, c, d) in ctx.locals if d > lidx)
            ctx.locals = [(v, c, d) for (v, c, d) in ctx.locals if d <= lidx]
        if remove_cells:
            frame.locals_stack = [(v, c) for (v, c) in frame.locals_stack if id(c) not in remove_cells]

    def exec_stmt(self, node, frame, ctx):
        tag = node[0]
        frame.current_line = node[1]
        if tag == "empty" or tag == "label":
            return
        if tag == "block":
            self._exec_block_once(node, frame)
            return
        if tag == "do":
            self._exec_block_once(node[2], frame)
            return
        if tag == "local":
            vars = node[2]
            exps = node[3]
            values = self.eval_explist(exps, frame) if exps else []
            values = self._adjust(values, len(vars))
            newcells = []
            for i, v in enumerate(vars):
                cell = Cell(values[i])
                frame.cells[v.id] = cell
                frame.locals_stack.append((v, cell))
                ctx.locals.append((v, cell, ctx.current_idx))
                newcells.append((v, cell))
            for (v, cell) in newcells:
                if v.close:
                    self._check_closable(v, cell.value, node[1], frame)
                    ctx.closers.append((v, cell, ctx.current_idx))
            return
        if tag == "localfunc":
            var = node[2]
            proto = node[3]
            cell = Cell(None)
            frame.cells[var.id] = cell
            frame.locals_stack.append((var, cell))
            ctx.locals.append((var, cell, ctx.current_idx))
            fn = self.make_closure(proto, frame)
            cell.value = fn
            return
        if tag == "global":
            names, exps, env_var, env_kind = node[2], node[3], node[4], node[5]
            if exps is None:
                return
            values = self.eval_explist(exps, frame)
            values = self._adjust(values, len(names))
            env = frame.cells[env_var.id].value
            # assign in reverse order, checking already defined
            for i in range(len(names) - 1, -1, -1):
                name = names[i]
                existing = self.index_value(env, name,
                                             desc=" (upvalue '_ENV')" if env_kind == "upvalue" else " (local '_ENV')",
                                             line=node[1], frame=frame)
                if existing is not None:
                    self.runtime_error("global '%s' already defined" % name.decode("latin1"),
                                       line=node[1], frame=frame)
                self.set_index(env, name, values[i],
                               desc=" (upvalue '_ENV')" if env_kind == "upvalue" else " (local '_ENV')",
                               line=node[1], frame=frame)
            return
        if tag == "globalfunc":
            name, proto, env_var, env_kind = node[2], node[3], node[4], node[5]
            fn = self.make_closure(proto, frame)
            env = frame.cells[env_var.id].value
            existing = self.index_value(env, name,
                                         desc=" (upvalue '_ENV')" if env_kind == "upvalue" else " (local '_ENV')",
                                         line=node[1], frame=frame)
            if existing is not None:
                self.runtime_error("global '%s' already defined" % name.decode("latin1"),
                                   line=node[1], frame=frame)
            self.set_index(env, name, fn,
                           desc=" (upvalue '_ENV')" if env_kind == "upvalue" else " (local '_ENV')",
                           line=node[1], frame=frame)
            return
        if tag == "assign":
            targets = node[2]
            exps = node[3]
            prepared = [self._prepare_target(t, frame) for t in targets]
            values = self.eval_explist(exps, frame)
            values = self._adjust(values, len(targets))
            for i in range(len(targets) - 1, -1, -1):
                self._assign_prepared(prepared[i], values[i], frame, targets[i])
            return
        if tag == "callstmt":
            self.eval_multi(node[2], frame)
            return
        if tag == "return":
            exps = node[2]
            # tail call detection
            if len(exps) == 1 and exps[0][0] in ("call", "mcall"):
                func, args, desc, info = self._eval_call_parts(exps[0], frame)
                raise TailCallSignal(frame, func, args, desc, info)
            values = self.eval_explist(exps, frame)
            raise ReturnSignal(list(values))
        if tag == "if":
            for (cond, blk) in node[2]:
                if truthy(self.eval_exp(cond, frame)):
                    self._exec_block_once(blk, frame)
                    return
            if node[3] is not None:
                self._exec_block_once(node[3], frame)
            return
        if tag == "while":
            while truthy(self.eval_exp(node[2], frame)):
                try:
                    self._exec_block_once(node[3], frame)
                except BreakSignal:
                    break
                frame.current_line = node[1]
            return
        if tag == "repeat":
            while True:
                try:
                    done = self._exec_block_once(node[2], frame, repeat_cond=node[3])
                except BreakSignal:
                    break
                if done:
                    break
            return
        if tag == "fornum":
            self._exec_fornum(node, frame)
            return
        if tag == "forgen":
            self._exec_forgen(node, frame)
            return
        if tag == "break":
            raise BreakSignal()
        if tag == "goto":
            raise GotoSignal(node[3])
        raise AssertionError("stmt " + str(tag))

    def _exec_fornum(self, node, frame):
        _, line, var, start_e, limit_e, step_e, blk = node
        start = self.eval_exp(start_e, frame)
        limit = self.eval_exp(limit_e, frame)
        step = self.eval_exp(step_e, frame) if step_e is not None else 1
        # conversion
        s_int = to_integer_value(start) if is_number(start) else None
        # Strings: Lua converts numeric strings? use number coercion
        if not is_number(start):
            cs = self._to_number_coerce(start)
            if cs is None:
                self.runtime_error("bad 'for' initial value (number expected, got %s)" % lua_type(start),
                                   line=line, frame=frame)
            start = cs
        if not is_number(limit):
            cl = self._to_number_coerce(limit)
            if cl is None:
                self.runtime_error("bad 'for' limit (number expected, got %s)" % lua_type(limit),
                                   line=line, frame=frame)
            limit = cl
        if not is_number(step):
            cst = self._to_number_coerce(step)
            if cst is None:
                self.runtime_error("bad 'for' step (number expected, got %s)" % lua_type(step),
                                   line=line, frame=frame)
            step = cst
        if type(start) is int and type(limit) is int and type(step) is int:
            if step == 0:
                self.runtime_error("'for' step is zero", line=line, frame=frame)
            i = start
            while (i <= limit) if step > 0 else (i >= limit):
                cell = Cell(i)
                try:
                    self._exec_block_once(blk, frame, pre_locals=[(var, cell)])
                except BreakSignal:
                    break
                i += step
                frame.current_line = line
        else:
            fstart, flimit, fstep = float(start), float(limit), float(step)
            if fstep == 0.0:
                self.runtime_error("'for' step is zero", line=line, frame=frame)
            i = fstart
            while (i <= flimit) if fstep > 0 else (i >= flimit):
                cell = Cell(i)
                try:
                    self._exec_block_once(blk, frame, pre_locals=[(var, cell)])
                except BreakSignal:
                    break
                i += fstep
                frame.current_line = line

    def _exec_forgen(self, node, frame):
        _, line, vars, exps, blk = node
        vals = self.eval_explist(exps, frame)
        vals = self._adjust(vals, 4)
        iterfunc, state, control, closing = vals
        # validate closer
        if closing is not None:
            mm = self.get_metafield(closing, b"__close")
            if mm is None:
                self.runtime_error("for iterator got a non-closable value", line=line, frame=frame)
        pending = None
        try:
            while True:
                frame.current_line = line
                res = self.call_value(iterfunc, [state, control])
                if not res or res[0] is None:
                    break
                res = self._adjust(res, len(vars))
                control = res[0]
                precon = [(v, Cell(res[i])) for i, v in enumerate(vars)]
                try:
                    self._exec_block_once(blk, frame, pre_locals=precon)
                except BreakSignal:
                    break
        except BaseException as e:
            pending = e
        if closing is not None:
            errv = pending.value if isinstance(pending, LuaError) else None
            mm = self.get_metafield(closing, b"__close")
            try:
                self.call_value(mm, [closing, errv], call_info=(b"__close", "metamethod"))
            except BaseException as ce:
                if not isinstance(pending, LuaError):
                    raise ce
                raise ce
        if pending is not None:
            raise pending

    def _adjust(self, values, n):
        if len(values) < n:
            return list(values) + [None] * (n - len(values))
        return list(values[:n])

    def _prepare_target(self, node, frame):
        tag = node[0]
        if tag == "var":
            cell = frame.cells.get(node[2].id)
            if cell is None:
                cell = Cell(None)
                frame.cells[node[2].id] = cell
            return ("var", cell)
        if tag == "globalvar":
            env = frame.cells[node[3].id].value
            return ("global", env, node[2], node[4])
        if tag == "index":
            obj = self.eval_exp(node[2], frame)
            key = self.eval_exp(node[3], frame)
            return ("index", obj, key, node)
        if tag == "paren":
            return self._prepare_target(node[2], frame)
        # parser should prevent
        self.runtime_error("syntax error", line=node[1], frame=frame)

    def _assign_prepared(self, prep, value, frame, node):
        if prep[0] == "var":
            prep[1].value = value
            return
        if prep[0] == "global":
            env, name, env_kind = prep[1], prep[2], prep[3]
            self.set_index(env, name, value,
                           desc=" (upvalue '_ENV')" if env_kind == "upvalue" else " (local '_ENV')",
                           line=node[1], frame=frame)
            return
        if prep[0] == "index":
            _, obj, key, inode = prep
            self.set_index(obj, key, value, desc=self.expr_desc(inode[2]),
                           line=inode[1], frame=frame)
            return

    def make_closure(self, proto, frame):
        cells = {}
        if frame is not None:
            for v in proto.upvalues:
                cell = frame.cells.get(v.id)
                if cell is None:
                    cell = Cell(None)
                cells[v.id] = cell
        else:
            for v in proto.upvalues:
                cells[v.id] = Cell(None)
        return LuaClosure(proto, cells)

    # ---------- expressions ----------
    def eval_explist(self, exps, frame):
        if not exps:
            return []
        out = []
        for e in exps[:-1]:
            out.append(self.eval_exp(e, frame))
        out.extend(self.eval_multi(exps[-1], frame))
        return out

    def eval_multi(self, node, frame):
        tag = node[0]
        if tag == "call" or tag == "mcall":
            func, args, desc, info = self._eval_call_parts(node, frame)
            frame.current_line = node[1]
            return self.call_value(func, args, desc=desc, call_info=info)
        if tag == "vararg":
            return self._vararg_values(frame, node)
        return [self.eval_exp(node, frame)]

    def _vararg_values(self, frame, node):
        proto = frame.proto
        vv = getattr(proto, "vararg_var", None)
        if vv is not None:
            cell = frame.cells.get(vv.id)
            tbl = cell.value if cell else None
            if not isinstance(tbl, LuaTable):
                self.runtime_error("vararg table has no proper 'n'", line=node[1], frame=frame)
            n = tbl.rawget(b"n")
            if type(n) is not int or n < 0:
                self.runtime_error("vararg table has no proper 'n'", line=node[1], frame=frame)
            return [tbl.get_int(i) for i in range(1, n + 1)]
        return list(frame.varargs)

    def _eval_call_parts(self, node, frame):
        if node[0] == "call":
            fnode = node[2]
            func = self.eval_exp(fnode, frame)
            args = self.eval_explist(node[3], frame) if node[3] else []
            desc = self.expr_desc(fnode)
            info = self.call_info_of(fnode)
            return func, args, desc, info
        else:  # mcall
            onode = node[2]
            obj = self.eval_exp(onode, frame)
            frame.current_line = node[1]
            func = self.index_value(obj, node[3], desc=self.expr_desc(onode),
                                    line=node[1], frame=frame)
            args = self.eval_explist(node[4], frame) if node[4] else []
            desc = " (method '%s')" % node[3].decode("latin1")
            info = (node[3], "method")
            return func, [obj] + list(args), desc, info

    def eval_exp(self, node, frame):
        tag = node[0]
        if tag == "nil":
            return None
        if tag == "true":
            return True
        if tag == "false":
            return False
        if tag == "number":
            return node[2]
        if tag == "string":
            return node[2]
        if tag == "var":
            cell = frame.cells.get(node[2].id)
            return cell.value if cell is not None else None
        if tag == "globalvar":
            frame.current_line = node[1]
            env = frame.cells[node[3].id].value
            return self.index_value(env, node[2],
                                    desc=" (upvalue '_ENV')" if node[4] == "upvalue" else " (local '_ENV')",
                                    line=node[1], frame=frame)
        if tag == "paren":
            vals = self.eval_multi_trunc(node[2], frame)
            return vals
        if tag == "vararg":
            vals = self._vararg_values(frame, node)
            return vals[0] if vals else None
        if tag == "function":
            return self.make_closure(node[2], frame)
        if tag == "table":
            return self._eval_table(node, frame)
        if tag == "index":
            obj = self.eval_exp(node[2], frame)
            key = self.eval_exp(node[3], frame)
            frame.current_line = node[1]
            return self.index_value(obj, key, desc=self.expr_desc(node[2]),
                                    line=node[1], frame=frame)
        if tag == "call" or tag == "mcall":
            vals = self.eval_multi(node, frame)
            return vals[0] if vals else None
        if tag == "unop":
            op = node[2]
            frame.current_line = node[1]
            v = self.eval_exp(node[3], frame)
            frame.current_line = node[1]
            return self.unary_op(op, v, vnode=node[3], line=node[1], frame=frame)
        if tag == "binop":
            op = node[2]
            if op == b"and":
                lv = self.eval_exp(node[3], frame)
                if not truthy(lv):
                    return lv
                return self.eval_exp(node[4], frame)
            if op == b"or":
                lv = self.eval_exp(node[3], frame)
                if truthy(lv):
                    return lv
                return self.eval_exp(node[4], frame)
            lv = self.eval_exp(node[3], frame)
            rv = self.eval_exp(node[4], frame)
            frame.current_line = node[1]
            if op == b"==":
                return self.equals(lv, rv)
            if op == b"~=":
                return not self.equals(lv, rv)
            if op in (b"<", b">", b"<=", b">="):
                return self.compare_op(op, lv, rv, line=node[1], frame=frame)
            if op == b"..":
                return self.concat_op(lv, rv, anode=node[3], bnode=node[4],
                                      line=node[1], frame=frame)
            return self.arith_op(op, lv, rv, anode=node[3], bnode=node[4],
                                 line=node[1], frame=frame)
        raise AssertionError("exp " + str(tag))

    def eval_multi_trunc(self, node, frame):
        vals = self.eval_multi(node, frame)
        return vals[0] if vals else None

    def _eval_table(self, node, frame):
        tbl = LuaTable()
        fields = node[2]
        array_i = 1
        for idx, (kind, kexp, vexp) in enumerate(fields):
            is_last = idx == len(fields) - 1
            if kind == "list":
                if is_last and vexp[0] in ("call", "mcall", "vararg"):
                    vals = self.eval_multi(vexp, frame)
                    for v in vals:
                        if v is not None:
                            tbl.rawset(array_i, v)
                        array_i += 1
                else:
                    v = self.eval_exp(vexp, frame)
                    if v is not None:
                        try:
                            tbl.rawset(array_i, v)
                        except ValueError as ve:
                            self.runtime_error(str(ve), line=node[1], frame=frame)
                    array_i += 1
            else:
                key = self.eval_exp(kexp, frame)
                v = self.eval_exp(vexp, frame)
                try:
                    tbl.rawset(key, v)
                except ValueError as ve:
                    self.runtime_error(str(ve), line=node[1], frame=frame)
        return tbl
