import pickle
from lua_values import *
from lua_parser import parse_source, ParseError

DUMP_HEADER = b"\x1bLua\x55\x00\x19\x93\r\n\x1a\n\x04\x88\xa9\xff\xff\x04xV4\x12\x08\x88\xa9\xff\xff\xff\xff\xff\xff\x08\x00\x00\x00\x00\x00(\x77\xc0"
DUMP_MARKER = b"PYLUA55\x00"

def format_error(source, line, msg):
    if isinstance(msg, str):
        msg = msg.encode("latin1")
    return short_source(source) + b":" + str(line).encode() + b": " + msg

def make_main_closure(interp, proto, env):
    closure = LuaClosure(proto, {})
    for v in proto.upvalues:
        closure.upvalue_cells[v.id] = Cell(None)
    if proto.upvalues:
        first = proto.upvalues[0]
        closure.upvalue_cells[first.id] = Cell(env if env is not None else interp.globals)
    return closure

def strip_shebang_bom(data):
    # mirrors loadfile preprocessing
    if data.startswith(b"\xef\xbb\xbf"):
        data = data[3:]
    if data.startswith(b"#"):
        nl = data.find(b"\n")
        if nl >= 0:
            data = data[nl+1:]
            # keep line numbering: original file line numbers count shebang as line1?
            # Lua skips first line and line numbers start after? It treats first line
            # as comment; errors on following lines report actual file lines (+1).
            data = b"\n" + data
        else:
            data = b""
    return data

def load_binary_proto(interp, data, source, env):
    if not data.startswith(DUMP_HEADER):
        # figure error
        if len(data) < 5 or data[4] != 0x55:
            return None, short_source(source) + b": bad binary format (version mismatch)"
        return None, short_source(source) + b": bad binary format"
    rest = data[len(DUMP_HEADER):]
    if not rest.startswith(DUMP_MARKER):
        return None, short_source(source) + b": bad binary format (corrupted chunk)"
    try:
        proto = pickle.loads(rest[len(DUMP_MARKER):])
    except Exception:
        return None, short_source(source) + b": bad binary format (corrupted chunk)"
    if not isinstance(proto, Proto):
        return None, short_source(source) + b": bad binary format (corrupted chunk)"
    return make_main_closure(interp, proto, env), None

def load_chunk(interp, data, source, mode=b"bt", env=None):
    """Return (closure, err_bytes_or_None)."""
    if mode is None:
        mode = b"bt"
    if isinstance(mode, str):
        mode = mode.encode()
    is_binary = len(data) > 0 and data[0] == 0x1b
    if is_binary and b"b" not in mode:
        return None, b"attempt to load a binary chunk (mode is '" + mode + b"')"
    if not is_binary and b"t" not in mode:
        return None, b"attempt to load a text chunk (mode is '" + mode + b"')"
    if is_binary:
        return load_binary_proto(interp, data, source, env)
    try:
        proto = parse_source(data, source)
    except ParseError as e:
        return None, format_error(source, e.line, e.msg)
    return make_main_closure(interp, proto, env), None

def dump_function(interp, closure, strip=False):
    proto = closure.proto
    payload = pickle.dumps(proto, protocol=4)
    return DUMP_HEADER + DUMP_MARKER + payload
