class PatternError(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg if isinstance(msg, bytes) else msg.encode("latin1")

def _class_pred(letter):
    # letter is lowercase bytes int for class; returns pred(byte)->bool
    if letter == ord('a'):
        return lambda c: (65 <= c <= 90) or (97 <= c <= 122)
    if letter == ord('c'):
        return lambda c: c < 32 or c == 127
    if letter == ord('d'):
        return lambda c: 48 <= c <= 57
    if letter == ord('g'):
        return lambda c: 33 <= c <= 126
    if letter == ord('l'):
        return lambda c: 97 <= c <= 122
    if letter == ord('p'):
        return lambda c: (33 <= c <= 126) and not ((65 <= c <= 90) or (97 <= c <= 122) or (48 <= c <= 57))
    if letter == ord('s'):
        return lambda c: c in (9, 10, 11, 12, 13, 32)
    if letter == ord('u'):
        return lambda c: 65 <= c <= 90
    if letter == ord('w'):
        return lambda c: (65 <= c <= 90) or (97 <= c <= 122) or (48 <= c <= 57)
    if letter == ord('x'):
        return lambda c: (48 <= c <= 57) or (65 <= c <= 70) or (97 <= c <= 102)
    return None

_CLASSES = b"acdg" b"lpsuwx"

class _Parser:
    def __init__(self, pat):
        self.pat = pat
        self.i = 0
        self.n = len(pat)
        self.nodes = []
        self.ncaps = 0
        self.cap_open = []  # stack of capture indexes currently open
        self.cap_closed = set()
        self.anchored = False

    def parse(self):
        if self.n > 0 and self.pat[0] == 94:  # ^
            self.anchored = True
            self.i = 1
        while self.i < self.n:
            self.parse_item()
        if self.cap_open:
            raise PatternError("unfinished capture")
        return self.nodes, self.ncaps, self.anchored

    def parse_item(self):
        pat, i, n = self.pat, self.i, self.n
        c = pat[i]
        if c == 40:  # (
            if i + 1 < n and pat[i + 1] == 41:
                self.ncaps += 1
                if self.ncaps > 32:
                    raise PatternError("too many captures")
                self.nodes.append(("poscap", self.ncaps - 1))
                self.cap_closed.add(self.ncaps - 1)
                self.i += 2
                return
            self.ncaps += 1
            if self.ncaps > 32:
                raise PatternError("too many captures")
            idx = self.ncaps - 1
            self.cap_open.append(idx)
            self.nodes.append(("capstart", idx))
            self.i += 1
            return
        if c == 41:  # )
            if not self.cap_open:
                raise PatternError("invalid pattern capture")
            idx = self.cap_open.pop()
            self.cap_closed.add(idx)
            self.nodes.append(("capend", idx))
            self.i += 1
            return
        if c == 36 and i == n - 1:  # $ at end
            self.nodes.append(("endanchor",))
            self.i += 1
            return
        # single-char item or special
        node, is_single = self.parse_single()
        if is_single:
            quant = None
            if self.i < n and pat[self.i] in (42, 43, 45, 63):  # * + - ?
                quant = chr(pat[self.i])
                self.i += 1
            self.nodes.append(("char", node, quant))
        else:
            self.nodes.append(node)

    def parse_single(self):
        """Return (matcher_pred_or_node, is_single)."""
        pat, i, n = self.pat, self.i, self.n
        c = pat[i]
        if c == 37:  # %
            if i + 1 >= n:
                raise PatternError("malformed pattern (ends with '%')")
            d = pat[i + 1]
            if 49 <= d <= 57:  # 1-9 backref
                idx = d - 49
                if idx not in self.cap_closed:
                    raise PatternError("invalid capture index %%%d" % (idx + 1))
                self.i += 2
                return ("backref", idx), False
            if d == ord('b'):
                if i + 3 >= n:
                    raise PatternError("malformed pattern (missing arguments to '%b')")
                x, y = pat[i + 2], pat[i + 3]
                self.i += 4
                return ("balanced", x, y), False
            if d == ord('f'):
                if i + 2 >= n or pat[i + 2] != 91:
                    raise PatternError("malformed pattern (missing '[' after '%f')")
                self.i += 2
                pred = self.parse_set()
                return ("frontier", pred), False
            self.i += 2
            if (97 <= d <= 122) and d in _CLASSES:
                return _class_pred(d), True
            if (65 <= d <= 90) and (d + 32) in _CLASSES:
                base = _class_pred(d + 32)
                return (lambda ch, base=base: not base(ch)), True
            # escaped char literal (including unknown letters treated literally as Lua does for %x? all non-class)
            return (lambda ch, d=d: ch == d), True
        if c == 91:  # [
            pred = self.parse_set()
            return pred, True
        if c == 46:  # .
            self.i += 1
            return (lambda ch: True), True
        # literal
        self.i += 1
        return (lambda ch, c=c: ch == c), True

    def parse_set(self):
        # self.pat[self.i] == '['
        pat, n = self.pat, self.n
        i = self.i + 1
        neg = False
        if i < n and pat[i] == 94:  # ^
            neg = True
            i += 1
        preds = []
        singles = set()
        ranges = []
        first = True
        while True:
            if i >= n:
                raise PatternError("malformed pattern (missing ']')")
            if pat[i] == 93 and not first:  # ]
                i += 1
                break
            first = False
            # one element
            if pat[i] == 37:  # %
                if i + 1 >= n:
                    raise PatternError("malformed pattern (ends with '%')")
                d = pat[i + 1]
                if (97 <= d <= 122) and d in _CLASSES:
                    preds.append(_class_pred(d))
                    i += 2
                    continue
                if (65 <= d <= 90) and (d + 32) in _CLASSES:
                    base = _class_pred(d + 32)
                    preds.append(lambda ch, base=base: not base(ch))
                    i += 2
                    continue
                elem = d
                i += 2
            else:
                elem = pat[i]
                i += 1
            # range?
            if i < n and pat[i] == 45 and i + 1 < n and pat[i + 1] != 93:
                i += 1  # skip '-'
                if pat[i] == 37:
                    if i + 1 >= n:
                        raise PatternError("malformed pattern (ends with '%')")
                    endc = pat[i + 1]
                    i += 2
                else:
                    endc = pat[i]
                    i += 1
                ranges.append((elem, endc))
            else:
                singles.add(elem)
        self.i = i
        singles_f = frozenset(singles)
        ranges_f = tuple(ranges)
        preds_f = tuple(preds)
        def pred(ch, singles_f=singles_f, ranges_f=ranges_f, preds_f=preds_f, neg=neg):
            ok = ch in singles_f
            if not ok:
                for a, b in ranges_f:
                    if a <= ch <= b:
                        ok = True
                        break
            if not ok:
                for p in preds_f:
                    if p(ch):
                        ok = True
                        break
            return (not ok) if neg else ok
        return pred

def compile_pattern(pat):
    p = _Parser(pat)
    return p.parse()

class Matcher:
    def __init__(self, subject, nodes, ncaps):
        self.s = subject
        self.nodes = nodes
        self.ncaps = ncaps

    def match_at(self, start):
        caps = [(None, None)] * self.ncaps  # (start, end) or ('pos', value)
        for endpos, finalcaps in self._run(0, start, caps):
            return endpos, finalcaps
        return None

    def _run(self, ni, pos, caps):
        nodes = self.nodes
        s = self.s
        if ni >= len(nodes):
            yield pos, caps
            return
        node = nodes[ni]
        typ = node[0]
        if typ == "char":
            pred, quant = node[1], node[2]
            if quant is None:
                if pos < len(s) and pred(s[pos]):
                    yield from self._run(ni + 1, pos + 1, caps)
            elif quant == "?":
                if pos < len(s) and pred(s[pos]):
                    yield from self._run(ni + 1, pos + 1, caps)
                yield from self._run(ni + 1, pos, caps)
            elif quant in ("*", "+"):
                maxc = 0
                while pos + maxc < len(s) and pred(s[pos + maxc]):
                    maxc += 1
                minc = 1 if quant == "+" else 0
                for count in range(maxc, minc - 1, -1):
                    yield from self._run(ni + 1, pos + count, caps)
            elif quant == "-":
                count = 0
                while True:
                    yield from self._run(ni + 1, pos + count, caps)
                    if pos + count < len(s) and pred(s[pos + count]):
                        count += 1
                    else:
                        break
            return
        if typ == "capstart":
            newcaps = list(caps)
            newcaps[node[1]] = (pos, None)
            yield from self._run(ni + 1, pos, newcaps)
            return
        if typ == "capend":
            newcaps = list(caps)
            st = newcaps[node[1]][0]
            newcaps[node[1]] = (st, pos)
            yield from self._run(ni + 1, pos, newcaps)
            return
        if typ == "poscap":
            newcaps = list(caps)
            newcaps[node[1]] = ("pos", pos + 1)
            yield from self._run(ni + 1, pos, newcaps)
            return
        if typ == "backref":
            cap = caps[node[1]]
            if cap[0] == "pos":
                # backreferencing a position capture fails to match
                return
            st, en = cap
            if st is None or en is None:
                return
            txt = s[st:en]
            if s[pos:pos + len(txt)] == txt:
                yield from self._run(ni + 1, pos + len(txt), caps)
            return
        if typ == "balanced":
            _, x, y = node
            if pos >= len(s) or s[pos] != x:
                return
            depth = 1
            j = pos + 1
            while j < len(s):
                if s[j] == y:
                    depth -= 1
                    if depth == 0:
                        yield from self._run(ni + 1, j + 1, caps)
                        return
                elif s[j] == x:
                    depth += 1
                j += 1
            return
        if typ == "frontier":
            pred = node[1]
            prev = s[pos - 1] if pos > 0 else 0
            nxt = s[pos] if pos < len(s) else 0
            if (not pred(prev)) and pred(nxt):
                yield from self._run(ni + 1, pos, caps)
            return
        if typ == "endanchor":
            if pos == len(s):
                yield from self._run(ni + 1, pos, caps)
            return
        raise AssertionError(typ)

    def captures_values(self, caps):
        vals = []
        for cap in caps:
            if cap[0] == "pos":
                vals.append(cap[1])
            elif cap[0] is None:
                vals.append(None)
            else:
                vals.append(self.s[cap[0]:cap[1]])
        return vals

def find_pattern(subject, pat, start0):
    """Search; returns (start0idx, end0idx_exclusive, captures_list) or None."""
    nodes, ncaps, anchored = compile_pattern(pat)
    m = Matcher(subject, nodes, ncaps)
    if anchored:
        r = m.match_at(start0)
        if r is None:
            return None
        endpos, caps = r
        return start0, endpos, m.captures_values(caps)
    for st in range(start0, len(subject) + 1):
        r = m.match_at(st)
        if r is not None:
            endpos, caps = r
            return st, endpos, m.captures_values(caps)
    return None

def match_pattern_at(subject, compiled, start0):
    nodes, ncaps, anchored = compiled
    m = Matcher(subject, nodes, ncaps)
    r = m.match_at(start0)
    if r is None:
        return None
    endpos, caps = r
    return endpos, m.captures_values(caps)
