import math
import struct as _struct
from lua_values import *
from lua_libutil import *
from lua_patterns import compile_pattern, Matcher, PatternError

FN = b"string."

def _posrel(pos, length):
    if pos >= 0:
        return pos
    if -pos > length:
        return 0
    return length + pos + 1

def _clamp_pos(pos, length):
    return max(1, min(pos, length + 1))

def _pattern_error(interp, e):
    interp.lib_error(e.msg)

# ---------- basic ----------

def str_len(interp, args):
    s = check_string(interp, FN+b"len", args, 1)
    return [len(s)]

def str_byte(interp, args):
    s = check_string(interp, FN+b"byte", args, 1)
    i = opt_integer(interp, FN+b"byte", args, 2, 1)
    j = opt_integer(interp, FN+b"byte", args, 3, i)
    i = _clamp_pos(_posrel(i, len(s)), len(s))
    j = _clamp_pos(_posrel(j, len(s)), len(s))
    # Lua clamps: i<1 ->1, j>len -> len ( _clamp gives len+1 for j? fix)
    j = min(j, len(s))
    if i > j:
        return []
    return [s[k - 1] for k in range(i, j + 1)]

def str_char(interp, args):
    out = bytearray()
    for idx, a in enumerate(args):
        v = check_integer(interp, FN+b"char", args, idx + 1)
        out.append(v & 0xff)
    return [bytes(out)]

def str_sub(interp, args):
    s = check_string(interp, FN+b"sub", args, 1)
    i = check_integer(interp, FN+b"sub", args, 2)
    j = opt_integer(interp, FN+b"sub", args, 3, -1)
    n = len(s)
    i = _posrel(i, n)
    j = _posrel(j, n)
    if i < 1:
        i = 1
    if j > n:
        j = n
    if i > j:
        return [b""]
    return [s[i - 1:j]]

def str_reverse(interp, args):
    s = check_string(interp, FN+b"reverse", args, 1)
    return [s[::-1]]

def _ascii_map(s, upper):
    out = bytearray(s)
    for i, c in enumerate(out):
        if upper and 97 <= c <= 122:
            out[i] = c - 32
        if not upper and 65 <= c <= 90:
            out[i] = c + 32
    return bytes(out)

def str_lower(interp, args):
    s = check_string(interp, FN+b"lower", args, 1)
    return [_ascii_map(s, False)]

def str_upper(interp, args):
    s = check_string(interp, FN+b"upper", args, 1)
    return [_ascii_map(s, True)]

def str_rep(interp, args):
    s = check_string(interp, FN+b"rep", args, 1)
    n = check_integer(interp, FN+b"rep", args, 2)
    sep = opt_string(interp, FN+b"rep", args, 3, b"")
    if n <= 0:
        return [b""]
    if len(s) * n + max(0, n - 1) * len(sep) > (1 << 31):
        interp.lib_error(b"resulting string too large")
    if n == 1:
        return [s]
    return [sep.join([s] * n)]

def str_dump(interp, args):
    v = args[0] if args else None
    if not isinstance(v, LuaClosure):
        arg_error(interp, FN+b"dump", 1, b"Lua function expected")
    strip = False
    if len(args) > 1:
        strip = truthy(args[1])
    from lua_loader import dump_function
    return [dump_function(interp, v, strip)]

# ---------- patterns ----------

def _get_search(interp, args, fullname):
    s = check_string(interp, fullname, args, 1)
    pat = check_string(interp, fullname, args, 2)
    init = opt_integer(interp, fullname, args, 3, 1)
    n = len(s)
    start = _posrel(init, n)
    if start < 1:
        start = 1
    return s, pat, start

def _do_find(interp, s, pat, start1, plain=False):
    start0 = start1 - 1
    if start0 > len(s):
        return None
    if plain:
        idx = s.find(pat, start0)
        if idx < 0:
            return None
        return (idx, idx + len(pat), [])
    try:
        compiled = compile_pattern(pat)
    except PatternError as e:
        _pattern_error(interp, e)
    nodes, ncaps, anchored = compiled
    m = Matcher(s, nodes, ncaps)
    if anchored:
        r = m.match_at(start0)
        if r:
            endpos, caps = r
            return (start0, endpos, m.captures_values(caps))
        return None
    for st in range(start0, len(s) + 1):
        r = m.match_at(st)
        if r:
            endpos, caps = r
            return (st, endpos, m.captures_values(caps))
    return None

def str_find(interp, args):
    s, pat, start = _get_search(interp, args, FN+b"find")
    plain = False
    if len(args) > 3:
        plain = truthy(args[3])
    if start > len(s) + 1:
        return [None]
    r = _do_find(interp, s, pat, start, plain)
    if r is None:
        return [None]
    a, b, caps = r
    # b is exclusive end following Lua internal; return b (as inclusive), since b-1 0-based -> Lua number b
    return [a + 1, b] + list(caps)

def str_match(interp, args):
    s, pat, start = _get_search(interp, args, FN+b"match")
    if start > len(s) + 1:
        return [None]
    r = _do_find(interp, s, pat, start, False)
    if r is None:
        return [None]
    a, b, caps = r
    if caps:
        return list(caps)
    return [s[a:b]]

def make_gmatch_iterator(interp, s, pat, compiled):
    state = {"pos": 0, "lastend": -1}
    nodes, ncaps, anchored = compiled
    m = Matcher(s, nodes, ncaps)
    def iterator(itp, iargs):
        # gmatch_aux algorithm: search from state pos
        ls = len(s)
        start = state["pos"]
        for st in range(start, ls + 1):
            r = m.match_at(st)
            if r is not None:
                endpos, caps = r
                if endpos == state["lastend"] and st == state.get("laststart", -2):
                    # avoid same empty match repeated: advance
                    # Lua: if match is empty and same as last, move one char
                    # Simplification: if this is an empty match at the same
                    # position as previous match end, skip a char.
                    if st < ls:
                        continue_search = True
                        # set pos to st+1 and restart search loop via recursion emulation
                        state["pos"] = st + 1
                        return iterator(itp, iargs)
                    else:
                        state["pos"] = ls + 1
                        return []
                state["pos"] = endpos
                state["lastend"] = endpos
                state["laststart"] = st
                vals = m.captures_values(caps)
                if vals:
                    return vals
                return [s[st:endpos]]
            if anchored:
                break
        state["pos"] = ls + 1
        return []
    return BuiltinFunction(b"gmatch_iterator", iterator)

def str_gmatch(interp, args):
    s = check_string(interp, FN+b"gmatch", args, 1)
    pat = check_string(interp, FN+b"gmatch", args, 2)
    try:
        compiled = compile_pattern(pat)
    except PatternError as e:
        _pattern_error(interp, e)
    return [make_gmatch_iterator(interp, s, pat, compiled)]

def _replacement_string(interp, repl, s, a, b, caps):
    out = bytearray()
    i = 0
    while i < len(repl):
        c = repl[i]
        if c != 37:  # %
            out.append(c)
            i += 1
            continue
        if i + 1 >= len(repl):
            interp.lib_error(b"invalid use of '%' in replacement string")
        d = repl[i + 1]
        if d == 37:
            out.append(37)
            i += 2
            continue
        if 48 <= d <= 57:
            idx = d - 48
            if idx == 0:
                out += s[a:b]
            else:
                if idx > len(caps):
                    interp.lib_error(("invalid capture index %%%d" % idx).encode())
                val = caps[idx - 1]
                if type(val) is int:
                    interp.lib_error(b"attempt to use a position capture as a string")
                out += val
            i += 2
            continue
        interp.lib_error(b"invalid use of '%' in replacement string")
    return bytes(out)

def str_gsub(interp, args):
    s = check_string(interp, FN+b"gsub", args, 1)
    pat = check_string(interp, FN+b"gsub", args, 2)
    repl = check_any(interp, FN+b"gsub", args, 3)
    maxn = opt_integer(interp, FN+b"gsub", args, 4, None)
    if maxn is None:
        maxn = len(s) + 1
    # validate repl type
    rt = lua_type(repl)
    if rt not in ("string", "number", "table", "function"):
        arg_error(interp, FN+b"gsub", 3,
                  ("string/function/table expected, got %s" % rt).encode())
    if is_number(repl):
        repl = number_to_bytes(repl)
        rt = "string"
    try:
        compiled = compile_pattern(pat)
    except PatternError as e:
        _pattern_error(interp, e)
    nodes, ncaps, anchored = compiled
    m = Matcher(s, nodes, ncaps)
    out = bytearray()
    nsub = 0
    pos = 0
    ls = len(s)
    while nsub < maxn:
        r = m.match_at(pos) if pos <= ls else None
        if r is not None:
            endpos, caps_obj = r
            caps = m.captures_values(caps_obj)
            nsub += 1
            # compute replacement
            if rt == "string":
                out += _replacement_string(interp, repl, s, pos, endpos, caps)
            elif rt == "table":
                key = caps[0] if caps else s[pos:endpos]
                val = interp.index_value(repl, key)
                if val is None or val is False:
                    out += s[pos:endpos]
                elif type(val) is bytes:
                    out += val
                elif is_number(val):
                    out += number_to_bytes(val)
                else:
                    interp.lib_error(("invalid replacement value (a %s)" % lua_type(val)).encode())
            else:  # function
                fargs = list(caps) if caps else [s[pos:endpos]]
                res = interp.call_value(repl, fargs)
                val = res[0] if res else None
                if val is None or val is False:
                    out += s[pos:endpos]
                elif type(val) is bytes:
                    out += val
                elif is_number(val):
                    out += number_to_bytes(val)
                else:
                    interp.lib_error(("invalid replacement value (a %s)" % lua_type(val)).encode())
            if endpos > pos:
                pos = endpos
            else:
                # empty match: copy next char if any
                if pos < ls:
                    out.append(s[pos])
                    pos += 1
                else:
                    pos = endpos + 1
        else:
            if pos >= ls:
                break
            out.append(s[pos])
            pos += 1
        if anchored:
            break
        if pos > ls:
            break
    out += s[pos:]
    return [bytes(out), nsub]

# ---------- format ----------

def _quote_string(s):
    out = bytearray(b'"')
    i = 0
    while i < len(s):
        c = s[i]
        if c == 34 or c == 92:
            out.append(92); out.append(c)
        elif c == 10:
            out.append(92); out.append(10)
        elif c < 32 or c == 127:
            # \ddd; use 3 digits if next char is a digit, else minimal
            nxt = s[i + 1] if i + 1 < len(s) else None
            if nxt is not None and 48 <= nxt <= 57:
                out += ("\\%03d" % c).encode()
            else:
                out += ("\\%d" % c).encode()
        else:
            out.append(c)
        i += 1
    out.append(34)
    return bytes(out)

def _hex_float(x, prec):
    """C %a formatting. prec=None -> exact shortest (strip trailing zeros)."""
    if math.isnan(x):
        return "nan"
    if math.isinf(x):
        return "-inf" if x < 0 else "inf"
    sign = "-" if math.copysign(1.0, x) < 0 else ""
    ax = abs(x)
    if ax == 0.0:
        if prec is None or prec == 0:
            return sign + "0x0p+0"
        return sign + "0x0." + "0" * prec + "p+0"
    mant, exp = math.frexp(ax)  # ax = mant * 2^exp, mant in [0.5,1)
    # C %a uses mantissa in [1,2)
    mant *= 2
    exp -= 1
    # mantissa as exact integer of 53 bits
    # mant in [1,2): value = m_int / 2^52
    m_int = int(round(mant * (1 << 52)))
    # hex digits: 13 hex digits after point represent 52 bits
    frac = m_int & ((1 << 52) - 1)
    hexfrac_full = "%013x" % frac
    if prec is None:
        hexfrac = hexfrac_full.rstrip("0")
        if hexfrac:
            return "%s0x1.%sp%+d" % (sign, hexfrac, exp)
        return "%s0x1p%+d" % (sign, exp)
    # round to prec hex digits
    if prec >= 13:
        hexfrac = hexfrac_full + "0" * (prec - 13)
    else:
        shift = (13 - prec) * 4
        keep_mask = (~0 << shift) & ((1 << 52) - 1)
        # rounding: add half of dropped
        rounded = frac + (1 << (shift - 1)) if shift > 0 else frac
        if rounded >= (1 << 52):
            # overflow into integer part -> 2.0 => renormalize to 1.0 * 2^(exp+1)
            rounded = 0
            exp += 1
            hexfrac = "0" * prec
            if prec == 0:
                return "%s0x1p%+d" % (sign, exp)
            return "%s0x1.%sp%+d" % (sign, hexfrac, exp)
        rounded &= keep_mask
        hexfrac = ("%013x" % rounded)[:prec] if prec > 0 else ""
    if prec == 0:
        return "%s0x1p%+d" % (sign, exp)
    return "%s0x1.%sp%+d" % (sign, hexfrac, exp)

def _apply_width(text, width, flags, zero_pad_ok=True):
    if width is None or len(text) >= width:
        return text
    pad = width - len(text)
    if "-" in flags:
        return text + " " * pad
    if zero_pad_ok and "0" in flags:
        # zeros after sign and 0x prefix
        prefix_len = 0
        t = text
        if t[:1] in ("-", "+", " "):
            prefix_len = 1
        if t[prefix_len:prefix_len+2] in ("0x", "0X"):
            prefix_len += 2
        return t[:prefix_len] + "0" * pad + t[prefix_len:]
    return " " * pad + text

def _format_int_core(ival, conv, flags, prec):
    if conv in "di":
        neg = ival < 0
        digits = str(abs(ival))
    elif conv == "u":
        neg = False
        digits = str(ival & MASK64)
    elif conv == "o":
        neg = False
        digits = "%o" % (ival & MASK64)
    elif conv == "x":
        neg = False
        digits = "%x" % (ival & MASK64)
    elif conv == "X":
        neg = False
        digits = "%X" % (ival & MASK64)
    # precision: minimum digits
    if prec is not None:
        if prec == 0 and digits == "0" and conv != "o":
            digits = ""
        elif len(digits) < prec:
            digits = "0" * (prec - len(digits)) + digits
    prefix = ""
    if "#" in flags:
        if conv == "o" and not digits.startswith("0"):
            prefix = "0"
        if conv in "xX" and (ival & MASK64) != 0:
            prefix = "0x" if conv == "x" else "0X"
    sign = ""
    if conv in "di":
        if neg:
            sign = "-"
        elif "+" in flags:
            sign = "+"
        elif " " in flags:
            sign = " "
    return sign + prefix + digits

def str_format(interp, args):
