            p = 6 if prec is None else prec
            spec_flags = ""
            if "#" in flags:
                spec_flags += "#"
            if "0" in flags and "-" not in flags:
                spec_flags += "0"
            if "+" in flags:
                spec_flags += "+"
            elif " " in flags:
                spec_flags += " "
            if conv in "gG" and p == 0:
                p = 1
            cconv = conv.lower()
            core = format(fv, "%s.%d%s" % (spec_flags, p, cconv))
            if upper:
                core = core.upper()
            core = _apply_width(core, width, flags if "0" not in spec_flags else flags)
            # width already handled if zero pad via spec? Python didn't include width; _apply_width pads
            out += core.encode("ascii")
        elif conv == "c":
            num = value
            if type(value) is bytes:
                num = parse_number_string(value)
            if not is_number(num):
                arg_error(interp, FN+b"format", anum,
                          ("number expected, got %s" % lua_type(value)).encode())
            iv = to_integer_value(num)
            if iv is None:
                arg_error(interp, FN+b"format", anum, b"number has no integer representation")
            ch = bytes([iv & 0xff])
            text = ch.decode("latin1")
