                sval = sval[:prec]
            text = sval.decode("latin1")
            text = _apply_width(text, width, flags, zero_pad_ok=False)
            out += text.encode("latin1")
        elif conv == "p":
            if isinstance(value, (LuaTable, LuaClosure, BuiltinFunction, UserData, LuaThreadObj)):
                core = "0x%x" % interp.obj_addr(value)
