            else:
                out += _struct.pack("<d" if pf.endian == "<" else ">d", float(num))
            continue
        # integer types
        num = value
        if type(value) is bytes:
            num = parse_number_string(value)
        if not is_number(num):
            arg_error(interp, FN+b"pack", anum, ("number expected, got %s" % lua_type(value)).encode())
        iv = to_integer_value(num)
        if iv is None:
            arg_error(interp, FN+b"pack", anum, b"number has no integer representation")
        out += _pack_int_bytes(iv, sz, pf.endian, c.islower())
    return [bytes(out)]

def _alignment_padding_bytes(offset, size, maxalign):
    return b"\x00" * _alignment_padding(offset, size, maxalign)

def str_unpack(interp, args):
    fmt = check_string(interp, FN+b"unpack", args, 1)
    data = check_string(interp, FN+b"unpack", args, 2)
    pos = opt_integer(interp, FN+b"unpack", args, 3, 1)
    start = _posrel(pos, len(data))
    if start < 1:
        start = 1
    idx = start - 1
    pf = _PackFmt(fmt)
    results = []
    def need(nbytes):
        if idx + nbytes > len(data):
            arg_error(interp, FN+b"unpack", 2, b"data string too short")
    while True:
        opt = pf.next_option(interp, FN+b"unpack")
        if opt is None:
            break
        if opt[0] in ("endian", "align"):
            continue
        c, size = opt
        if c == "x":
            need(1); idx += 1
            continue
        if c == "X":
            save_i = pf.i
            nopt = pf.next_option(interp, FN+b"unpack")
            if nopt is None or nopt[0] in ("endian", "align"):
                arg_error(interp, FN+b"unpack", 1, b"missing format option after 'X'")
            nsize = _pack_size_of(interp, FN+b"unpack", nopt)
            if nsize is None:
                nsize = 1
            pf.i = save_i
            idx += _alignment_padding(idx, nsize, pf.maxalign)
            continue
        if c == "c":
            if size is None:
                arg_error(interp, FN+b"unpack", 1, b"missing size for format option 'c'")
            need(size)
            results.append(data[idx:idx+size]); idx += size
            continue
        if c == "z":
            end = data.find(b"\x00", idx)
            if end < 0:
                arg_error(interp, FN+b"unpack", 2, b"data string too short")
            results.append(data[idx:end]); idx = end + 1
            continue
        if c == "s":
            lensize = size if size is not None else 8
            idx += _alignment_padding(idx, lensize, pf.maxalign)
            need(lensize)
            ln = int.from_bytes(data[idx:idx+lensize], "little" if pf.endian == "<" else "big")
            idx += lensize
            need(ln)
            results.append(data[idx:idx+ln]); idx += ln
            continue
        sz = _pack_size_of(interp, FN+b"unpack", opt)
        if sz is None:
            arg_error(interp, FN+b"unpack", 1, ("invalid format option '%s'" % c).encode())
        idx += _alignment_padding(idx, sz, pf.maxalign)
        need(sz)
        raw = data[idx:idx+sz]; idx += sz
        if c in "fdn":
            if c == "f":
                results.append(_struct.unpack("<f" if pf.endian == "<" else ">f", raw)[0])
            else:
                results.append(_struct.unpack("<d" if pf.endian == "<" else ">d", raw)[0])
