        if c.islower() or c in "i":
            # signed types: b,h,l,j,i
            if c in "bhlji":
                bits = 8 * sz
                if unsigned >= (1 << (bits - 1)):
                    unsigned -= (1 << bits)
                results.append(unsigned)
            else:
                results.append(unsigned if unsigned <= INT_MAX else unsigned - (1 << 64))
        else:
            # unsigned: values > INT_MAX wrap to signed Lua integer
            results.append(wrap_int(unsigned))
    results.append(idx + 1)
    return results

LIB = {
    b"len": str_len, b"byte": str_byte, b"char": str_char, b"sub": str_sub,
    b"reverse": str_reverse, b"lower": str_lower, b"upper": str_upper,
    b"rep": str_rep, b"dump": str_dump, b"find": str_find, b"match": str_match,
    b"gmatch": str_gmatch, b"gsub": str_gsub, b"format": str_format,
    b"pack": str_pack, b"packsize": str_packsize, b"unpack": str_unpack,
}
