        if type(v) is bytes:
            return [parse_number_string(v)]
        return [None]
    base = check_integer(interp, b"tonumber", args, 2)
    if type(v) is not bytes:
        arg_error(interp, b"tonumber", 1, ("string expected, got %s" % lua_type(v)).encode())
    if not (2 <= base <= 36):
        arg_error(interp, b"tonumber", 2, b"base out of range")
    s = v.strip(b" \t\n\v\f\r")
    if not s:
        return [None]
    neg = False
    if s[:1] in (b"+", b"-"):
        neg = s[:1] == b"-"
        s = s[1:]
    if not s:
        return [None]
    val = 0
    ok = True
    for c in s:
        if 48 <= c <= 57:
            d = c - 48
        elif 97 <= c <= 122:
            d = c - 97 + 10
        elif 65 <= c <= 90:
            d = c - 65 + 10
        else:
            ok = False; break
        if d >= base:
            ok = False; break
        val = val * base + d
    if not ok:
        return [None]
    if neg:
        val = -val
    return [wrap_int(val)]

