def _error_location(interp, level):
    """Return (source,line) for luaL_where semantics used by error()/assert."""
    th = interp.current_thread()
    frames = th.frames
    # skip innermost C frame (error itself)
    idx = len(frames) - 1
    if idx >= 0 and frames[idx].is_c:
        idx -= 1
    # level 1 = frame at idx, level 2 = caller of that, etc.
    target = idx - (level - 1)
    if target < 0:
