    opt = b"collect"
    if args and args[0] is not None:
        opt = check_string(interp, b"collectgarbage", args, 1)
    if opt == b"collect":
        import gc as pygc
        pygc.collect()
        return [0]
    if opt == b"count":
        import gc as pygc
        # report something plausible: use object count scaled
        return [len(pygc.get_objects()) / 1024.0]
    if opt == b"stop":
        interp.gc_running = False
        return [0]
    if opt == b"restart":
        interp.gc_running = True
        return [0]
    if opt == b"step":
        if len(args) > 1:
            check_integer(interp, b"collectgarbage", args, 2)
        import gc as pygc
        pygc.collect()
        return [False]
    if opt == b"isrunning":
        return [interp.gc_running]
    if opt in (b"incremental", b"generational"):
        old = interp.gc_mode
        interp.gc_mode = opt.decode()
        return [old.encode()]
    if opt == b"param":
        param = check_string(interp, b"collectgarbage", args, 2)
        valid = {b"pause", b"stepmul", b"stepsize", b"minormul"}
        if param not in valid:
            arg_error(interp, b"collectgarbage", 2, (b"invalid option '" + param + b"'"))
        key = param.decode()
        if len(args) > 2 and args[2] is not None:
            val = check_integer(interp, b"collectgarbage", args, 3)
            old = interp.gc_params[key]
            interp.gc_params[key] = val
            return [old]
        return [interp.gc_params[key]]
    arg_error(interp, b"collectgarbage", 1, (b"invalid option '" + opt + b"'"))

def b_warn(interp, args):
    if not args:
        arg_error(interp, b"warn", 1, b"string expected, got no value")
    # control messages when single argument exactly @on/@off
    if len(args) == 1 and type(args[0]) is bytes and args[0] in (b"@on", b"@off"):
        interp.warn_state = args[0] == b"@on"
        return []
    parts = []
    for i, a in enumerate(args):
        parts.append(check_string(interp, b"warn", args, i + 1))
    if interp.warnings_on and interp.warn_state:
        try:
            sys.stderr.buffer.write(b"Lua warning: " + b"".join(parts) + b"\n")
            sys.stderr.buffer.flush()
        except Exception:
            pass
    return []

