class _Xoshiro:
    def __init__(self):
        import random as _r
        # initial state from system entropy/time like Lua default
        n1 = int(time.time()) & 0xffffffff
        n2 = (os.getpid() if hasattr(os, "getpid") else 0) & 0xffffffff
