        self._seed_vals = (wrap_int(n1), wrap_int(n2))
        self.reseed(n1, n2)
    def reseed(self, n1, n2):
        M = MASK64
        PHI = 0x9e3779b97f4a7c15
        # splitmix-like expansion (approximation of Lua's seeding)
        s = (n1 & M)
        out = []
        state = s ^ (n2 & M)
        for i in range(4):
            state = (state + PHI) & M
            z = state
            z = ((z ^ (z >> 30)) * 0xbf58476d1ce4e5b9) & M
            z = ((z ^ (z >> 27)) * 0x94d049bb133111eb) & M
            out.append(z ^ (z >> 31))
        self.s = out
        for _ in range(16):
            self.next()
    def next(self):
        M = MASK64
        s = self.s
        result = (((s[1] * 5) & M) << 7 | ((s[1] * 5) & M) >> 57) & M
        result = (result * 9) & M
        t = (s[1] << 17) & M
        s[2] ^= s[0]
        s[3] ^= s[1]
        s[1] ^= s[2]
        s[0] ^= s[3]
        s[2] ^= t
        s[3] = ((s[3] << 45) | (s[3] >> 19)) & M
