# ---------------- table library ----------------

def _len_of(interp, t):
    # luaL_len semantics
    mm = interp.get_metafield(t, b"__len") if isinstance(t, LuaTable) else None
    if isinstance(t, LuaTable) and mm is None:
        return t.border()
    r = interp.unary_op(b"#", t)
    # convert to integer if needed
    if type(r) is int:
        return r
    iv = to_integer_value(r) if is_number(r) else None
    if iv is None:
        interp.lib_error(b"object length is not an integer")
    return iv

def tbl_concat(interp, args):
    t = check_table(interp, b"table.concat", args, 1)
    sep = opt_string(interp, b"table.concat", args, 2, b"")
    i = opt_integer(interp, b"table.concat", args, 3, 1)
    j = opt_integer(interp, b"table.concat", args, 4, None)
    if j is None:
        j = _len_of(interp, t)
    parts = []
    for k in range(i, j + 1):
        v = interp.index_value(t, k)
        if type(v) is bytes:
            parts.append(v)
        elif is_number(v):
            parts.append(number_to_bytes(v))
        else:
            interp.lib_error(("invalid value (at index %d) in table for 'concat'" % k).encode())
    return [sep.join(parts)]

def tbl_create(interp, args):
    n1 = check_integer(interp, b"table.create", args, 1)
    n2 = opt_integer(interp, b"table.create", args, 2, 0)
    for (idx, n) in ((1, n1), (2, n2)):
        if n < 0 or n > 2147483647:
            arg_error(interp, b"table.create", idx, b"out of range")
    return [LuaTable()]

def tbl_insert(interp, args):
    if len(args) not in (2, 3):
        interp.lib_error(b"wrong number of arguments to 'insert'")
    t = check_table(interp, b"table.insert", args, 1)
    n = _len_of(interp, t)
    if len(args) == 2:
        pos = n + 1
        value = args[1]
    else:
        pos = check_integer(interp, b"table.insert", args, 2)
        value = args[2]
        if pos < 1 or pos > n + 1:
            interp.lib_error(b"position out of bounds")
    for i in range(n, pos - 1, -1):
        v = interp.index_value(t, i)
        interp.set_index(t, i + 1, v)
    interp.set_index(t, pos, value)
    return []

def tbl_remove(interp, args):
    t = check_table(interp, b"table.remove", args, 1)
    n = _len_of(interp, t)
    pos = opt_integer(interp, b"table.remove", args, 2, n)
    if n == 0:
        # remove with explicit pos on empty still nil if pos==? Lua allows pos==0? handled below
        if len(args) < 2:
            return [None]
        if pos != 0 and pos != 1:
            interp.lib_error(b"position out of bounds")
        return [None]
    if pos < 1 or pos > n:
        if pos == n + 1 and len(args) >= 2:
            interp.lib_error(b"position out of bounds")
        interp.lib_error(b"position out of bounds")
    removed = interp.index_value(t, pos)
    for i in range(pos, n):
        interp.set_index(t, i, interp.index_value(t, i + 1))
    interp.set_index(t, n, None)
    return [removed]

def tbl_move(interp, args):
    a = check_table(interp, b"table.move", args, 1)
    f = check_integer(interp, b"table.move", args, 2)
    e = check_integer(interp, b"table.move", args, 3)
    tpos = check_integer(interp, b"table.move", args, 4)
    dest = a
    if len(args) > 4 and args[4] is not None:
        dest = check_table(interp, b"table.move", args, 5)
    if e < f:
        return [dest]
    n = e - f + 1
    if tpos > INT_MAX - (n - 1) or (tpos - f) > 10**9:
        interp.lib_error(b"too many elements to move")
    if dest is a and tpos > f:
        rng = range(n - 1, -1, -1)
    else:
        rng = range(n)
    for k in rng:
        v = interp.index_value(a, f + k)
        interp.set_index(dest, tpos + k, v)
    return [dest]

def tbl_pack(interp, args):
    t = LuaTable()
    for i, v in enumerate(args):
        if v is not None:
            t.rawset(i + 1, v)
    t.rawset(b"n", len(args))
    return [t]

def tbl_unpack(interp, args):
    t = check_table(interp, b"table.unpack", args, 1)
    i = opt_integer(interp, b"table.unpack", args, 2, 1)
    j = opt_integer(interp, b"table.unpack", args, 3, None)
    if j is None:
        j = _len_of(interp, t)
    if i > j:
        return []
    n = j - i + 1
    if n < 0 or n > 1000000:
        interp.lib_error(b"too many results to unpack")
    return [interp.index_value(t, k) for k in range(i, j + 1)]

def tbl_sort(interp, args):
    t = check_table(interp, b"table.sort", args, 1)
    comp = None
    if len(args) > 1 and args[1] is not None:
        comp = args[1]
        if lua_type(comp) != "function":
            arg_error(interp, b"table.sort", 2, ("function expected, got %s" % lua_type(comp)).encode())
    n = _len_of(interp, t)
    arr = [interp.index_value(t, i) for i in range(1, n + 1)]
    import functools
    def cmpfn(a, b):
        if comp is not None:
            r1 = interp.call_value(comp, [a, b])
            less = truthy(r1[0] if r1 else None)
            r2 = interp.call_value(comp, [b, a])
            greater = truthy(r2[0] if r2 else None)
            if less and greater:
                interp.lib_error(b"invalid order function for sorting")
            return -1 if less else (1 if greater else 0)
        else:
            less = interp.compare_op(b"<", a, b)
            if less:
                return -1
            gt = interp.compare_op(b"<", b, a)
            return 1 if gt else 0
    arr.sort(key=functools.cmp_to_key(cmpfn))
    for i, v in enumerate(arr):
        interp.set_index(t, i + 1, v)
    return []

TABLE_LIB = {
    b"concat": tbl_concat, b"create": tbl_create, b"insert": tbl_insert,
    b"move": tbl_move, b"pack": tbl_pack, b"remove": tbl_remove,
    b"sort": tbl_sort, b"unpack": tbl_unpack,
}

# ---------------- math library ----------------

class _Xoshiro:
    def __init__(self):
        import random as _r
        # initial state from system entropy/time like Lua default
        n1 = int(time.time()) & 0xffffffff
        n2 = (os.getpid() if hasattr(os, "getpid") else 0) & 0xffffffff
        try:
            rnd = os.urandom(16)
            n1 = int.from_bytes(rnd[:8], "little")
            n2 = int.from_bytes(rnd[8:], "little")
        except Exception:
            pass
        self.s = [0, 0, 0, 0]
        self._seed_vals = (wrap_int(n1), wrap_int(n2))
        self.reseed(n1, n2)
    def reseed(self, n1, n2):
        M = MASK64
        PHI = 0x9e3779b97f4a7c15
        # splitmix-like expansion (approximation of Lua's seeding)
        s = (n1 & M)
        out = []
        state = s ^ (n2 & M)
        for i in range(4):
            state = (state + PHI) & M
            z = state
            z = ((z ^ (z >> 30)) * 0xbf58476d1ce4e5b9) & M
            z = ((z ^ (z >> 27)) * 0x94d049bb133111eb) & M
            out.append(z ^ (z >> 31))
        self.s = out
        for _ in range(16):
            self.next()
    def next(self):
        M = MASK64
        s = self.s
        result = (((s[1] * 5) & M) << 7 | ((s[1] * 5) & M) >> 57) & M
        result = (result * 9) & M
        t = (s[1] << 17) & M
        s[2] ^= s[0]
        s[3] ^= s[1]
        s[1] ^= s[2]
        s[0] ^= s[3]
        s[2] ^= t
        s[3] = ((s[3] << 45) | (s[3] >> 19)) & M
        return result

def _rng(interp):
    r = getattr(interp, "_rng_obj", None)
    if r is None:
        r = _Xoshiro()
        interp._rng_obj = r
    return r

def _math1(fn, name):
    def f(interp, args):
        x = check_number(interp, b"math." + name, args, 1)
        return [fn(x)]
    return f

def math_abs(interp, args):
    x = check_number(interp, b"math.abs", args, 1)
    if type(x) is int:
        return [wrap_int(abs(x)) if x != INT_MIN else INT_MIN]
    return [abs(x)]

def _floor_ceil(is_floor, name):
    def f(interp, args):
        x = check_number(interp, b"math." + name, args, 1)
        if type(x) is int:
            return [x]
        v = math.floor(x) if is_floor else math.ceil(x)
        if math.isnan(v) or math.isinf(v):
            return [v]
        fv = float(v)
        iv = to_integer_value(fv)
        return [iv if iv is not None else fv]
    return f

def math_atan(interp, args):
    y = check_number(interp, b"math.atan", args, 1)
    x = opt_number(interp, b"math.atan", args, 2, 1.0)
    return [math.atan2(float(y), float(x))]

def math_log(interp, args):
    x = check_number(interp, b"math.log", args, 1)
    fx = float(x)
    if len(args) > 1 and args[1] is not None:
        base = float(check_number(interp, b"math.log", args, 2))
        if base == 2.0:
            try: return [math.log2(fx)]
            except ValueError: return [float("nan")]
        if base == 10.0:
            try: return [math.log10(fx)]
            except ValueError: return [float("nan")]
        try:
            return [math.log(fx) / math.log(base)]
        except ValueError:
            return [float("nan")]
    try:
        return [math.log(fx)]
    except ValueError:
        return [float("nan")] if fx < 0 else [-math.inf]

def math_fmod(interp, args):
    x = check_number(interp, b"math.fmod", args, 1)
    y = check_number(interp, b"math.fmod", args, 2)
    if type(x) is int and type(y) is int:
        if y == 0:
            arg_error(interp, b"math.fmod", 2, b"zero")
        # C fmod for ints == truncated remainder
        r = abs(x) % abs(y)
        return [-r if x < 0 else r]
    fx, fy = float(x), float(y)
    try:
        return [math.fmod(fx, fy)]
    except ValueError:
        return [float("nan")]

def math_modf(interp, args):
    x = check_number(interp, b"math.modf", args, 1)
    if type(x) is int:
        return [x, 0.0]
    if math.isnan(x) or math.isinf(x):
        return [x, x]
    ip = math.trunc(x)
    frac = x - ip
    iv = to_integer_value(float(ip))
    return [iv if iv is not None else float(ip), frac]

def math_frexp(interp, args):
    x = check_number(interp, b"math.frexp", args, 1)
    m, e = math.frexp(float(x))
    return [m, e]

def math_ldexp(interp, args):
    x = check_number(interp, b"math.ldexp", args, 1)
    e = check_integer(interp, b"math.ldexp", args, 2)
    try:
        return [math.ldexp(float(x), e)]
    except OverflowError:
        return [math.copysign(math.inf, float(x))]

def _minmax(is_max, name):
    def f(interp, args):
        best = check_any(interp, b"math." + name, args, 1)
        for v in args[1:]:
            if is_max:
                if interp.compare_op(b"<", best, v):
                    best = v
            else:
                if interp.compare_op(b"<", v, best):
                    best = v
        return [best]
    return f

def math_random(interp, args):
    rng = _rng(interp)
    if not args or (len(args) == 1 and args[0] is None):
        return [(rng.next() >> 11) * (1.0 / (1 << 53))]
    if len(args) == 1:
        up = check_integer(interp, b"math.random", args, 1)
        if up == 0:
            return [wrap_int(rng.next())]
        lo, hi = 1, up
    else:
        lo = check_integer(interp, b"math.random", args, 1)
        hi = check_integer(interp, b"math.random", args, 2)
    if lo > hi:
        arg_error(interp, b"math.random", 1, b"interval is empty")
    # project
    span = (hi - lo) & MASK64  # range-1 as unsigned
    # Use rejection similar to Lua's project to avoid bias
    if span == MASK64:
        return [wrap_int(rng.next())]
    n = span  # we want result in [0, span]
    # Lua project(ran, n) returns value in [0,n] where n = up-low
    if n & (n + 1) == 0:
        return [wrap_int((rng.next() & n) + lo)]
    # limit = (2^64-1) / (n+1) * (n+1) ...
    # Compute using unsigned arithmetic:  limit = ~0 - (~0 % (n+1)) ... approximated by Lua algorithm below
    ran = rng.next()
    # Lua: unsigned limit = (MAX / (n+1)) * (n+1); while ran >= limit reroll ??? choose common formulation
    mod = n + 1
    limit = ((1 << 64) // mod) * mod
    while ran >= limit:
        ran = rng.next()
    return [wrap_int((ran % mod) + lo)]

def math_randomseed(interp, args):
    rng = _rng(interp)
    if not args or args[0] is None:
        # generate new seeds
        n1 = int.from_bytes(os.urandom(8), "little")
        n2 = int.from_bytes(os.urandom(8), "little")
        # Lua returns the two seed numbers used: first fits in 32 bits? observed large second
        # Use values similar: n1 as unsigned 32, n2 as signed 64
        n1_32 = n1 & 0xffffffff
        rng.reseed(n1, n2)
        rng._seed_vals = (n1_32, wrap_int(n2))
        return [n1_32, wrap_int(n2)]
    x = check_integer(interp, b"math.randomseed", args, 1)
    y = opt_integer(interp, b"math.randomseed", args, 2, 0)
    rng.reseed(x & MASK64, y & MASK64)
    rng._seed_vals = (x, y)
    return [x, y]

def math_tointeger(interp, args):
    if not args:
        return [None]
    v = args[0]
    if type(v) is bytes:
        v = parse_number_string(v)
        if v is None:
            return [None]
    if not is_number(v):
        return [None]
    return [to_integer_value(v)]

