# ---------------- coroutine ----------------

from lua_interp import CoroutineCloseSignal

def co_status(interp, co):
    if co.status == "dead":
        return b"dead"
    cur = interp.current_thread()
    if co is cur:
        return b"running"
    # walk resumed_by chain from current thread
    t = cur.resumed_by
    while t is not None:
        if t is co:
            return b"normal"
        t = t.resumed_by
    # co may be running on another Python thread and resumed_by current? if co has resumed_by not None but not current chain
    if co.resumed_by is not None and co.status == "running":
        return b"normal"
    return b"suspended"

def _co_main(interp, co):
    interp.thread_by_py[threading.get_ident()] = co
    with co.cond:
        while not co.has_resume:
            co.cond.wait()
        co.has_resume = False
        first_args = co.resume_args or []
        co.resume_args = None
    try:
        res = interp.call_value(co.func, list(first_args))
        kind = "return"
        vals = list(res)
        errv = None
        errobj = None
    except CoroutineCloseSignal:
        kind = "close"
        vals = []
        errv = None
        errobj = None
    except LuaError as e:
        kind = "error"
        vals = []
        errv = e.value
        errobj = e
    except RecursionError:
        kind = "error"
        vals = []
        errv = b"stack overflow"
        errobj = None
    co.status = "dead"
    with co.cond:
        co.result_kind = kind
        co.return_values = vals
        co.error_value = errv
        co.error_object = errobj
        co.has_result = True
        co.cond.notify_all()

def _co_resume_internal(interp, co, args_vals, closing=False):
    cur = interp.current_thread()
    with co.cond:
        co.resumed_by = cur
        co.resume_args = list(args_vals)
        if closing:
            co.close_requested = True
        else:
            co.close_requested = False
        if not co.started:
            if closing:
                # never started and closing: mark dead here
                co.status = "dead"
                co.result_kind = "close"
                co.return_values = []
                return ("close", [], None, None)
            co.started = True
            co.status = "running"
            co.has_resume = True
            t = threading.Thread(target=_co_main, args=(interp, co), daemon=True)
            co.pythread = t
            t.start()
        else:
            co.has_resume = True
            co.cond.notify_all()
        while not co.has_result:
            co.cond.wait()
        co.has_result = False
        kind = co.result_kind
        if kind == "yield":
            vals = co.yield_values
            co.yield_values = None
        elif kind == "error":
            vals = co.error_value
        else:
            vals = co.return_values
        errobj = co.error_object
        co.resumed_by = None
        if kind != "yield":
            co.status = "dead"
        return (kind, vals, co.error_value, errobj)

def co_create(interp, args):
    f = args[0] if args else None
    if f is None or lua_type(f) != "function":
        arg_error(interp, b"coroutine.create", 1,
                  ("function expected, got %s" % ("no value" if not args else lua_type(f))).encode())
    co = LuaThreadObj(func=f)
    return [co]

def co_resume(interp, args):
    co = check_thread(interp, b"coroutine.resume", args, 1)
    st = co_status(interp, co)
    if st == b"dead":
        return [False, b"cannot resume dead coroutine"]
    if st != b"suspended":
        return [False, b"cannot resume non-suspended coroutine"]
    kind, vals, errv, errobj = _co_resume_internal(interp, co, args[1:])
    if kind == "error":
        return [False, _no_error_object(errv)]
    if kind == "close":
        return [True]
    return [True] + list(vals)

def co_yield(interp, args):
    cur = interp.current_thread()
    if cur.is_main or cur.resumed_by is None:
        interp.lib_error(b"attempt to yield from outside a coroutine")
    if cur.closing:
        raise interp.make_error(b"attempt to yield across a C-call boundary")
    co = cur
    with co.cond:
        co.yield_values = list(args)
        co.result_kind = "yield"
        co.has_result = True
        co.cond.notify_all()
        while not co.has_resume:
            co.cond.wait()
        co.has_resume = False
        if co.close_requested:
            co.closing = True
            raise CoroutineCloseSignal()
        vals = co.resume_args or []
        co.resume_args = None
        return list(vals)

def co_running(interp, args):
    cur = interp.current_thread()
    return [cur, cur.is_main]

def co_status_fn(interp, args):
    co = check_thread(interp, b"coroutine.status", args, 1)
    return [co_status(interp, co)]

def co_wrap(interp, args):
    f = args[0] if args else None
    if f is None or lua_type(f) != "function":
        arg_error(interp, b"coroutine.wrap", 1,
                  ("function expected, got %s" % ("no value" if not args else lua_type(f))).encode())
    co = LuaThreadObj(func=f)
    def wrapper(itp, wargs):
        st = co_status(itp, co)
        if st == b"dead":
            raise itp.make_error(b"cannot resume dead coroutine", False)
        if st != b"suspended":
            raise itp.make_error(b"cannot resume non-suspended coroutine", False)
        kind, vals, errv, errobj = _co_resume_internal(itp, co, wargs)
        if kind == "error":
            if errobj is not None:
                raise errobj
            raise itp.make_error(errv, True)
        if kind == "close":
            return []
        return list(vals)
    return [BuiltinFunction(b"coroutine.wrap_function", wrapper)]

def co_close(interp, args):
    co = check_thread(interp, b"coroutine.close", args, 1)
    if co.is_main:
        interp.lib_error(b"cannot close main thread")
    st = co_status(interp, co)
    if st == b"dead":
        return [True]
    if st == b"running":
        # closing itself: unwind this coroutine now
        co.closing = True
        raise CoroutineCloseSignal()
    if st == b"normal":
        interp.lib_error(b"cannot close a normal coroutine")
    # suspended
    if not co.started:
        co.status = "dead"
        return [True]
    kind, vals, errv, errobj = _co_resume_internal(interp, co, [], closing=True)
    if kind == "error":
        return [False, _no_error_object(errv)]
    return [True]

def co_isyieldable(interp, args):
    if args and args[0] is not None:
        co = check_thread(interp, b"coroutine.isyieldable", args, 1)
    else:
        co = interp.current_thread()
    if co.is_main:
        return [False]
    if co.status == "dead":
        return [False]
    return [True]

COROUTINE_LIB = {
    b"close": co_close, b"create": co_create, b"isyieldable": co_isyieldable,
    b"resume": co_resume, b"running": co_running, b"status": co_status_fn,
    b"wrap": co_wrap, b"yield": co_yield,
}

# ---------------- utf8 ----------------

def _utf8_decode(s, pos, lax=False):
    """Decode one codepoint at 0-based pos. Return (codepoint, length) or None."""
    if pos >= len(s):
        return None
    b0 = s[pos]
    if b0 < 0x80:
        return (b0, 1)
    # determine expected length and initial value/minimum
    if b0 < 0xc0:
        return None  # continuation as lead
    if b0 < 0xe0:
        need, val, minv = 1, b0 & 0x1f, 0x80
    elif b0 < 0xf0:
        need, val, minv = 2, b0 & 0x0f, 0x800
    elif b0 < 0xf8:
        need, val, minv = 3, b0 & 0x07, 0x10000
    elif b0 < 0xfc:
        need, val, minv = 4, b0 & 0x03, 0x200000
    elif b0 < 0xfe:
        need, val, minv = 5, b0 & 0x01, 0x4000000
    else:
        return None
    if pos + need >= len(s):
        return None
    for i in range(1, need + 1):
        cb = s[pos + i]
        if cb < 0x80 or cb > 0xbf:
            return None
        val = (val << 6) | (cb & 0x3f)
    if not lax and val < minv:
        # Lua default decode accepts overlong? utf8.len strict rejects? We'll treat overlong as invalid only when not lax
        return None
    if val > 0x7fffffff:
        return None
    return (val, need + 1)

def _utf8_decode_loose(s, pos):
    # decode accepting overlong forms (Lua default utf8 appears to accept CO etc? uses only continuation checks)
    return _utf8_decode(s, pos, lax=True)

def utf8_char(interp, args):
    out = bytearray()
    for i, a in enumerate(args):
        v = check_integer(interp, b"utf8.char", args, i + 1)
        if v < 0 or v > 0x7fffffff:
            arg_error(interp, b"utf8.char", i + 1, b"value out of range")
        out += encode_utf8(v)
    return [bytes(out)]

def utf8_codepoint(interp, args):
    s = check_string(interp, b"utf8.codepoint", args, 1)
    i = opt_integer(interp, b"utf8.codepoint", args, 2, 1)
    j = opt_integer(interp, b"utf8.codepoint", args, 3, i)
    lax = truthy(args[3]) if len(args) > 3 else False
    n = len(s)
    i = _slib._posrel(i, n)
    j = _slib._posrel(j, n)
    if i < 1:
        arg_error(interp, b"utf8.codepoint", 2, b"out of range")
    if j > n:
        arg_error(interp, b"utf8.codepoint", 3, b"out of range")
    out = []
    pos = i - 1
    end = j - 1
    while pos <= end:
        r = _utf8_decode_loose(s, pos) if not lax else _utf8_decode_loose(s, pos)
        # strictness: Lua codepoint with lax false rejects >0x10FFFF and surrogates?
        if r is None:
            interp.lib_error(b"invalid UTF-8 code")
        val, ln = r
        if not lax and (val > 0x10ffff or 0xd800 <= val <= 0xdfff):
            # observed utf8.char(0x110000) works, but codepoint reading it? default (before 5.5 lax param)
            # Lua historically did not check these constraints in codepoint.
            pass
        out.append(val)
        pos += ln
    return out

def utf8_len(interp, args):
    s = check_string(interp, b"utf8.len", args, 1)
    i = opt_integer(interp, b"utf8.len", args, 2, 1)
    j = opt_integer(interp, b"utf8.len", args, 3, -1)
    lax = truthy(args[3]) if len(args) > 3 else False
    n = len(s)
    i = _slib._posrel(i, n)
    j = _slib._posrel(j, n)
    if i < 1 or i > n + 1:
        arg_error(interp, b"utf8.len", 2, b"position out of bounds")
    if j < 0 or j > n:
        arg_error(interp, b"utf8.len", 3, b"position out of bounds")
    count = 0
    pos = i - 1
    end = j  # exclusive0 == j
    while pos < end:
        r = _utf8_decode(s, pos, lax=lax)
        # Without lax, Lua len is strict about values > 0x10FFFF? Historical: utf8.len also
        # fails on values > MAXUTF (0x7fffffff) only. Surrogates accepted.
        if r is None:
            # try loose to distinguish overlong: Lua's decode without lax rejects overlong & >0x10FFFF? 5.5 lax handling vague.
            return [None, pos + 1]
        val, ln = r
        if not lax and val > 0x10ffff:
            # Historically (?) utf8.len('\xf4\x90...') for 0x110000: Lua 5.4 returns 1? We'll not fail.
            pass
        count += 1
        pos += ln
    return [count]

def _utf8_char_bounds(s, pos):
    """Given a byte pos that is at/inside a char, return (start0, end0_inclusive, length_guess)
    by first stepping back over continuation bytes."""
    start = pos
    while start > 0 and 0x80 <= s[start] <= 0xbf:
        start -= 1
    if start >= len(s):
        return start, start - 1, 0
    b0 = s[start]
    if b0 < 0x80:
        ln = 1
    elif b0 < 0xe0:
        ln = 2
    elif b0 < 0xf0:
        ln = 3
    elif b0 < 0xf8:
        ln = 4
    elif b0 < 0xfc:
        ln = 5
    elif b0 < 0xfe:
        ln = 6
    else:
        ln = 1
    # Actual sequence may be truncated
    end = min(start + ln - 1, len(s) - 1)
    return start, end, ln

def utf8_offset(interp, args):
    s = check_string(interp, b"utf8.offset", args, 1)
    narg = check_integer(interp, b"utf8.offset", args, 2)
    i = opt_integer(interp, b"utf8.offset", args, 3, 1 if narg >= 0 else len(s) + 1)
    n = len(s)
    startpos = _slib._posrel(i, n)
    if startpos < 1 or startpos > n + 1:
        arg_error(interp, b"utf8.offset", 3, b"position out of bounds")
    pos = startpos - 1  # 0-based byte index; may == n
    # align to start of char containing pos (if pos==n, that is virtual empty char at n)
    if pos == n:
        cur_start = n
    else:
        cs, ce, _ = _utf8_char_bounds(s, pos)
        cur_start = cs
    if narg == 0:
        target = cur_start
    elif narg > 0:
        # go forward narg-1 additional characters from cur_start
        target = cur_start
        for _ in range(narg - 1):
            if target >= n:
                return [None]
            _, ce, _ = _utf8_char_bounds(s, target)
            target = ce + 1
    else:
        target = cur_start
        for _ in range(-narg):
            if target <= 0:
                return [None]
            cs, _, _ = _utf8_char_bounds(s, target - 1)
            target = cs
    if target >= n:
        return [n + 1, n + 1]
    cs, ce, _ = _utf8_char_bounds(s, target)
    return [cs + 1, ce + 1]

def utf8_codes(interp, args):
    s = check_string(interp, b"utf8.codes", args, 1)
    lax = truthy(args[1]) if len(args) > 1 else False
    state_str = s
    def iterator(itp, iargs):
        # control variable is last returned position (byte index, 1-based) or nil/0
        last = iargs[1] if len(iargs) > 1 else None
        if last is None:
            pos = 0
        else:
            lv = to_integer_value(last)
            pos = lv if lv is not None else 0
            # advance past char at last position:
            if pos > 0:
                r = _utf8_decode_loose(state_str, pos - 1)
                if r is None:
                    itp.lib_error(b"invalid UTF-8 code")
                pos = (pos - 1) + r[1]
            else:
                pos = 0
        if pos >= len(state_str):
            return []
        r = _utf8_decode_loose(state_str, pos)
        if r is None:
            itp.lib_error(b"invalid UTF-8 code")
        return [pos + 1, r[0]]
    it = BuiltinFunction(b"utf8.codes_iterator", iterator)
    return [it, s, 0]

UTF8_LIB = {
    b"char": utf8_char, b"codepoint": utf8_codepoint, b"codes": utf8_codes,
    b"len": utf8_len, b"offset": utf8_offset,
}
