    io = LuaTable()
    funcs = {
        b"close": io_close, b"flush": io_flush, b"input": io_input,
        b"lines": io_lines, b"open": io_open, b"output": io_output,
        b"popen": io_popen, b"read": io_read, b"tmpfile": io_tmpfile,
        b"type": io_type, b"write": io_write,
    }
    for k, fn in funcs.items():
        io.rawset(k, BuiltinFunction(b"io." + k, fn))
    io.rawset(b"stdin", stdin_f)
    io.rawset(b"stdout", stdout_f)
    io.rawset(b"stderr", stderr_f)
    return io

# ---------------- os ----------------

def os_clock(interp, args):
    return [time.process_time()]

def os_time_fn(interp, args):
    if not args or args[0] is None:
        return [int(time.time())]
    t = check_table(interp, b"os.time", args, 1)
    def field(name, required=False, default=None):
        v = interp.index_value(t, name)
        if v is None:
            if required:
                interp.lib_error(("field '%s' missing in date table" % name.decode()).encode())
            return default
        iv = to_integer_value(v) if is_number(v) else None
        if iv is None:
            # numeric string?
            if type(v) is bytes:
                nv = parse_number_string(v)
                iv = to_integer_value(nv) if nv is not None else None
            if iv is None:
                interp.lib_error(("field '%s' is not an integer" % name.decode()).encode())
        return iv
    year = field(b"year", True)
    month = field(b"month", True)
    day = field(b"day", True)
    hour = field(b"hour", False, 12)
    minute = field(b"min", False, 0)
    sec = field(b"sec", False, 0)
    isdst = interp.index_value(t, b"isdst")
    dst = -1
    if isdst is not None:
        dst = 1 if truthy(isdst) else 0
    try:
        tt = time.mktime((year, month, day, hour, minute, sec, 0, 0, dst))
    except (OverflowError, OSError, ValueError):
        return [None]
    return [int(tt)]

def os_difftime(interp, args):
    t2 = check_number(interp, b"os.difftime", args, 1)
    t1 = opt_number(interp, b"os.difftime", args, 2, 0)
    d = float(t2) - float(t1)
    # Lua returns float (?) difftime returns number (float in C). If both ints, Lua 5.5 returns float?
    return [d]

def _date_table(tm):
    t = LuaTable()
    t.rawset(b"year", tm.tm_year)
    t.rawset(b"month", tm.tm_mon)
    t.rawset(b"day", tm.tm_mday)
    t.rawset(b"hour", tm.tm_hour)
    t.rawset(b"min", tm.tm_min)
    t.rawset(b"sec", tm.tm_sec)
    t.rawset(b"wday", tm.tm_wday + 1)
    t.rawset(b"yday", tm.tm_yday)
    t.rawset(b"isdst", tm.tm_isdst > 0)
    return t

def _format_date(fmt, tm, timet):
    # Implement common strftime directives manually to match C locale "C"
    # Use Python strftime for most, but handle %z etc. Locale is C in original (unless setlocale changed).
    import calendar
    s = fmt.decode("latin1")
    out = []
    i = 0
    # Python's strftime for many codes: fallback manual mapping for weekday/month names in C locale
    # We'll translate using time.strftime, then it matches C locale on Linux
    try:
        formatted = time.strftime(s, tm)
        # Python strftime leaves unknown directives as-is? C returns maybe error for some; approximate.
        return formatted.encode("latin1")
    except Exception:
        return None

def os_date(interp, args):
    fmt = opt_string(interp, b"os.date", args, 1, b"%c")
    timet = None
    if len(args) > 1 and args[1] is not None:
        timet = check_integer(interp, b"os.date", args, 2)
    utc = False
    f = fmt
    if f.startswith(b"!"):
        utc = True
        f = f[1:]
    if timet is None:
        timet = int(time.time())
    try:
        tm = time.gmtime(timet) if utc else time.localtime(timet)
    except (OverflowError, OSError, ValueError):
        interp.lib_error(b"time result cannot be represented in this installation")
    if f == b"*t":
        return [_date_table(tm)]
    res = _format_date(f, tm, timet)
    if res is None:
        return [None]
    return [res]

def os_getenv(interp, args):
    name = check_string(interp, b"os.getenv", args, 1)
    # Must bypass variables that original -E strips? no, process env is same.
    v = os.environb.get(name) if hasattr(os, "environb") else None
    if v is None:
        v2 = os.environ.get(name.decode("latin1"))
        return [v2.encode("latin1") if v2 is not None else None]
    return [v]

def os_remove(interp, args):
    fn = check_string(interp, b"os.remove", args, 1)
    try:
        os.remove(_fname_bytes(fn))
        return [True]
    except IsADirectoryError:
        # C remove() on Linux removes empty directories
        try:
            os.rmdir(_fname_bytes(fn))
            return [True]
        except OSError as e:
            return [None, ("%s: %s" % (_fname_bytes(fn), _errno_msg(e))).encode("latin1"), e.errno]
    except OSError as e:
        return [None, ("%s: %s" % (_fname_bytes(fn), _errno_msg(e))).encode("latin1"), e.errno]

def os_rename(interp, args):
    old = check_string(interp, b"os.rename", args, 1)
    new = check_string(interp, b"os.rename", args, 2)
    try:
        os.rename(_fname_bytes(old), _fname_bytes(new))
        return [True]
    except OSError as e:
        return [None, ("%s: %s" % (_fname_bytes(old), _errno_msg(e))).encode("latin1"), e.errno]

def os_tmpname(interp, args):
    # Lua uses mkstemp-like name in /tmp like /tmp/lua_XXXXXX and file is created?
    # os.tmpname behavior: returns a name; on POSIX Lua uses mktemp and the file should not exist? It warns. Generate unique name
    import tempfile
    fd, path = tempfile.mkstemp(prefix="lua_")
    os.close(fd)
    os.unlink(path)
    return [os.fsencode(path)]

def os_execute(interp, args):
    if not args or args[0] is None:
        return [True]
    cmd = check_string(interp, b"os.execute", args, 1)
    # Flush Lua stdout before system call to keep ordering
    try:
        sys.stdout.buffer.flush()
    except Exception:
        pass
    rc = os.system(cmd.decode("latin1"))
    # os.system returns wait status encoded; decode
    if os.WIFEXITED(rc):
        code = os.WEXITSTATUS(rc)
        if code == 0:
            return [True, b"exit", 0]
        return [None, b"exit", code]
    if os.WIFSIGNALED(rc):
        sig = os.WTERMSIG(rc)
        return [None, b"signal", sig]
    return [None, b"exit", rc]

def os_exit(interp, args):
    code = 0
    close_state = False
    if args and args[0] is not None:
        if type(args[0]) is bool:
            code = 0 if args[0] else 1
        else:
            code = check_integer(interp, b"os.exit", args, 1)
    if len(args) > 1 and truthy(args[1]):
        # close state: run __gc/close of to-be-closed top? Lua closes state running GC finalizers.
        # Approximate: flush files
        for f in (interp.output_file, interp.input_file):
            try:
                if f and not f.closed and f.file not in (sys.stdout.buffer, sys.stdin.buffer):
                    f.file.flush()
            except Exception:
                pass
    try:
        sys.stdout.buffer.flush()
        sys.stderr.buffer.flush()
    except Exception:
        pass
    interp.exit_code = code
    # Raise a special exception caught at top-level? os._exit would bypass flushing of Python files opened by scripts.
    # Flush all open Lua files we can find? Python files opened via io will be flushed at process exit by GC maybe not if _exit.
    # We'll use SystemExit and let CLI translate; before that, flush tracked files (best effort: flush output/input + std streams)
    raise SystemExit(code)

def os_setlocale(interp, args):
    loc = None
    cat = b"all"
    if args and args[0] is not None:
        loc = check_string(interp, b"os.setlocale", args, 1)
    if len(args) > 1 and args[1] is not None:
        cat = check_string(interp, b"os.setlocale", args, 2)
        if cat not in (b"all", b"collate", b"ctype", b"monetary", b"numeric", b"time"):
            arg_error(interp, b"os.setlocale", 2, b"invalid option")
    import locale as _locale
    category_map = {
        b"all": _locale.LC_ALL, b"collate": _locale.LC_COLLATE, b"ctype": _locale.LC_CTYPE,
        b"monetary": _locale.LC_MONETARY, b"numeric": _locale.LC_NUMERIC, b"time": _locale.LC_TIME,
    }
    try:
        if loc is None:
            cur = _locale.setlocale(category_map[cat])
            return [cur.encode("latin1") if cur else None]
        if loc == b"":
            res = _locale.setlocale(category_map[cat], "")
        else:
            res = _locale.setlocale(category_map[cat], loc.decode("latin1"))
        return [res.encode("latin1")]
    except _locale.Error:
        return [None]

OS_LIB = {
    b"clock": os_clock, b"date": os_date, b"difftime": os_difftime,
    b"execute": os_execute, b"exit": os_exit, b"getenv": os_getenv,
    b"remove": os_remove, b"rename": os_rename, b"setlocale": os_setlocale,
    b"time": os_time_fn, b"tmpname": os_tmpname,
}
PY
"}

