import os
import sys
import time
import stat as _stat
from lua_values import *
from lua_libutil import *

def _fname_bytes(b):
    return os.fsdecode(b) if isinstance(b, bytes) else b

def _errno_msg(e):
    if hasattr(e, "strerror") and e.strerror:
        return e.strerror
    return str(e)

# ---------- file helpers ----------

def check_file(interp, full, args, n, default_current=None):
    if n - 1 >= len(args) or args[n - 1] is None:
        if default_current is not None:
            return default_current
        arg_error(interp, full, n, b"FILE* expected, got no value")
    v = args[n - 1]
    if not isinstance(v, FileUserData):
        arg_error(interp, full, n, ("FILE* expected, got %s" % lua_type(v)).encode())
    if v.closed:
        interp.lib_error(b"attempt to use a closed file")
    return v

def _file_error(interp, msg):
    interp.lib_error(msg)

def make_file(interp, fobj, name=b"", is_popen=False, mode=b"r"):
    f = FileUserData(fobj, name=name, is_popen=is_popen, mode=mode)
    f.metatable = interp.file_metatable
    return f

def _open_mode(modebytes, default="r"):
    if modebytes is None:
        return default
    m = modebytes.decode("latin1")
    # validate like fopen mode: starts with r/w/a -> with optional '+' and 'b'
    base = ""
    plus = False
    binary = False
    i = 0
    if i < len(m) and m[i] in "rwa":
        base = m[i]; i += 1
    else:
        return None
    # Lua also accepts trailing 'b'
    while i < len(m):
        if m[i] == "+":
            plus = True
        elif m[i] == "b":
            binary = True
        else:
            return None
        i += 1
    pymode = base + ("+" if plus else "") + "b"
    return pymode

# ---------- io functions (also file methods where first arg is file) ----------

def io_open(interp, args):
    fn = check_string(interp, b"io.open", args, 1)
    mode = opt_string(interp, b"io.open", args, 2, b"r")
    pymode = _open_mode(mode)
    if pymode is None:
        arg_error(interp, b"io.open", 2, b"invalid mode")
    try:
        f = open(_fname_bytes(fn), pymode)
    except OSError as e:
        return [None, ("%s: %s" % (_fname_bytes(fn), _errno_msg(e))).encode("latin1"), e.errno]
    return [make_file(interp, f, name=fn, mode=mode)]

def io_close(interp, args):
    # io.close() defaults to current output; file:close has file as arg1
    if not args or args[0] is None:
        f = interp.output_file
        if f is None or f.closed:
            return [True]
        # closing stdout default? Lua io_close closes default output and resets? It considers stdout protected? We'll close if not std handles
        return [_close_file_obj(interp, f)]
    v = args[0]
    if not isinstance(v, FileUserData):
        arg_error(interp, b"io.close", 1, ("FILE* expected, got %s" % lua_type(v)).encode())
    return [_close_file_obj(interp, v)]

def _close_file_obj(interp, f):
    if f.closed:
        interp.lib_error(b"attempt to use a closed file")
    try:
        if f.is_popen:
            # file is a Popen wrapper stored in .data
            proc = f.data
            try:
                if f.file:
                    f.file.close()
            except Exception:
                pass
            rc = proc.wait()
            f.closed = True
            if rc == 0:
                return True
            # Lua popen close returns exit status info: true/nil, "exit"/"signal", code
            if rc < 0:
                return _popen_close_result_tuple(False, rc)
            return _popen_close_result_tuple(False, rc)
        else:
            f.file.flush()
            # do not close standard streams' underlying fd? Lua fclose(stdout) would close, but keep fd for interpreter
            if f.file not in (sys.stdout.buffer, sys.stderr.buffer, sys.stdin.buffer):
                f.file.close()
            f.closed = True
            return True
    except OSError as e:
        return [None, _errno_msg(e).encode("latin1"), e.errno] if False else None

def _popen_close_result_tuple(ok, rc):
    # Marker object handled by io_close wrapper conversion; but simpler: return sentinel tuple
    return ("__popen_result__", ok, rc)

def io_flush(interp, args):
    if args and isinstance(args[0], FileUserData):
        f = check_file(interp, b"io.flush", args, 1)
        try:
            f.file.flush()
        except (OSError, ValueError) as e:
            return [None, _errno_msg(e).encode("latin1"), getattr(e, 'errno', None)]
        return [True]
    f = interp.output_file
    try:
        if f and not f.closed:
            f.file.flush()
    except Exception as e:
        return [None, _errno_msg(e).encode("latin1"), getattr(e, 'errno', None)]
    return [True]

def _resolve_file_or_name(interp, full, args, current, mode_for_name=b"r"):
    if not args or args[0] is None:
        return current, False
    v = args[0]
    if isinstance(v, FileUserData):
        if v.closed:
            interp.lib_error(b"attempt to use a closed file")
        return v, True
    if type(v) is bytes or is_number(v):
        fn = check_string(interp, full, args, 1)
        pymode = _open_mode(mode_for_name)
        try:
            fobj = open(_fname_bytes(fn), pymode)
        except OSError as e:
            interp.lib_error(("%s: %s" % (_fname_bytes(fn), _errno_msg(e))).encode("latin1"))
        return make_file(interp, fobj, name=fn, mode=mode_for_name), True
    arg_error(interp, full, 1, ("FILE* expected, got %s" % lua_type(v)).encode())

def io_input(interp, args):
    if not args or args[0] is None:
        return [interp.input_file]
    f, _ = _resolve_file_or_name(interp, b"io.input", args, interp.input_file, b"r")
    interp.input_file = f
    # registry _IO_input
    interp.registry.rawset(b"_IO_input", f)
    return [f]

def io_output(interp, args):
    if not args or args[0] is None:
        return [interp.output_file]
    f, _ = _resolve_file_or_name(interp, b"io.output", args, interp.output_file, b"w")
    interp.output_file = f
    interp.registry.rawset(b"_IO_output", f)
    return [f]

def io_tmpfile(interp, args):
    import tempfile
    try:
        fobj = tempfile.TemporaryFile(mode="w+b")
    except OSError as e:
        interp.lib_error(_errno_msg(e).encode("latin1"))
    return [make_file(interp, fobj, mode=b"w+")]

def io_popen(interp, args):
    cmd = check_string(interp, b"io.popen", args, 1)
    mode = opt_string(interp, b"io.popen", args, 2, b"r")
    if mode not in (b"r", b"w", b"rb", b"wb"):
        arg_error(interp, b"io.popen", 2, b"invalid mode")
    import subprocess
    try:
        if mode.startswith(b"r"):
            proc = subprocess.Popen(cmd.decode("latin1"), shell=True, stdout=subprocess.PIPE, stdin=subprocess.DEVNULL)
            fobj = proc.stdout
        else:
            proc = subprocess.Popen(cmd.decode("latin1"), shell=True, stdin=subprocess.PIPE, stdout=subprocess.DEVNULL)
            fobj = proc.stdin
    except OSError as e:
        return [None, _errno_msg(e).encode("latin1"), e.errno]
    f = make_file(interp, fobj, is_popen=True, mode=mode)
    f.data = proc
    return [f]

def io_type(interp, args):
    if not args:
        arg_error(interp, b"io.type", 1, b"value expected")
    v = args[0]
    if isinstance(v, FileUserData):
        return [b"closed file" if v.closed else b"file"]
    return [None]

# ---- reading ----

def _read_number(f):
    # reads a number from stream like fscanf %lf-ish; Lua skips spaces, reads numeric pattern
    # We need stream readahead char by char using .read(1)
    # Return number value or None (and whether EOF)
    buf = bytearray()
    eof = False
    # skip spaces
    pending = None
    while True:
        ch = f.file.read(1)
        if not ch:
            eof = True
            break
        if ch[0] in (32, 9, 10, 13, 11, 12):
            continue
        pending = ch
        break
    if pending is None:
        return None, eof
    buf += pending
    # read characters that could be part of number (Lua reads using fscanf which stops at invalid)
    # Accept sign, digits, '.', e/E, hex letters, p/P, x/X, signs after e/p
    while True:
        pos = f.file.tell() if hasattr(f.file, "tell") else None
        ch = f.file.read(1)
        if not ch:
            break
        c = ch[0]
        cur = bytes(buf)
        candidate = cur + ch
        # decide whether ch can extend a potential number: keep reading while candidate is a prefix of
        # a number token. Simple: accept alnum . and sign if last char in eEpP else stop.
        if (48 <= c <= 57) or (65 <= c <= 90) or (97 <= c <= 122) or c == 46 or c == 95:
            buf += ch
            continue
        if c in (43, 45) and len(buf) > 0 and chr(buf[-1]) in "eEpP":
            buf += ch
            continue
        # push back one char if seekable; else buffer it in file object data? For stdin/pipes, need peek storage.
        _unread(f, ch)
        break
    num = parse_number_string(bytes(buf))
    return num, eof

def _unread(f, data):
    # store pending bytes on file userdata (data slot used for popen proc; use separate attr via uservalue dict on interp)
    # We leverage a per-file pending buffer stored in a global WeakKey? File objects use __slots__; use f.file seek if possible.
    try:
        f.file.seek(-len(data), 1)
        return
    except Exception:
        pass
    # non-seekable: wrap pending buffer into an attribute through interpreter registry keyed by id(f)
    # Simplification: keep pending in a module-level dict
    _pending.setdefault(id(f), bytearray())
    _pending[id(f)] = bytearray(data) + _pending[id(f)]

_pending = {}

def _read_bytes(f, n):
    out = bytearray()
    pend = _pending.pop(id(f), None)
    if pend:
        out += pend[:n]
        if len(pend) > n:
            _pending[id(f)] = pend[n:]
        if len(out) >= n:
            return bytes(out[:n])
    try:
        data = f.file.read(n - len(out))
    except Exception:
        data = b""
    if data:
        out += data
    return bytes(out)

def _read_line(f, keep_eol=False):
    # read until \n or EOF
    out = bytearray()
    pend = _pending.pop(id(f), None)
    stream_chunks = []
    if pend:
        stream_chunks.append(bytes(pend))
    # read line byte-by-byte from underlying after pending handling
    # Build an iterator of bytes: first pending, then file.read(1) loops
    idx = 0
    chunks = stream_chunks
    while True:
        if chunks:
            chunk = chunks[0]
            nl = chunk.find(b"\n")
            if nl >= 0:
                out += chunk[:nl+1]
                rest = chunk[nl+1:]
                if rest:
                    _pending[id(f)] = bytearray(rest)
                break
            else:
                out += chunk
                chunks = []
                continue
        ch = f.file.read(1)
        if not ch:
            break
        out += ch
        if ch == b"\n":
            break
    if not out:
        return None
    if keep_eol:
        return bytes(out)
    if out.endswith(b"\n"):
        out = out[:-1]
        if out.endswith(b"\r"):
            out = out[:-1]
    return bytes(out)

def _read_all(f):
    out = bytearray()
    pend = _pending.pop(id(f), None)
    if pend:
        out += pend
    try:
        data = f.file.read()
    except Exception:
        data = b""
    if data:
        out += data
    return bytes(out)

def _do_read(interp, f, formats, first_arg_no, full):
    if not formats:
        formats = [b"l"]
    results = []
    for k, fmt in enumerate(formats):
        argno = first_arg_no + k
        if type(fmt) is bytes:
            if fmt == b"n":
                # read number; use peek-aware reader
                # For seekable / normal files, _read_number uses read(1) on underlying; pending handling n/a approx.
                num, eof = _read_number(f)
                results.append(num)
                if num is None:
                    break
            elif fmt == b"a":
                results.append(_read_all(f))
            elif fmt == b"l":
                r = _read_line(f, False)
                results.append(r)
                if r is None:
                    break
            elif fmt == b"L":
                r = _read_line(f, True)
                results.append(r)
                if r is None:
                    break
            else:
                arg_error(interp, full, argno, b"invalid format")
        elif is_number(fmt):
            nch = to_integer_value(fmt)
            if nch is None:
                arg_error(interp, full, argno, b"number has no integer representation")
            if nch < 0:
                arg_error(interp, full, argno, b"invalid count")
            if nch == 0:
                # test eof: try read 1 char and unread
                data = _read_bytes(f, 1)
                if not data:
                    results.append(None)
                    break
                _unread(f, data)
                results.append(b"")
            else:
                data = _read_bytes(f, nch)
                if not data:
                    results.append(None)
                    break
                results.append(data)
        else:
            arg_error(interp, full, argno, ("string expected, got %s" % lua_type(fmt)).encode())
    return results

def io_read(interp, args):
    # if first arg is file (method call), use it
    if args and isinstance(args[0], FileUserData):
        f = check_file(interp, b"file.read", args, 1)
        formats = []
        for a in args[1:]:
            formats.append(a)
        res = _do_read(interp, f, formats, 2, b"file.read")
        return res
    f = interp.input_file
    if f is None or f.closed:
        interp.lib_error(b"attempt to use a closed file")
