        return [interp.output_file]
    f, _ = _resolve_file_or_name(interp, b"io.output", args, interp.output_file, b"w")
    interp.output_file = f
    interp.registry.rawset(b"_IO_output", f)
    return [f]

def io_tmpfile(interp, args):
    import tempfile
    try:
        fobj = tempfile.TemporaryFile(mode="w+b")
    except OSError as e:
        interp.lib_error(_errno_msg(e).encode("latin1"))
    return [make_file(interp, fobj, mode=b"w+")]

def io_popen(interp, args):
    cmd = check_string(interp, b"io.popen", args, 1)
    mode = opt_string(interp, b"io.popen", args, 2, b"r")
    if mode not in (b"r", b"w", b"rb", b"wb"):
        arg_error(interp, b"io.popen", 2, b"invalid mode")
    import subprocess
    try:
        if mode.startswith(b"r"):
            proc = subprocess.Popen(cmd.decode("latin1"), shell=True, stdout=subprocess.PIPE, stdin=subprocess.DEVNULL)
            fobj = proc.stdout
        else:
            proc = subprocess.Popen(cmd.decode("latin1"), shell=True, stdin=subprocess.PIPE, stdout=subprocess.DEVNULL)
            fobj = proc.stdin
    except OSError as e:
        return [None, _errno_msg(e).encode("latin1"), e.errno]
    f = make_file(interp, fobj, is_popen=True, mode=mode)
    f.data = proc
    return [f]

def io_type(interp, args):
    if not args:
        arg_error(interp, b"io.type", 1, b"value expected")
    v = args[0]
    if isinstance(v, FileUserData):
        return [b"closed file" if v.closed else b"file"]
    return [None]

# ---- reading ----

def _read_number(f):
    # reads a number from stream like fscanf %lf-ish; Lua skips spaces, reads numeric pattern
    # We need stream readahead char by char using .read(1)
    # Return number value or None (and whether EOF)
    buf = bytearray()
    eof = False
    # skip spaces
    pending = None
    while True:
        ch = f.file.read(1)
        if not ch:
            eof = True
            break
        if ch[0] in (32, 9, 10, 13, 11, 12):
            continue
        pending = ch
        break
    if pending is None:
        return None, eof
    buf += pending
    # read characters that could be part of number (Lua reads using fscanf which stops at invalid)
    # Accept sign, digits, '.', e/E, hex letters, p/P, x/X, signs after e/p
    while True:
        pos = f.file.tell() if hasattr(f.file, "tell") else None
        ch = f.file.read(1)
        if not ch:
            break
        c = ch[0]
        cur = bytes(buf)
        candidate = cur + ch
        # decide whether ch can extend a potential number: keep reading while candidate is a prefix of
        # a number token. Simple: accept alnum . and sign if last char in eEpP else stop.
        if (48 <= c <= 57) or (65 <= c <= 90) or (97 <= c <= 122) or c == 46 or c == 95:
            buf += ch
            continue
        if c in (43, 45) and len(buf) > 0 and chr(buf[-1]) in "eEpP":
            buf += ch
            continue
        # push back one char if seekable; else buffer it in file object data? For stdin/pipes, need peek storage.
        _unread(f, ch)
        break
    num = parse_number_string(bytes(buf))
    return num, eof

def _unread(f, data):
    # store pending bytes on file userdata (data slot used for popen proc; use separate attr via uservalue dict on interp)
    # We leverage a per-file pending buffer stored in a global WeakKey? File objects use __slots__; use f.file seek if possible.
    try:
        f.file.seek(-len(data), 1)
        return
    except Exception:
        pass
    # non-seekable: wrap pending buffer into an attribute through interpreter registry keyed by id(f)
    # Simplification: keep pending in a module-level dict
    _pending.setdefault(id(f), bytearray())
    _pending[id(f)] = bytearray(data) + _pending[id(f)]

_pending = {}

def _read_bytes(f, n):
    out = bytearray()
    pend = _pending.pop(id(f), None)
    if pend:
        out += pend[:n]
        if len(pend) > n:
            _pending[id(f)] = pend[n:]
        if len(out) >= n:
            return bytes(out[:n])
    try:
        data = f.file.read(n - len(out))
    except Exception:
        data = b""
    if data:
        out += data
    return bytes(out)

def _read_line(f, keep_eol=False):
    # read until \n or EOF
    out = bytearray()
    pend = _pending.pop(id(f), None)
    stream_chunks = []
    if pend:
        stream_chunks.append(bytes(pend))
    # read line byte-by-byte from underlying after pending handling
    # Build an iterator of bytes: first pending, then file.read(1) loops
    idx = 0
    chunks = stream_chunks
    while True:
        if chunks:
            chunk = chunks[0]
            nl = chunk.find(b"\n")
            if nl >= 0:
                out += chunk[:nl+1]
                rest = chunk[nl+1:]
                if rest:
                    _pending[id(f)] = bytearray(rest)
                break
            else:
                out += chunk
                chunks = []
                continue
        ch = f.file.read(1)
        if not ch:
            break
        out += ch
        if ch == b"\n":
            break
    if not out:
        return None
    if keep_eol:
        return bytes(out)
    if out.endswith(b"\n"):
        out = out[:-1]
        if out.endswith(b"\r"):
            out = out[:-1]
    return bytes(out)

def _read_all(f):
    out = bytearray()
    pend = _pending.pop(id(f), None)
    if pend:
        out += pend
    try:
        data = f.file.read()
    except Exception:
        data = b""
    if data:
        out += data
    return bytes(out)

def _do_read(interp, f, formats, first_arg_no, full):
    if not formats:
        formats = [b"l"]
    results = []
    for k, fmt in enumerate(formats):
        argno = first_arg_no + k
        if type(fmt) is bytes:
            if fmt == b"n":
                # read number; use peek-aware reader
                # For seekable / normal files, _read_number uses read(1) on underlying; pending handling n/a approx.
                num, eof = _read_number(f)
                results.append(num)
                if num is None:
                    break
            elif fmt == b"a":
                results.append(_read_all(f))
            elif fmt == b"l":
                r = _read_line(f, False)
                results.append(r)
                if r is None:
                    break
            elif fmt == b"L":
                r = _read_line(f, True)
                results.append(r)
                if r is None:
                    break
            else:
                arg_error(interp, full, argno, b"invalid format")
        elif is_number(fmt):
            nch = to_integer_value(fmt)
            if nch is None:
                arg_error(interp, full, argno, b"number has no integer representation")
            if nch < 0:
                arg_error(interp, full, argno, b"invalid count")
            if nch == 0:
                # test eof: try read 1 char and unread
                data = _read_bytes(f, 1)
                if not data:
                    results.append(None)
                    break
                _unread(f, data)
                results.append(b"")
            else:
                data = _read_bytes(f, nch)
                if not data:
                    results.append(None)
                    break
                results.append(data)
        else:
            arg_error(interp, full, argno, ("string expected, got %s" % lua_type(fmt)).encode())
    return results

def io_read(interp, args):
    # if first arg is file (method call), use it
    if args and isinstance(args[0], FileUserData):
        f = check_file(interp, b"file.read", args, 1)
        formats = []
        for a in args[1:]:
            formats.append(a)
        res = _do_read(interp, f, formats, 2, b"file.read")
        return res
    f = interp.input_file
    if f is None or f.closed:
        interp.lib_error(b"attempt to use a closed file")
    return _do_read(interp, f, list(args), 1, b"io.read")

def file_read(interp, args):
    f = check_file(interp, b"file.read", args, 1)
    return _do_read(interp, f, list(args[1:]), 2, b"file.read")

def _do_write(interp, f, values, first_arg_no, full):
    for k, v in enumerate(values):
        if type(v) is bytes:
            data = v
        elif is_number(v):
            data = number_to_bytes(v)
        else:
            arg_error(interp, full, first_arg_no + k, ("string expected, got %s" % lua_type(v)).encode())
        try:
            f.file.write(data)
        except (OSError, ValueError) as e:
            return [None, _errno_msg(e).encode("latin1"), getattr(e, "errno", None)]
    # flush? Lua files are buffered by C; keep Python buffer (flush for stdout to maintain ordering in tests?)
    # For regular files, not flushing matches buffering but scripts that exit without close may still need data
    # at interpreter exit. Python closes files at exit only via GC. We'll flush regular files lazily at close/exit,
    # but stdout flush to keep interaction ordered.
    try:
        if f.file is sys.stdout.buffer:
            f.file.flush()
    except Exception:
        pass
    return [f]

def io_write(interp, args):
    if args and isinstance(args[0], FileUserData):
        f = check_file(interp, b"file.write", args, 1)
        return _do_write(interp, f, args[1:], 2, b"file.write")
    f = interp.output_file
    if f is None or f.closed:
        interp.lib_error(b"attempt to use a closed file")
    return _do_write(interp, f, list(args), 1, b"io.write")

def file_write(interp, args):
    f = check_file(interp, b"file.write", args, 1)
    return _do_write(interp, f, args[1:], 2, b"file.write")

def file_seek(interp, args):
    f = check_file(interp, b"file.seek", args, 1)
    whence = opt_string(interp, b"file.seek", args, 2, b"cur")
    offset = opt_integer(interp, b"file.seek", args, 3, 0)
    modes = {b"set": 0, b"cur": 1, b"end": 2}
    if whence not in modes:
        arg_error(interp, b"file.seek", 2, b"invalid option")
    # if reading a number left pending, drop pending
    _pending.pop(id(f), None)
    try:
        newpos = f.file.seek(offset, modes[whence])
        if newpos is None:
            newpos = f.file.tell()
    except (OSError, ValueError) as e:
        return [None, _errno_msg(e).encode("latin1"), getattr(e, "errno", None)]
    return [newpos]

def file_setvbuf(interp, args):
    f = check_file(interp, b"file.setvbuf", args, 1)
    mode = check_string(interp, b"file.setvbuf", args, 2)
    if mode not in (b"no", b"full", b"line"):
        arg_error(interp, b"file.setvbuf", 2, b"invalid option")
    if len(args) > 2:
        check_integer(interp, b"file.setvbuf", args, 3)
    return [True]

def _lines_iterator(interp, f, close_when_done, formats):
    # returns a builtin closure
    done = {"done": False}
    def it(itp, iargs):
        if done["done"]:
            return []
        if f.closed:
            itp.lib_error(b"attempt to use a closed file")
        res = _do_read(itp, f, list(formats), 2, b"file.lines")
        if not res or res[0] is None:
            done["done"] = True
            if close_when_done:
                try:
                    _close_file_obj(itp, f)
                except Exception:
                    pass
            return []
        return res
    return BuiltinFunction(b"file.lines_iterator", it)

def io_lines(interp, args):
    # io.lines([filename, formats...]) or file:lines(formats...)
    if args and isinstance(args[0], FileUserData):
        f = check_file(interp, b"file.lines", args, 1)
        formats = list(args[1:]) if len(args) > 1 else [b"l"]
        it = _lines_iterator(interp, f, False, formats)
        # Generic for closing value is the file itself? file:lines returns iterator, state, nil, file
        return [it, None, None, f]
    if not args or args[0] is None:
        f = interp.input_file
        formats = [b"l"]
        it = _lines_iterator(interp, f, False, formats)
        return [it, None, None, f]
    # filename
    if type(args[0]) is bytes or is_number(args[0]):
        fn = check_string(interp, b"io.lines", args, 1)
        try:
            fobj = open(_fname_bytes(fn), "rb")
        except OSError as e:
            interp.lib_error(("%s: %s" % (_fname_bytes(fn), _errno_msg(e))).encode("latin1"))
        f = make_file(interp, fobj, name=fn)
        formats = list(args[1:]) if len(args) > 1 else [b"l"]
        it = _lines_iterator(interp, f, True, formats)
        return [it, None, None, f]
    arg_error(interp, b"io.lines", 1, ("string expected, got %s" % lua_type(args[0])).encode())

def file_lines(interp, args):
    f = check_file(interp, b"file.lines", args, 1)
    formats = list(args[1:]) if len(args) > 1 else [b"l"]
    it = _lines_iterator(interp, f, False, formats)
    return [it, None, None, f]

def file_close(interp, args):
    v = args[0] if args else None
    if not isinstance(v, FileUserData):
        arg_error(interp, b"file.close", 1, ("FILE* expected, got %s" % lua_type(v)).encode())
    r = _close_file_obj(interp, v)
    if isinstance(r, tuple) and r and r[0] == "__popen_result__":
        _, ok, rc = r
        if rc < 0:
            return [None, b"signal", -rc]
        return [None, b"exit", rc]
    return [r]

def file_flush(interp, args):
    f = check_file(interp, b"file.flush", args, 1)
    try:
        f.file.flush()
    except (OSError, ValueError) as e:
        return [None, _errno_msg(e).encode("latin1"), getattr(e, "errno", None)]
    return [True]

def file_tostring(interp, args):
    v = args[0]
    if v.closed:
        return [b"file (closed)"]
    return [b"file (0x%x)" % v.addr]

def init_io(interp):
    # file metatable
    methods = LuaTable()
    method_funcs = {
        b"close": file_close, b"flush": file_flush, b"lines": file_lines,
        b"read": file_read, b"seek": file_seek, b"setvbuf": file_setvbuf,
        b"write": file_write,
    }
    for k, fn in method_funcs.items():
        methods.rawset(k, BuiltinFunction(b"file." + k, fn))
    mt = LuaTable()
    mt.rawset(b"__index", methods)
    mt.rawset(b"__name", b"FILE*")
    mt.rawset(b"__tostring", BuiltinFunction(b"file.__tostring", file_tostring))
    mt.rawset(b"__close", BuiltinFunction(b"file.__close", lambda itp, a: file_close(itp, a)))
    mt.rawset(b"__gc", BuiltinFunction(b"file.__gc", lambda itp, a: (_close_file_obj(itp, a[0]) if a and isinstance(a[0], FileUserData) and not a[0].closed else True, [])))
    # The __gc lambda returns tuple; fix by defining proper
    def _gc(itp, a):
        if a and isinstance(a[0], FileUserData) and not a[0].closed:
            try:
                _close_file_obj(itp, a[0])
            except Exception:
                pass
        return []
    mt.rawset(b"__gc", BuiltinFunction(b"file.__gc", _gc))
    interp.file_metatable = mt
    interp.registry.rawset(b"FILE*", mt)

    stdin_f = make_file(interp, sys.stdin.buffer, mode=b"r")
    stdout_f = make_file(interp, sys.stdout.buffer, mode=b"w")
    stderr_f = make_file(interp, sys.stderr.buffer, mode=b"w")
    interp.stdin_file = stdin_f
    interp.stdout_file = stdout_f
    interp.stderr_file = stderr_f
    interp.input_file = stdin_f
    interp.output_file = stdout_f
    interp.registry.rawset(b"_IO_input", stdin_f)
    interp.registry.rawset(b"_IO_output", stdout_f)

    io = LuaTable()
    funcs = {
        b"close": io_close, b"flush": io_flush, b"input": io_input,
        b"lines": io_lines, b"open": io_open, b"output": io_output,
        b"popen": io_popen, b"read": io_read, b"tmpfile": io_tmpfile,
        b"type": io_type, b"write": io_write,
    }
    for k, fn in funcs.items():
        io.rawset(k, BuiltinFunction(b"io." + k, fn))
    io.rawset(b"stdin", stdin_f)
    io.rawset(b"stdout", stdout_f)
    io.rawset(b"stderr", stderr_f)
    return io

# ---------------- os ----------------

def os_clock(interp, args):
    return [time.process_time()]

def os_time_fn(interp, args):
    if not args or args[0] is None:
        return [int(time.time())]
    t = check_table(interp, b"os.time", args, 1)
    def field(name, required=False, default=None):
        v = interp.index_value(t, name)
        if v is None:
            if required:
                interp.lib_error(("field '%s' missing in date table" % name.decode()).encode())
            return default
        iv = to_integer_value(v) if is_number(v) else None
        if iv is None:
            # numeric string?
            if type(v) is bytes:
                nv = parse_number_string(v)
                iv = to_integer_value(nv) if nv is not None else None
            if iv is None:
                interp.lib_error(("field '%s' is not an integer" % name.decode()).encode())
        return iv
    year = field(b"year", True)
    month = field(b"month", True)
    day = field(b"day", True)
    hour = field(b"hour", False, 12)
    minute = field(b"min", False, 0)
    sec = field(b"sec", False, 0)
    isdst = interp.index_value(t, b"isdst")
    dst = -1
    if isdst is not None:
        dst = 1 if truthy(isdst) else 0
    try:
        tt = time.mktime((year, month, day, hour, minute, sec, 0, 0, dst))
    except (OverflowError, OSError, ValueError):
        return [None]
    return [int(tt)]

def os_difftime(interp, args):
    t2 = check_number(interp, b"os.difftime", args, 1)
    t1 = opt_number(interp, b"os.difftime", args, 2, 0)
    d = float(t2) - float(t1)
    # Lua returns float (?) difftime returns number (float in C). If both ints, Lua 5.5 returns float?
    return [d]

def _date_table(tm):
    t = LuaTable()
    t.rawset(b"year", tm.tm_year)
    t.rawset(b"month", tm.tm_mon)
    t.rawset(b"day", tm.tm_mday)
    t.rawset(b"hour", tm.tm_hour)
    t.rawset(b"min", tm.tm_min)
    t.rawset(b"sec", tm.tm_sec)
    t.rawset(b"wday", tm.tm_wday + 1)
    t.rawset(b"yday", tm.tm_yday)
    t.rawset(b"isdst", tm.tm_isdst > 0)
    return t

def _format_date(fmt, tm, timet):
    # Implement common strftime directives manually to match C locale "C"
    # Use Python strftime for most, but handle %z etc. Locale is C in original (unless setlocale changed).
    import calendar
    s = fmt.decode("latin1")
    out = []
    i = 0
    # Python's strftime for many codes: fallback manual mapping for weekday/month names in C locale
    # We'll translate using time.strftime, then it matches C locale on Linux
    try:
        formatted = time.strftime(s, tm)
        # Python strftime leaves unknown directives as-is? C returns maybe error for some; approximate.
        return formatted.encode("latin1")
    except Exception:
        return None

def os_date(interp, args):
    fmt = opt_string(interp, b"os.date", args, 1, b"%c")
    timet = None
    if len(args) > 1 and args[1] is not None:
        timet = check_integer(interp, b"os.date", args, 2)
    utc = False
    f = fmt
    if f.startswith(b"!"):
        utc = True
        f = f[1:]
    if timet is None:
        timet = int(time.time())
    try:
        tm = time.gmtime(timet) if utc else time.localtime(timet)
    except (OverflowError, OSError, ValueError):
        interp.lib_error(b"time result cannot be represented in this installation")
    if f == b"*t":
        return [_date_table(tm)]
    res = _format_date(f, tm, timet)
    if res is None:
        return [None]
    return [res]

def os_getenv(interp, args):
    name = check_string(interp, b"os.getenv", args, 1)
    # Must bypass variables that original -E strips? no, process env is same.
    v = os.environb.get(name) if hasattr(os, "environb") else None
    if v is None:
        v2 = os.environ.get(name.decode("latin1"))
        return [v2.encode("latin1") if v2 is not None else None]
    return [v]

def os_remove(interp, args):
    fn = check_string(interp, b"os.remove", args, 1)
    try:
        os.remove(_fname_bytes(fn))
        return [True]
    except IsADirectoryError:
        # C remove() on Linux removes empty directories
        try:
            os.rmdir(_fname_bytes(fn))
            return [True]
        except OSError as e:
            return [None, ("%s: %s" % (_fname_bytes(fn), _errno_msg(e))).encode("latin1"), e.errno]
    except OSError as e:
        return [None, ("%s: %s" % (_fname_bytes(fn), _errno_msg(e))).encode("latin1"), e.errno]

def os_rename(interp, args):
    old = check_string(interp, b"os.rename", args, 1)
    new = check_string(interp, b"os.rename", args, 2)
    try:
        os.rename(_fname_bytes(old), _fname_bytes(new))
        return [True]
    except OSError as e:
        return [None, ("%s: %s" % (_fname_bytes(old), _errno_msg(e))).encode("latin1"), e.errno]

def os_tmpname(interp, args):
    # Lua uses mkstemp-like name in /tmp like /tmp/lua_XXXXXX and file is created?
    # os.tmpname behavior: returns a name; on POSIX Lua uses mktemp and the file should not exist? It warns. Generate unique name
    import tempfile
    fd, path = tempfile.mkstemp(prefix="lua_")
    os.close(fd)
    os.unlink(path)
    return [os.fsencode(path)]

def os_execute(interp, args):
    if not args or args[0] is None:
        return [True]
    cmd = check_string(interp, b"os.execute", args, 1)
    # Flush Lua stdout before system call to keep ordering
    try:
        sys.stdout.buffer.flush()
    except Exception:
        pass
    rc = os.system(cmd.decode("latin1"))
    # os.system returns wait status encoded; decode
    if os.WIFEXITED(rc):
        code = os.WEXITSTATUS(rc)
        if code == 0:
            return [True, b"exit", 0]
        return [None, b"exit", code]
    if os.WIFSIGNALED(rc):
        sig = os.WTERMSIG(rc)
        return [None, b"signal", sig]
    return [None, b"exit", rc]

def os_exit(interp, args):
    code = 0
    close_state = False
    if args and args[0] is not None:
        if type(args[0]) is bool:
            code = 0 if args[0] else 1
        else:
            code = check_integer(interp, b"os.exit", args, 1)
    if len(args) > 1 and truthy(args[1]):
        # close state: run __gc/close of to-be-closed top? Lua closes state running GC finalizers.
        # Approximate: flush files
        for f in (interp.output_file, interp.input_file):
            try:
                if f and not f.closed and f.file not in (sys.stdout.buffer, sys.stdin.buffer):
                    f.file.flush()
            except Exception:
                pass
    try:
        sys.stdout.buffer.flush()
        sys.stderr.buffer.flush()
    except Exception:
        pass
    interp.exit_code = code
    # Raise a special exception caught at top-level? os._exit would bypass flushing of Python files opened by scripts.
