    lines = set()
    # Proto.linedefined is a line too? Lua activelines includes lines with code
    def walk(n):
        if isinstance(n, (tuple, list)):
            # AST node convention: (tag, line, ...)
            if len(n) >= 2 and isinstance(n[0], str) and type(n[1]) is int:
                lines.add(n[1])
                for x in n[2:]:
