def dbg_debug(interp, args):
    from lua_loader import load_chunk
    while True:
        try:
            sys.stdout.buffer.write(b"lua_debug> ")
            sys.stdout.buffer.flush()
        except Exception:
            pass
        line = sys.stdin.buffer.readline()
        if not line:
            break
        if line.rstrip(b"\r\n") == b"cont":
            break
        fn, err = load_chunk(interp, line, b"=stdin")
        if fn is None:
            try:
                sys.stderr.buffer.write(err + b"\n"); sys.stderr.buffer.flush()
            except Exception:
                pass
            continue
        try:
            interp.call_value(fn, [])
        except LuaError as e:
            v = e.value
            try:
                if type(v) is bytes:
                    sys.stderr.buffer.write(v + b"\n")
                else:
                    sys.stderr.buffer.write(b"(error object is a " + lua_type(v).encode() + b" value)\n")
                sys.stderr.buffer.flush()
            except Exception:
                pass
    return []

HOOK_EVENTS = {"call": 1, "return": 2, "line": 4, "count": 8, "tail call": 16}

def dbg_sethook(interp, args):
    full = b"debug.sethook"
    thread, offset = _parse_thread_arg(interp, full, args)
    hook = args[offset] if offset < len(args) else None
    if hook is None:
        thread.hook = None
        thread.hook_mask = 0
        thread.hook_count = 0
        return []
    if lua_type(hook) != "function":
        arg_error(interp, full, offset + 1, ("function expected, got %s" % lua_type(hook)).encode())
    mask = check_string(interp, full, args, offset + 2)
    count = opt_integer(interp, full, args, offset + 3, 0)
    m = 0
    for ch in mask:
        if ch == ord('c'):
            m |= 1
        elif ch == ord('r'):
            m |= 2
        elif ch == ord('l'):
            m |= 4
        else:
            arg_error(interp, full, offset + 2, b"invalid mask")
    thread.hook = hook
    thread.hook_mask = m
    thread.hook_count = count
    return []

def dbg_gethook(interp, args):
    thread, offset = _parse_thread_arg(interp, b"debug.gethook", args)
    if thread.hook is None:
        return [None]
    mask = b""
    if thread.hook_mask & 1: mask += b"c"
    if thread.hook_mask & 2: mask += b"r"
    if thread.hook_mask & 4: mask += b"l"
    return [thread.hook, mask, thread.hook_count]

DEBUG_LIB = {
    b"debug": dbg_debug, b"gethook": dbg_gethook, b"getinfo": dbg_getinfo,
    b"getlocal": dbg_getlocal, b"getmetatable": dbg_getmetatable,
