def _write_out(data):
    try:
        sys.stdout.buffer.write(data)
        sys.stdout.buffer.flush()
    except Exception:
        pass

def _write_err(data):
    try:
        sys.stderr.buffer.write(data)
        sys.stderr.buffer.flush()
    except Exception:
        pass

def _prog_bytes(argv0):
    return os.fsencode(argv0) if argv0 else b"lua"

class CLI:
    def __init__(self, argv):
        self.argv = argv
        self.progname = argv[0] if argv else "./executable"
        self.interp = Interpreter()
        self.interp.progname = _prog_bytes(self.progname)
        self.ignore_env = False
        self.script_index = None

    def print_usage_error(self, msg):
        p = _prog_bytes(self.progname)
        _write_err(p + b": " + msg + b"\nusage: " + p + USAGE_TAIL)

    def format_top_error(self, e):
        # e is LuaError
        val = e.value
        p = _prog_bytes(self.progname)
        if type(val) is bytes:
            msg = val
        elif is_number(val):
            msg = number_to_bytes(val)
        else:
            msg = b"(error object is a " + lua_type(val).encode() + b" value)"
            # __tostring handling in Lua msg handler: if object has __tostring metamethod string result use it? We'll try
            mt = self.interp.get_metafield(val, b"__tostring")
            if mt is not None:
                try:
                    s = self.interp.lua_tostring(val)
                    if type(s) is bytes:
                        msg = s
                except Exception:
                    pass
        tb = b""
        if e.snapshot is not None:
            tb = self.interp.format_traceback(e.snapshot, 0)
        out = p + b": " + msg + b"\n"
        if tb:
            out += tb + b"\n"
        return out

    def run_closure(self, fn, args_vals):
        """Run like lua.c docall/pcall from C: push a root C frame. Return LuaError or None, results"""
        th = self.interp.main_thread
        root = Frame(th)
        root.is_c = True
        root.what = "C"
        root.builtin = None
        root.call_name = None
        root.namewhat = ""
        th.frames.append(root)
        try:
            res = self.interp.call_value(fn, list(args_vals))
            return None, res
        except LuaError as e:
            return e, None
        finally:
            if th.frames and th.frames[-1] is root:
                th.frames.pop()
            elif root in th.frames:
                th.frames.remove(root)

    def do_chunk(self, data, source, args_vals, treat_as_file=False):
        if treat_as_file and not data.startswith(b"\x1b"):
            data = strip_shebang_bom(data)
        fn, err = load_chunk(self.interp, data, source, b"bt", None)
        if fn is None:
            # syntax error: top-level message is err (already located); no traceback
            _write_err(_prog_bytes(self.progname) + b": " + err + b"\n")
            return 1
        e, res = self.run_closure(fn, args_vals)
        if e is not None:
            _write_err(self.format_top_error(e))
            return 1
        return 0

    def do_string_top(self, code, name, args_vals=[]):
        return self.do_chunk(code, name, args_vals, treat_as_file=False)

    def create_arg_table(self, script_idx):
        argv = self.argv
        arg = LuaTable()
        if script_idx is None:
            # arg[0] is progname, negatives none? With only -e args, earlier observed arg[0] = './executable' when executing -e.
            arg.rawset(0, os.fsencode(argv[0]))
            # negative indices for options before? In lua.c createargtable: if script index == argc or <0 uses ... Let's mimic:
            # When no script, arg[0]=argv[0], and argv[i] for i>=1 mapped at i-1? Tests with -e show arg[-1] nil.
            # We'll keep just [0].
        else:
            arg.rawset(0, os.fsencode(argv[script_idx]))
            for i in range(script_idx + 1, len(argv)):
                arg.rawset(i - script_idx, os.fsencode(argv[i]))
            for i in range(script_idx):
                arg.rawset(i - script_idx, os.fsencode(argv[i]))
        self.interp.globals.rawset(b"arg", arg)
        return arg

    def handle_lua_init(self):
        if self.ignore_env:
            return 0
        init = os.environ.get("LUA_INIT_5_5")
        if init is None:
            init = os.environ.get("LUA_INIT")
        if init is None:
            return 0
        if init.startswith("@"):
            fname = init[1:]
            try:
                with open(fname, "rb") as f:
                    data = f.read()
            except OSError as e:
                # Lua dofile error format? lua_writestringerror "%s: %s" with progname and message from load
                msg = ("cannot open %s: %s" % (fname, e.strerror or str(e)))
                _write_err(_prog_bytes(self.progname) + b": " + msg.encode("latin1") + b"\n")
                return 1
            return self.do_chunk(data, os.fsencode("@" + fname), [], treat_as_file=True)
        else:
            return self.do_string_top(os.fsencode(init), b"=LUA_INIT", [])

    def run_interactive(self):
        interp = self.interp
        _write_out(VERSION_STR)
        is_tty = False
        try:
            is_tty = sys.stdin.isatty()
        except Exception:
            is_tty = False
        # If stdin is a tty, load readline for editing (input())
        use_readline = False
        if is_tty:
            try:
                import readline
                use_readline = True
            except Exception:
                use_readline = False

        def get_prompt(name, default):
            v = interp.globals.rawget(name)
            if type(v) is bytes:
                return v
            if v is not None:
                # lua prompts use lua_tostring on _PROMPT etc? if not string, conversion maybe
                try:
                    s = interp.lua_tostring(v)
                    if type(s) is bytes:
                        return s
                except Exception:
                    pass
            return default

        def read_line(prompt_bytes):
            prompt_str = prompt_bytes.decode("latin1")
            if is_tty and use_readline:
                try:
                    line = input(prompt_str)
                except EOFError:
                    _write_out(b"\n")
                    return None
                except KeyboardInterrupt:
                    _write_out(b"\n")
                    return b""
                return line.encode("latin1") + b"\n"
            else:
                _write_out(prompt_bytes)
                line = sys.stdin.buffer.readline()
                if not line:
                    _write_out(b"\n")
                    return None
                if not is_tty:
                    # emulate readline echo on pipes
                    _write_out(line if line.endswith(b"\n") else line)
                return line

        buffer = b""
        first_line_of_chunk = True
        while True:
            prompt = get_prompt(b"_PROMPT", b"> ") if first_line_of_chunk else get_prompt(b"_PROMPT2", b">> ")
            line = read_line(prompt)
            if line is None:
                if buffer:
                    # EOF in middle of incomplete chunk: report syntax error like original
                    # Try to load buffer and print error, then write prompt newline? Original showed error to stderr and stdout '>> > '
                    # It printed continuation prompt then a new first prompt then newline at EOF.
                    # Simulate by processing buffer as final chunk
                    self._repl_execute(buffer, is_eof=True)
                break
            if first_line_of_chunk:
                stripped = line.lstrip(b" ")
                if stripped.startswith(b"local ") or stripped.rstrip(b"\r\n") == b"local":
                    _write_err(b"warning: locals do not survive across lines in interactive mode\n")
            buffer += line
            # Attempt to load buffer as chunk: first try as expression? Logic:
            status = self._repl_try_load(buffer)
            if status == "incomplete":
                first_line_of_chunk = False
                continue
            buffer = b""
            first_line_of_chunk = True
        return 0

    def _repl_try_load(self, buffer):
        # Returns 'incomplete' if more input needed; else executes and returns 'done'
        interp = self.interp
        from lua_parser import parse_source, ParseError
        # If buffer contains only whitespace/comments -> execute as empty chunk (done)
        # First, lua REPL tries adding 'return ' in front if line doesn't start with ... logic:
        # Simplified: try parse as statement chunk; if that succeeds, but the chunk is a single expression statement parse would fail.
        # lua.c: it tries to compile as 'return <line>' first only if first non-space char isn't ';'??? Original behaviors:
        #  - "return 10,20" prints results
        #  - "10+20" prints result (so expression mode)
        #  - "= x+1" errors unexpected symbol near '=' (not expression mode prefix in 5.5)
        # lua.c implementation (from behavior): loadline tries to parse the input; if it's a return statement results are printed.
        # It also has logic: if first token is not a statement starter etc, treats as return.
        # We'll implement: strip spaces; if begins with 'return' as keyword, parse normally and print results if any.
        # Else try to parse as a statement chunk; if parse fails with incomplete markers, return incomplete.
        # If statement parse fails generically, try expression mode 'return '+buffer. If that succeeds execute/print.
        # If statement parse succeeds execute it.
        # However expressions like "print(1)" parse as statement and execute fine.
        # A bare expression "x+2" fails statement parse (syntax error near eof) but expression parse succeeds.
        def try_load(code):
            fn, err = load_chunk(interp, code, b"=stdin", b"t", None)
            return fn, err
        fn, err = try_load(buffer)
        if fn is not None:
            # execute statement chunk
            e, res = self.run_closure(fn, [])
            if e is not None:
                # in REPL, runtime errors print message (without progname prefix) + traceback to stderr
                val = e.value
                if type(val) is bytes:
                    msg = val
                elif is_number(val):
                    msg = number_to_bytes(val)
                else:
                    msg = b"(error object is a " + lua_type(val).encode() + b" value)"
                out = msg + b"\n"
                if e.snapshot:
                    out += interp.format_traceback(e.snapshot, 0) + b"\n"
                _write_err(out)
            else:
                # If the chunk explicitly returned values (return statement), print them.
                # We can detect textual 'return' at top-level start.
                stripped = buffer.lstrip()
                if stripped.startswith(b"return") and (len(stripped) == 6 or not (stripped[6:7].isalnum() or stripped[6:7] == b"_")):
                    if res:
                        self._repl_print_results(res)
            return "done"
        # load failed
        if self._is_incomplete(err):
            return "incomplete"
        # try as expression
        fn2, err2 = try_load(b"return " + buffer)
        if fn2 is not None:
            e, res = self.run_closure(fn2, [])
            if e is not None:
                val = e.value
                if type(val) is bytes:
                    msg = val
                elif is_number(val):
                    msg = number_to_bytes(val)
                else:
                    msg = b"(error object is a " + lua_type(val).encode() + b" value)"
                out = msg + b"\n"
                if e.snapshot:
                    out += interp.format_traceback(e.snapshot, 0) + b"\n"
                _write_err(out)
            else:
                if res:
                    self._repl_print_results(res)
            return "done"
        if self._is_incomplete(err2):
            return "incomplete"
        # report original statement error (stripped of source prefix? REPL errors shown as "stdin:1: ...")
        _write_err(err + b"\n")
        return "done"

    def _repl_execute(self, buffer, is_eof=False):
        fn, err = load_chunk(self.interp, buffer, b"=stdin", b"t", None)
        if fn is None:
            _write_err(err + b"\n")
            # after error at EOF original printed a new prompt: handled by caller loop ending? stdout had '>> > \n'
            # We emit the primary prompt then loop will terminate after additional read... To match, caller does one more read.
            # Simplified: write prompt
            prompt = self.interp.globals.rawget(b"_PROMPT")
            if type(prompt) is not bytes:
                prompt = b"> "
            _write_out(prompt)
            return
        self.run_closure(fn, [])

    def _repl_print_results(self, res):
        parts = []
        for v in res:
            s = self.interp.lua_tostring(v)
            parts.append(s if type(s) is bytes else number_to_bytes(s))
        _write_out(b"\t".join(parts) + b"\n")

    def _is_incomplete(self, err):
        if err is None:
            return False
        # Heuristics from Lua: error message contains '<eof>' near end.
        return b"<eof>" in err or b"unfinished" in err

    def main(self):
        argv = self.argv
        # First pass option parsing like lua.c collectargs: script is first non-option or after -- / -
        # Options can be after each other; -e/-l may have attached arg.
        args = []
        i = 1
        script = None
        script_args_start = None
        has_e = False
        has_v = False
        interactive = False
        # We will process parse -> list actions in order, but -v and -E/-W flags apply globally.
        actions = []  # list of (kind, value)
        status = 0
        while i < len(argv):
            a = argv[i]
            if script is not None:
                break
            if a == "--":
                i += 1
                if i < len(argv):
                    script = argv[i]
                    script_args_start = i
                break
            elif a == "-":
                script = a
                script_args_start = i
                break
            elif a == "-E":
                self.ignore_env = True
                actions.append(("E", None))
            elif a == "-W":
                actions.append(("W", None))
            elif a == "-v":
                has_v = True
                actions.append(("v", None))
            elif a == "-i":
                interactive = True
                has_v = True  # -i implies -v in lua.c (interactive shows version)
            elif a.startswith("-e"):
