                        self.print_usage_error(b"'-e' needs argument")
                        return 1
                    val = argv[i + 1]
                    i += 1
                else:
                    val = a[2:]
                actions.append(("e", val))
                has_e = True
            elif a.startswith("-l"):
                if a == "-l":
                    if i + 1 >= len(argv):
                        self.print_usage_error(b"'-l' needs argument")
                        return 1
                    val = argv[i + 1]
                    i += 1
                else:
                    val = a[2:]
                actions.append(("l", val))
            elif a.startswith("-") and a != "-":
                self.print_usage_error(("unrecognized option '%s'" % a).encode())
                return 1
            else:
                script = a
                script_args_start = i
                break
