                if "=" in val:
                    gname, modname = val.split("=", 1)
                    if gname == "":
                        gname = modname
                else:
                    modname = val
                    gname = val
                # require into global gname
                try:
                    res = b_require(self.interp, [os.fsencode(modname)])
                except LuaError as e:
                    _write_err(self.format_top_error(e))
                    return 1
