                    return 1
                except IsADirectoryError:
                    _write_err(_prog_bytes(self.progname) + b": cannot read " + os.fsencode(path) + b"\n")
                    return 1
                except PermissionError:
                    _write_err(_prog_bytes(self.progname) + b": cannot open " + os.fsencode(path) + b": Permission denied\n")
                    return 1
                except OSError as e:
                    _write_err(_prog_bytes(self.progname) + b": cannot open " + os.fsencode(path) + b": " + (e.strerror or str(e)).encode("latin1") + b"\n")
