                    data = sys.stdin.buffer.read()
                    if data:
                        rc = self.do_chunk(data, b"=stdin", [])
                        return rc
                    return 0
        if interactive:
            return self.run_interactive()
        return 0


def _run_in_thread(argv):
    cli = CLI(argv)
    rc = cli.main()
    # flush output files opened by scripts that remain open (like closing Lua state __gc)
    try:
        for f in getattr(cli.interp, "_lua_files", []):
            try:
                if not f.closed and f.file not in (sys.stdout.buffer, sys.stderr.buffer, sys.stdin.buffer):
                    try:
                        f.file.flush()
                        f.file.close()
                    except Exception:
                        pass
            except Exception:
                pass
    except Exception:
        pass
    try:
        sys.stdout.buffer.flush()
        sys.stderr.buffer.flush()
    except Exception:
        pass
    if cli.interp.exit_code is not None:
        rc = cli.interp.exit_code
    return rc


def main(argv=None):
    if argv is None:
        argv = sys.argv
    # Increase recursion limit and run in a thread with big stack for deep Lua recursion
    sys.setrecursionlimit(1000000)
    result = {"rc": 1}
    def target():
        try:
            result["rc"] = _run_in_thread(argv)
        except SystemExit as e:
            result["rc"] = int(e.code) if isinstance(e.code, int) else 0
        except KeyboardInterrupt:
            result["rc"] = 1
    stack_ok = False
    for size in (512 * 1024 * 1024, 256 * 1024 * 1024, 128 * 1024 * 1024, 64 * 1024 * 1024):
        try:
            threading.stack_size(size)
            stack_ok = True
            break
        except (ValueError, RuntimeError, OverflowError):
            continue
    t = threading.Thread(target=target)
    t.start()
    t.join()
    return result["rc"]
