    return isinstance(v, (LuaTable, LuaClosure, BuiltinFunction, UserData, LuaThreadObj))

class _Weak:
    __slots__ = ("ref",)
    def __init__(self, table_ref, nk, obj):
        def _cb(_ref, _tref=table_ref, _nk=nk):
            t = _tref()
            if t is not None:
                # remove only if entry still maps to a dead weak
                e = t.map.get(_nk)
                if e is not None:
