                    v_dead = isinstance(e[1], _Weak) and e[1].ref() is None
                    if k_dead or v_dead:
                        t.map.pop(_nk, None)
        self.ref = weakref.ref(obj, _cb)
    def get(self):
        return self.ref()

class LuaTable:
    __slots__ = ("map", "order", "metatable", "addr", "__weakref__", "_gc_marked", "_gc_called", "_gc_interp")
    def __init__(self):
        self.map = {}      # nk -> [key_or_Weak, value_or_Weak]
        self.order = []    # nks in insertion order (kept after deletion)
        self.metatable = None
        self.addr = next_addr()
        self._gc_marked = False
        self._gc_called = False
        self._gc_interp = None

    def __del__(self):
        try:
            if getattr(self, "_gc_marked", False) and not getattr(self, "_gc_called", False):
                interp = getattr(self, "_gc_interp", None)
                if interp is not None:
                    interp._queue_finalizer(self)
        except Exception:
            pass

    def _weak_flags(self):
        mt = self.metatable
        if mt is None:
            return (False, False)
        mode = mt.rawget(b"__mode") if isinstance(mt, LuaTable) else None
        if type(mode) is not bytes:
            return (False, False)
        return (b"k" in mode, b"v" in mode)

    def _wrap_key(self, nk, key):
        wk, wv = self._weak_flags()
        if wk and _is_collectable(key):
            return _Weak(weakref.ref(self), nk, key)
        return key

    def _wrap_val(self, nk, value):
        wk, wv = self._weak_flags()
        if wv and _is_collectable(value):
            return _Weak(weakref.ref(self), nk, value)
        return value

    @staticmethod
    def _unwrap(x):
        if isinstance(x, _Weak):
            return x.get()
        return x

    def refresh_weak_mode(self):
        """Materialize/convert entries according to current __mode.
        Called after setmetatable."""
        wk, wv = self._weak_flags()
        for nk, e in list(self.map.items()):
            key = self._unwrap(e[0])
            val = self._unwrap(e[1])
            if key is None or val is None:
                self.map.pop(nk, None)
                continue
            e[0] = self._wrap_key(nk, key) if wk else key
            e[1] = self._wrap_val(nk, val) if wv else val

    def rawget(self, key):
        if key is None:
            return None
        try:
            nk = normalize_key(key)
        except ValueError:
            return None
        e = self.map.get(nk)
        if e is None:
            return None
        if self._unwrap(e[0]) is None or self._unwrap(e[1]) is None:
            # stale weak entry (defensive; callbacks normally remove)
            if isinstance(e[0], _Weak) or isinstance(e[1], _Weak):
                self.map.pop(nk, None)
                return None
        return self._unwrap(e[1])

    def rawset(self, key, value):
        nk = normalize_key(key)  # raises ValueError
        if value is None:
            if nk in self.map:
                del self.map[nk]
            return
        e = self.map.get(nk)
        sk = storage_key(key)
        if e is None:
            self.map[nk] = [self._wrap_key(nk, sk), self._wrap_val(nk, value)]
            if nk not in self.order:
                self.order.append(nk)
        else:
            # keep original stored key (identity) but refresh weak wrapping per mode
            e[1] = self._wrap_val(nk, value)

    def get_int(self, i):
        e = self.map.get((1, i))
        if e is None:
            return None
        return self._unwrap(e[1])

    def border(self):
        n = 0
        while True:
            e = self.map.get((1, n + 1))
            if e is None or self._unwrap(e[1]) is None:
                break
            n += 1
        return n

    def _live_entry(self, nk):
        e = self.map.get(nk)
        if e is None:
            return None
        k = self._unwrap(e[0]); v = self._unwrap(e[1])
        if (isinstance(e[0], _Weak) and k is None) or (isinstance(e[1], _Weak) and v is None):
            self.map.pop(nk, None)
            return None
        return [k, v]

    def ordered_entries(self):
        ints = []
        for nk in list(self.map.keys()):
            if nk[0] == 1 and nk[1] >= 1:
                le = self._live_entry(nk)
                if le is not None:
                    ints.append((nk[1], le))
        ints.sort(key=lambda x: x[0])
        result = []
        for _, e in ints:
            result.append(e)
        pos_int_nks = set((1, i) for i, _ in ints)
        seen = set()
        for nk in self.order:
            if nk in pos_int_nks or nk in seen:
                continue
            seen.add(nk)
            le = self._live_entry(nk)
            if le is not None:
                result.append(le)
        for nk in list(self.map.keys()):
            if nk not in pos_int_nks and nk not in seen:
                le = self._live_entry(nk)
                if le is not None:
                    result.append(le)
        return result

    def lua_next(self, key):
        if key is None:
            entries = self.ordered_entries()
            if not entries:
                return None
            return (entries[0][0], entries[0][1])
        nk = normalize_key(key)
        entries = self.ordered_entries()
        for i, e in enumerate(entries):
            try:
                enk = normalize_key(e[0])
            except ValueError:
                continue
            if enk == nk:
                if i + 1 < len(entries):
                    ne = entries[i + 1]
                    return (ne[0], ne[1])
                return None
        if nk[0] == 1 and nk[1] >= 1 and nk in self.order:
            best = None
            for e in entries:
                ek = e[0]
                if type(ek) is int and ek > nk[1]:
                    if best is None or ek < best[0]:
